insert into exercises (id, version, category, knowledge_points, difficulty, estimated_seconds, format, context, stem, prompt, options, items, answer, alternatives, explanation, review_tags, provenance, status, grading_partial_credit, grading_order_tolerance, seeded_from, content_schema_version) values
  ('ex-arg-001', 1, 'argument-analysis', array['conclusion-identification']::text[], 2, 55, 'single-choice', null, '一次公交线网调整讨论被整理成四句话：①本市三条公交支线在过去半年里平均上客人数下降了四成。②因此，这三条支线应该改成了定点发车的区间巴士。③运营方补充说，支线沿路的几个居民点近两年陆续外迁。④另外，市里在去年年底开通了连接两个镇的新道路。这段话的结论是哪一句？', null, '[{"key":"A","text":"①，因为这一句给出了可以被核对的具体数字","errorType":"premise-misidentification","reason":"把带数字的事实句当成被支持的主张"},{"key":"B","text":"②，因为其他句子都在为它提供依据，它是被支持的那个主张"},{"key":"C","text":"③，因为这一句解释了上客人数下降的原因"},{"key":"D","text":"④，因为这一句提到的事情发生时间最近"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"结论是被其他句子支撑的那个主张。②带着“因此”，并且①③④都在为它提供理由，所以它是结论；句子带不带数字、时间新不新，都不是结论的标志。","steps":["先找提示词：“因此”“所以”“可见”后面通常是被支持的结论，“因为”“由于”后面通常是前提。","再做支持方向检验：把②拿去问“为什么”，能自然引出①和③作为回答；反过来问①“所以呢”，②才是回答，说明①服务于②。","检查④的作用：新道路开通改变了沿路的出行条件；无论把它读成前提还是背景，它都在为②这个建议提供理由，本身不是一条需要被证明的新主张。","排除两个常见误判：数字只说明可核对性，不说明主张地位；时间新近也不改变一句话在论证中的角色。"],"commonMistakes":[{"option":"A","errorType":"premise-misidentification","why":"精确数字容易显得像重点，但它在这里是被引用的观测结果，用来支持那个改动建议。"},{"option":"C","errorType":"missing-reasoning-step","why":"解释原因的句子是前提一侧的材料，把它当结论就漏掉了“解释服务于建议”这一层关系。"}],"takeaway":"找结论的办法：把每句话拿去问“它为什么成立”，能被其他句子回答的那句才是结论。"}'::jsonb, array['结论识别', '提示词', '支持方向']::text[], '原创题，场景取自公共交通调整讨论，用于训练区分结论句与前提句。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-arg-002', 1, 'argument-analysis', array['implicit-premise', 'conclusion-identification']::text[], 3, 75, 'single-choice', null, '同事在工作群里说：“小林这季度的方案全都通过了评审，所以他做需求分析的功底一定很扎实。”这个推理依赖但没有说出来的假设是哪一条？', null, '[{"key":"A","text":"方案能否通过评审，能够稳定地反映需求分析做得是否扎实"},{"key":"B","text":"小林做需求分析用的方法，从去年就已经开始用了"},{"key":"C","text":"评审专家打分时还会考虑需求分析以外的因素"},{"key":"D","text":"只要方案通过了评审，这个项目的最终结果就一定好","errorType":"conclusion-overreach","reason":"从通过评审又往前推到结果好，超出原论证范围"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"原论证从“方案全过”跳到“需求分析扎实”，中间依赖一条未被说出的对应关系：评审结果能反映需求分析质量。把它取反，推理就断了。","steps":["标出两半：前提是“方案全部通过评审”，结论是“需求分析功底扎实”，两者说的是不同的东西。","寻找桥梁：要让前者支持后者，必须假设通过与否与需求分析质量之间存在稳定联系。","用取反检验：假设这条联系不成立（评审主要看预算与排期），那么“全过”就推不出“扎实”，可见该假设确实必需。","对照 B：方法用了多久与推理能否成立无关，它只是补充背景，不是必需假设。","对照 C：它其实削弱原论证，而不是原论证所依赖的前提；对照 D：它把结论再往前推一步，属于额外的过度推广。"],"commonMistakes":[{"option":"D","errorType":"conclusion-overreach","why":"题干只走到“功底扎实”，把结论扩到“项目结果一定好”需要另外的前提，不是原论证依赖的那一条。"},{"option":"C","errorType":"premise-misidentification","why":"会削弱论证的条件不是论证所依赖的假设，两者方向相反，容易在这里认错。"}],"takeaway":"找隐含前提的诀窍是取反代入：把候选假设反过来说一遍，若论证随之塌掉，它就是那条未说出的前提。"}'::jsonb, array['隐含前提', '取反检验', '论证缺口']::text[], '原创题，场景取自职场评价讨论，专门训练用取反法定位隐含前提。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-arg-003', 1, 'argument-analysis', array['conclusion-identification', 'evidence-relevance']::text[], 4, 115, 'multi-choice', null, '关于是否延长中心馆开放时间的发言被整理成六句：①《本市阅读服务年报》显示，18 时后到馆的读者中上班族占 61%。②该年报纸质版为双色印刷，共 68 页。③馆长据此提出：应该把中心馆的闭馆时间从 18 时延长到 21 时。④现在的闭馆时间与上班族的空闲时间几乎重合，多数上班族只能周末到馆。⑤而周末到馆人数已经接近设计容量的 1.4 倍。⑥中心馆建于 2008 年，去年完成了外立面维修。下面关于每句话在这段论证中作用的说法，哪些是正确的？（选出所有正确的）', null, '[{"key":"A","text":"③是这段话的结论，①④⑤是支持它的三条前提"},{"key":"B","text":"②只是材料的外观信息，属于与结论无关的背景"},{"key":"C","text":"⑥说明馆舍条件允许延长开放时间，是支持结论的关键前提","errorType":"premise-misidentification","reason":"把建馆与维修年份当成对建议的支持"},{"key":"D","text":"如果把①里的 61% 改成 8%，④对③的支持力度不会变化","errorType":"missing-reasoning-step","reason":"漏掉了上班族比例决定闭馆后需求大小这一环"},{"key":"E","text":"凡是带数字的句子都自动成为论证的前提，所以②也是前提","errorType":"premise-misidentification","reason":"用“有数字”来判定句子的论证角色"}]'::jsonb, null, '{"keys":["A","B"]}'::jsonb, '[]'::jsonb, '{"summary":"判断一句话是前提还是背景，要看它为真时会不会让结论更可能成立：①④⑤都会，②⑥不会；②⑥只是让材料显得完整。","steps":["先定结论：③带“据此提出”，是一个建议，其余句子都在为它服务。","再看支持链：①给出需求集中在 18 时之后，④说明现有闭馆时间与该需求错开，⑤说明周末已接近容量，三者共同指向“延长到 21 时”。","用变动检验判定相关性：把①的 61% 改成 8%，闭馆后需求就不再集中，④对③的支持明显减弱，说明①确实相关。","检查②与⑥：页数与印刷方式、建馆年份与外立面维修，都不改变“延长开放时间是否值得做”的判断，属于背景信息。","纠正一条通用规则：带数字不等于在支持结论。数字只有在与被讨论的量同指向时才是前提，否则只是背景里的统计描述。"],"commonMistakes":[{"option":"C","errorType":"premise-misidentification","why":"题面没有给出馆舍条件与人力的任何信息，把建馆和维修年份读成支持，是自己补了一个说法。"},{"option":"D","errorType":"missing-reasoning-step","why":"断言“支持力度不变”之前，需要先说明上班族比例与闭馆后需求无关，而这一点恰好不成立。"},{"option":"E","errorType":"premise-misidentification","why":"判断角色靠的是支持方向，不是句子是否含数字；照这条规则，②也会被迫变成前提。"}],"takeaway":"区分前提与背景的可靠问法：这句话为真时，结论是否变得更可能？没变化就是背景。"}'::jsonb, array['前提识别', '背景信息', '证据相关性', '多选题']::text[], '原创题，场景取自公共图书馆开放时间讨论，用于练习前提与背景的角色划分。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-arg-004', 1, 'argument-analysis', array['evidence-relevance', 'implicit-premise']::text[], 2, 45, 'true-false', null, '判断下面这一说法是否正确：一条材料算不算某个结论的相关证据，主要看它为真时会不会让这个结论更可能（或更不可能）成立，而不是看它是不是数字、有没有出自权威机构。', null, null, null, '{"value":true}'::jsonb, '[]'::jsonb, '{"summary":"相关性由“能否改变结论的概率”决定；出处与形式只影响这条相关证据的分量大小，不能替代相关性判断。","steps":["把标准写成可操作的问题：假设这条材料为真，结论的成立可能性是否上升或下降。","举一个反例：官方发布的“去年该馆印刷页数”是权威数字，却与是否延长开放时间无关，说明权威与数字本身不产生相关性。","再举一个正例：没有单位的口头观察“周末门口排队很长”，若为真会提高结论可能性，属于相关证据，只是分量较轻。","补充一句：同一材料可以相关但很弱；判断要分两步，先问是否相关，再问强弱，两步不能合并。"],"commonMistakes":[{"errorType":"insufficient-evidence","why":"把“出自权威机构”当成相关性本身，跳过了它与结论之间是否有指向关系这一步。"},{"errorType":"missing-reasoning-step","why":"看到数字就直接采信，漏掉了核对“这个数字与结论所指的量是否同一个东西”。"}],"takeaway":"评估证据先问两句：它能改变结论的可能性吗？如果能，它有多强？"}'::jsonb, array['证据相关性', '判断标准', '证据强度']::text[], '原创题，针对“数字与权威自动等于证据”这一常见误解设计。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-arg-005', 1, 'argument-analysis', array['conclusion-identification', 'implicit-premise', 'evidence-relevance']::text[], 4, 130, 'short-answer', null, '运营负责人在周报里写：“我们客服的首次响应时长从 8 分钟降到了 3 分钟，所以客户满意度一定会回升。”请写三到四句话：这段话的结论是什么；它至少依赖一个什么样的未说出的前提；响应时长这条数据在什么条件下才算真正支持结论，在什么条件下不算。', null, null, null, '{"checkpoints":[{"id":"c1","label":"写出被支持的结论","keywords":["满意度","回升"],"weight":2,"required":true},{"id":"c2","label":"补出未说出的前提","keywords":["隐含前提","前提"],"weight":3,"required":true},{"id":"c3","label":"指出需要排除的同时变化","keywords":["同时发生","其他因素","价格"],"weight":2,"required":false},{"id":"c4","label":"说明数据不算支持的情形","keywords":["口径","同期","样本"],"weight":3,"required":true}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"这段话的结论是：客户满意度一定会回升。它依赖一个未说出的隐含前提：在响应时长之外，没有其他同时发生的变化会拉低满意度，例如价格上调、投诉处理变慢或产品本身出了新问题。要判断 8 分钟降到 3 分钟这条数据是否真正支持结论，要看它是否与满意度同口径、同期，并且满意度问卷的样本构成没有变化；如果这一期问卷题目或统计口径改过，或者用户结构变了，那么响应时长的改善就不足以支持“一定会回升”，最多支持“响应更快了”。"}'::jsonb, '[]'::jsonb, '{"summary":"该论证的结论是“满意度一定会回升”，它把一条内部指标当成了客户感受的可靠代理，并且默认其他条件不变。","steps":["分层：句子里能被直接核对的是“响应时长从 8 分钟降到 3 分钟”，需要被支持的是“满意度一定会回升”，后者才是结论。","补出隐含前提一：响应速度是客户满意的主要驱动因素，其他影响满意度的因素没有同时变化。","补出隐含前提二：这里的时长统计与实际客户感受之间有对应关系，例如统计口径、时段与工单类型可比。","判断支持条件：满意度问卷同口径同期结果确实上行、且没有价格或产品质量方面的负面变化时，这条数据才构成有力支持。","判断削弱条件：若口径变更、样本构成变化、或存在其他同时发生的不利因素，它至多支持“响应变快了”，支持不了“一定会回升”。"],"commonMistakes":[{"errorType":"correlation-as-causation","why":"把内部指标的改善直接当成客户感受变化的原因，跳过了两者之间的对应关系检验。"},{"errorType":"conclusion-overreach","why":"“一定会回升”是确定性表述，一条指标变化最多支持“可能改善”。"},{"errorType":"missing-reasoning-step","why":"没有说明响应时长如何转化为满意度，就把两个不同层面的指标连在了一起。"}],"takeaway":"看到“A 指标变好了，所以 B 一定会变好”，先把中间那条“A 是 B 的可靠代理”写出来再检查。"}'::jsonb, array['结论识别', '隐含前提', '指标代理', '简答题']::text[], '原创题，场景取自互联网运营周报，范文与要点关键词一一对应以便自动判分。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-arg-006', 1, 'argument-analysis', array['conclusion-identification', 'implicit-premise', 'evidence-relevance', 'subgoal-split']::text[], 3, 85, 'ordering', null, '你要完整分析一段四到五句的中文论证。按最合理的先后顺序排列下列步骤。', null, null, '[{"key":"s1","text":"找出候选结论：哪一句是其他句子要支撑的那个主张"},{"key":"s2","text":"先把明显属于背景的句子放到一边，例如时间、地点、材料外观、机构介绍"},{"key":"s3","text":"把支持结论的句子列成前提清单，检查它们的指向是否与结论一致"},{"key":"s4","text":"为推理补出未说出的隐含前提，并逐条判断它是否成立"},{"key":"s5","text":"最后评估结论强度：现有前提支持到“可能”还是“一定”"}]'::jsonb, '{"keys":["s1","s2","s3","s4","s5"]}'::jsonb, '[]'::jsonb, '{"summary":"论证分析要按依赖顺序推进：先定结论，才有前提与背景的分工；补齐隐含前提之后，才能谈结论能被支持到什么强度。","steps":["第一步定结论，是因为“某句是前提还是背景”只有在结论确定后才有意义；先做这一步可避免后面的分类反复改动。","第二步剔除背景句，把与结论指向无关的材料先隔离出去，减少干扰项。","第三步整理前提清单并核对指向：前提必须让结论更可能成立，方向相反的句子是削弱项而不是前提。","第四步补隐含前提，因为多数现实论证都有跳跃；用取反检验判断补出的假设是否必需。","第五步才评价强度，把“推理有效”与“前提为真”分开，最后给出结论的可信范围。"],"commonMistakes":[{"errorType":"premise-misidentification","why":"先挑句子再找结论，很容易把带数字的背景句误认成前提，导致整张清单错位。"},{"errorType":"missing-reasoning-step","why":"跳过补隐含前提就直接评价结论，等于在没有检查桥梁的情况下判定桥是稳的。"},{"errorType":"conclusion-overreach","why":"强度评估放在补前提之前，容易把仅被弱证据支持的说法读成确定结论。"}],"takeaway":"拆论证的顺序是：结论 → 剔除背景 → 列前提 → 补隐含前提 → 评强度。"}'::jsonb, array['论证结构', '步骤顺序', '拆解']::text[], '原创题，用于把论证分析的一般流程排成可复用的步骤。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-arg-007', 1, 'argument-analysis', array['conclusion-identification', 'implicit-premise', 'evidence-relevance', 'sample-size']::text[], 5, 175, 'open-response', null, '一篇网络文章写道：“我们调查了 200 位家长，其中 87% 认为孩子的作业太多。可见全国小学生的作业量都超出了标准。要减负，只要把作业总量砍掉一半就够了。”请分三步写下你的分析：这段话里有几个层次的结论，分别是什么；每个结论依赖哪些没有说出的前提；三条材料（200 位家长的样本、87% 这个比例、“砍掉一半”这一对策）各自能把结论支持到什么程度。', null, null, null, '{"scale":[{"score":0,"label":"只是复述","criteria":"把文章的话重新说一遍，没有区分结论、前提与证据三件事。"},{"score":1,"label":"找出一个结论","criteria":"能指出其中某一句是结论，但说不清另外两句在论证里扮演什么角色。"},{"score":2,"label":"分层并补前提","criteria":"能分出描述性结论与对策性结论两层，并为其中一层补出未说出的前提。"},{"score":3,"label":"评估支持强度","criteria":"进一步说明 200 位家长的样本怎样限制结论范围，以及“砍掉一半”还需要哪些证据。"},{"score":4,"label":"给出可区分检验","criteria":"还能提出一个能让“作业确实超量”与“家长主观感受偏强”给出不同预测的观察方式。"}],"guidance":"先把三句话分别标成结论、前提或背景；再逐层补出隐含前提，并用取反检验它们是否必需；最后写下每条结论最多能被支持到什么范围与强度。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"这段话有两个结论层：一是“全国小学生作业量都超出标准”，二是“把作业总量砍一半就够”。前者把家长主观判断换成了客观超标，后者还多加了一条对策性假设。","steps":["分层：87% 是调查结果（证据），“都超出标准”是描述性结论，“砍掉一半就够了”是对策性结论，三者地位不同。","补第一层的隐含前提：家长“认为太多”与作业量“超出标准”是同一件事，且这 200 位家长能代表全国。","指出概念替换：主观感受与客观标准是两个不同的量；要走到“超出标准”，需要作业时长、完成率、睡眠等可核对口径。","评估样本：200 位家长数量不大，抽样渠道与地区、学段分布未知，最多支持“这部分家长中多数觉得多”，推不到“全国都超”。","评估第二层：即使作业量确已超标，“砍一半就够”还假设作业量是负担的唯一来源、且不考虑教学质量与个体差异，需要额外证据支撑。"],"commonMistakes":[{"errorType":"hasty-generalization","why":"由 200 位家长的样本直接推广到全国小学生，样本量与代表性都不足。"},{"errorType":"equivocation","why":"把“家长认为太多”与“超出标准”当成同一个说法，用主观判断替换客观口径。"},{"errorType":"missing-reasoning-step","why":"从“负担重”直接跳到“砍一半就够”，没有说明负担的来源构成与对策的副作用。"},{"errorType":"conclusion-overreach","why":"“都”和“就够了”都是全称与唯一解表述，超出了三条材料能支撑的范围。"}],"takeaway":"分析多句论证时，先按“证据—描述性结论—对策性结论”分层，再逐层检查各自的前提。"}'::jsonb, array['论证分层', '隐含前提', '样本代表性', '开放题']::text[], '原创题，场景取自网络调查类文章，量表按常见回答层级设计，供自评与可选的模型反馈使用。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-arg-008', 1, 'argument-analysis', array['evidence-relevance', 'confounder', 'correlation-scenarios']::text[], 3, 70, 'single-choice', null, '论证：“学校把体育课从每周 2 节增加到 4 节之后，学生的肥胖率下降了 3 个百分点。因此，增加体育课能降低学生肥胖率。”为了检验这个论证，下列哪一条新信息最相关？', null, '[{"key":"A","text":"同一时期，该校是否还同步调整了营养餐、课间活动或作息时间"},{"key":"B","text":"学生和家长对这项调整表示满意的比例有多高","errorType":"premise-misidentification","reason":"把态度评价当成对因果检验的支持"},{"key":"C","text":"该校前年校服采购支出的变化情况"},{"key":"D","text":"本市媒体今年报道其他学校体育课的次数","errorType":"missing-reasoning-step","reason":"报道数量与本校肥胖率变化之间缺少可比数据这一环"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"原论证把“增加体育课”与“肥胖率下降”的先后共变直接当成因果。要检验它，最相关的信息是能提供替代解释的其他同期变化。","steps":["写出论证结构：干预（体育课 2 节变 4 节）在前，结果（肥胖率降 3 个百分点）在后，结论是前者导致后者。","列出竞争性解释：同期营养餐调整、作息变化、测量口径变化、年级构成变化，都可能同样产生这个下降。","据此判断相关性：能排除或确认这些竞争性解释的信息最相关，因此 A 直接改变结论的可信度。","检查 B：满意度与“肥胖率为什么下降”没有指向关系，它评价的是政策接受度而不是机制。","检查 C 与 D：校服支出与媒体报道量都不改变该校肥胖率变化的可能原因，属于无关背景；其中 D 连可比的对照数据都没有提供。"],"commonMistakes":[{"option":"B","errorType":"premise-misidentification","why":"把“大家支持这项调整”当成因果证据，混淆了接受度与效果来源这两类不同的问题。"},{"option":"D","errorType":"missing-reasoning-step","why":"想用外部信息核对，但媒体报道量既不是同类指标也不与本校数据可比，中间缺了可比对照这一环。"},{"errorType":"correlation-as-causation","why":"原论证的核心风险就在这里：先后共变可能有共同原因，必须靠同期其他变化来排除。"}],"takeaway":"判断一条证据是否相关，就问它能否改变“还有没有别的解释”；能改变原因的才相关。"}'::jsonb, array['证据相关性', '混淆因素', '因果检验']::text[], '原创题，场景取自校园体育安排调整，学校与数据均为虚构，不指向任何真实机构。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cau-001', 1, 'causal-reasoning', array['common-cause', 'causal-mechanism']::text[], 2, 55, 'single-choice', null, '某健康栏目引用一项调查：连续一年每天喝酸奶的成年人每年平均报告感冒 1.2 次，不喝酸奶的成年人平均 2.4 次。栏目据此写道“喝酸奶能预防感冒”。下列哪项最准确地指出了这个推论的问题？', null, '[{"key":"A","text":"两组人本来就是习惯不同的群体，喝酸奶的人可能同时保持着其他更利于减少感冒的习惯，调查没有排除这些差别"},{"key":"B","text":"1.2 次确实比 2.4 次少，所以结论只是话说得短了些，推理方向没有问题","errorType":"correlation-as-causation","reason":"把两组数字之间的差异直接当成因果效应"},{"key":"C","text":"只要再核对一次喝酸奶者的感冒次数是不是真的 1.2 次，就足以证明栏目的结论","errorType":"missing-reasoning-step","reason":"确认数字准确并不能补上从差异到因果的中间环节"},{"key":"D","text":"方向肯定被写反了：是不容易感冒的人才愿意每天喝酸奶","errorType":"conclusion-overreach","reason":"在没有证据的情况下断言因果方向必然相反"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"调查只给出两组人的结果差异，并没有给出把差异归到酸奶身上的机制，也没有排除“生活习惯更好”这一共同原因。","steps":["先记录事实：喝酸奶组平均 1.2 次，不喝组平均 2.4 次，两组差异存在。","把可能的解释列全：酸奶真的起作用；两组人在饮食、运动、就医、洗手等习惯上本就不同；样本自我选择造成的差别。","指出共同原因的作用：健康习惯同时影响是否喝酸奶和是否感冒，于是两组差异可以在酸奶无效的情况下出现。","说明需要什么才能定因果：能说明酸奶如何改变免疫指标的机制证据，或者随机分配喝与不喝的对照实验。"],"commonMistakes":[{"option":"B","errorType":"correlation-as-causation","why":"两组均值之差只说明差异存在，不说明差异的原因，直接把差异当效应是混淆相关与因果。"},{"option":"C","errorType":"missing-reasoning-step","why":"核实 1.2 次只是把前提坐实，从“少感冒”到“因为酸奶”中间还缺排除共同原因这一步。"},{"option":"D","errorType":"conclusion-overreach","why":"因果倒置只是一种可能，题目没有给出任何证据支持把它当成确定方向。"}],"takeaway":"看到“A 组比 B 组结果更好”，先问两组人除了 A 之外还有哪里不一样。"}'::jsonb, array['共同原因', '因果机制', '健康新闻']::text[], '原创题，场景取自健康类调查报道的常见表述，用于训练识别共同原因造成的组间差异。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cau-002', 1, 'causal-reasoning', array['confounder', 'causal-mechanism']::text[], 3, 70, 'single-choice', null, '一家学习机厂商宣传：报名暑期班的 200 名学生数学平均提高 12 分，其中 150 人在同期另外请了家教。要让“是学习机让学生提高了 12 分”这个说法站得住，最需要补充下列哪一项？', null, '[{"key":"A","text":"一组基础相当、同期既没请家教也没用学习机的学生的同阶段成绩变化"},{"key":"B","text":"150 人另请家教说明干预强度已经足够，不需要再设对照","errorType":"premise-misidentification","reason":"把干预强度当成可以省掉对照的理由"},{"key":"C","text":"把 12 分说成家教与学习机共同作用的结果，宣传就完整了","errorType":"missing-reasoning-step","reason":"没有任何拆分依据就把效果在两个因素之间分配"},{"key":"D","text":"平均提高 12 分，说明这 200 名学生每人至少提高了 12 分","errorType":"equivocation","reason":"把平均数偷换成了对每一个个体的断言"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"150 人同时请家教，使家教成为与学习机共存的混淆变量；不引入可比的对照组，就无法判断这 12 分该归给谁。","steps":["写出观察：200 人平均提高 12 分，其中 75% 同期另请家教。","识别混淆变量：家教与学习机同时施加在多数人身上，两者的效果在数据里混在一起。","确定缺什么：需要同基础、同阶段、既无家教也无学习机的对照变化量，才能把 12 分中的自然进步与真实增益分开。","排除错误做法：把 12 分随意分成两份没有依据；把平均数读成人人提高 12 分则偷换了概念。"],"commonMistakes":[{"option":"B","errorType":"premise-misidentification","why":"样本规模与干预强度都不解决归因问题，真正缺的是可比对照。"},{"option":"C","errorType":"missing-reasoning-step","why":"在没有对照的情况下，任何把效果在两因素之间分配的说法都是凭空补的一步。"},{"option":"D","errorType":"equivocation","why":"平均数描述整体水平，个别人可能提高很多、有人反而下降。"}],"takeaway":"两种干预同时施加时，先找只施加一种或都不施加的可比人群，再谈功劳归谁。"}'::jsonb, array['混淆变量', '教育产品宣传', '对照']::text[], '原创题，场景取自学习硬件的广告话术，用于训练识别同时施加的混淆变量。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cau-003', 1, 'causal-reasoning', array['confounder', 'common-cause', 'causal-mechanism']::text[], 4, 110, 'multi-choice', null, '某公司 3 月上线付费会员制，4 月会员用户复购率为 46%，非会员为 28%。同一时期，公司把满减优惠券只发放给会员。关于“会员制提高了复购率”，下列哪些说法是站得住的？（选出所有正确的）', null, '[{"key":"A","text":"46% 与 28% 的差距可能来自只有会员能领优惠券，而不是会员身份本身"},{"key":"B","text":"上线会员制在前、复购率升高在后，因此会员制一定提高了复购率","errorType":"correlation-as-causation","reason":"由时间先后与共变直接断定因果"},{"key":"C","text":"要判断会员制本身的作用，应比较领券条件相同的会员与非会员"},{"key":"D","text":"把 4 月会员的 46% 与 3 月全体用户的复购率相减，就能算出会员制造出的增量","errorType":"missing-reasoning-step","reason":"跨人群跨时间的两个数直接相减缺少可比性这一环"},{"key":"E","text":"这两个数字至少说明：在 4 月的记录里，会员与非会员的复购表现不同，至于原因还需另查"}]'::jsonb, null, '{"keys":["A","C","E"]}'::jsonb, '[]'::jsonb, '{"summary":"优惠券只发给会员，是一个与“是否会员”完全同向的混淆变量；描述性差距可以承认，因果结论必须先处理它。","steps":["记下三个事实：3 月上线会员制；4 月会员 46%、非会员 28%；优惠券只给会员。","把优惠券看成同时改变的因素：它既能提高复购，又与会员身份重合，所以 18 个百分点的差距无法直接归给会员制。","确定可比较的做法：把领券条件对齐（都领过或都没领），再比较会员与非会员。","分清描述与因果：A、C、E 都停在“差距存在但原因待查”或“怎样才可比”，B、D 则直接给出了没有依据的因果量。","指出 D 的另一处问题：3 月全体用户的复购率混合了后来成为会员的人，跨月跨人群相减不等于增量。"],"commonMistakes":[{"option":"B","errorType":"correlation-as-causation","why":"先后与共变是必要观察，但存在优惠券这一同期变化时不能直接说“一定”。"},{"option":"D","errorType":"missing-reasoning-step","why":"两个不可比的百分比相减之前，还需要人群对齐与时间对齐这两步。"}],"takeaway":"一项福利只给某类人时，这类人与其他类的差别就不再只属于那个标签。"}'::jsonb, array['混淆变量', '公司报表', '描述与因果']::text[], '原创题，场景来自电商会员制复盘数据，用于训练区分描述性差距与因果增量。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cau-004', 1, 'causal-reasoning', array['confounder', 'common-cause']::text[], 2, 45, 'true-false', null, 'A 市去年 9 月起在中心城区推行“工作日早晚高峰地铁延长 5 分钟”，当年 12 月公交准点率从 71% 升到 79%。已知同期该市在同一批路段新建了公交专用道，而公交专用道本身就能明显提升公交准点率。据此，“地铁延时政策带来了公交准点率上升”这一说法被削弱了。', null, null, null, '{"value":true}'::jsonb, '[]'::jsonb, '{"summary":"同期出现了另一个已知能提高准点率的原因，替代解释变强，原因果说法的可靠性因此下降，这就是被削弱。","steps":["确认原论证结构：政策在 9 月实施，指标在 12 月上升，于是归因于政策。","补入新信息：同一批路段新建了公交专用道，且专用道对口指标有直接作用。","比较两条路径：专用道直接改变公交行驶条件，地铁延时与公交准点率之间还需要额外环节。","加上时间因素：9 月到 12 月跨越季节变化，本身就是竞争性解释。","得出结论：新增同期原因使原说法更不可靠，因此“被削弱”为真；要说清各自贡献需要分路段对照。"],"commonMistakes":[{"errorType":"correlation-as-causation","why":"只按“政策在前、指标在后”的时间顺序归因，会认为补充信息不影响结论。"},{"errorType":"insufficient-evidence","why":"在已存在另一个已知原因的情况下仍坚持唯一归因，证据不足以排除替代解释。"}],"takeaway":"评估政策效果时，同一时间同一地点发生的其他变化同样要计入解释。"}'::jsonb, array['城市政策', '替代解释', '混淆变量']::text[], '原创题，场景取自城市交通政策的成效宣传，用于训练识别同期竞争性原因。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cau-005', 1, 'causal-reasoning', array['causal-mechanism', 'confounder', 'common-cause']::text[], 4, 130, 'short-answer', null, '一款记忆枕的电商页面显示：8,000 条评价中有 72% 提到“颈椎酸痛减轻”。厂家宣称这证明枕头通过改善睡姿缓解了颈椎疼痛。请用两三句话说明这个论证里最缺的是什么。', null, null, null, '{"checkpoints":[{"id":"c1","label":"缺少机制链条的证据","keywords":["机制","中间指标"],"weight":3,"required":false},{"id":"c2","label":"缺少对照与自发缓解的考虑","keywords":["对照","自然缓解"],"weight":3,"required":true},{"id":"c3","label":"指出评价人群存在自我选择","keywords":["自我选择","写评价"],"weight":2,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"这条宣传缺了三环。第一，缺少机制证据：要说清枕头如何改变睡姿、睡姿改变又如何减轻酸痛，需要能记录姿势的中间指标，而不是只引用评价文本。第二，缺少对照：颈椎酸痛本身会随时间自然缓解，也可能因同期热敷、运动或就医而减轻，没有对照组就分不清这些解释。第三，评价人群存在自我选择：会去写评价的多是感觉有效的人，72% 只是评价文本里的比例，不是所有使用者的缓解率。"}'::jsonb, '[]'::jsonb, '{"summary":"72% 是“愿意写评价的人”中的比例，不是使用者的缓解率；宣称中的机制链条也从未被测量。","steps":["先算清分母：8,000 条中有 72% 提到酸痛减轻，即约 5,760 条评价文本，而购买者总数与未写评价者数量都不知道。","补出机制要求：宣称里含有“枕头改变睡姿”和“睡姿改变减轻酸痛”两个环节，需要姿势测量与疼痛评分两处独立证据。","列出替代解释：酸痛的自然缓解、同期其他护理、期望效应（买了贵枕头的人更愿意报告好转）。","说明怎样区分：随机分组或至少与同期未换枕头的人群比较，并记录使用前后的疼痛评分变化幅度。"],"commonMistakes":[{"errorType":"base-rate-neglect","why":"只看提到缓解的评价比例，不看购买者中有多少根本没写评价、酸痛本身多久会自行缓解。"},{"errorType":"correlation-as-causation","why":"把“用了枕头”与“酸痛减轻”同时出现直接写成枕头导致减轻。"},{"errorType":"conclusion-overreach","why":"从评价文本跳到“通过改善睡姿缓解疼痛”这样带机制的确定结论。"}],"takeaway":"评价类数据先问两件事：分母是谁，以及宣称的中间环节有没有被测量。"}'::jsonb, array['消费评价', '因果机制', '自我选择']::text[], '原创题，场景取自电商商品页的评价话术，用于训练拆解带机制的因果宣称。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cau-006', 1, 'causal-reasoning', array['causal-mechanism', 'confounder', 'common-cause']::text[], 3, 90, 'ordering', null, '运营会上有人说：“改版首页那天之后，下单转化率从 2.1% 涨到 2.8%，就是改版带来的。”你要检验这个因果判断。请按最合理的先后顺序排列下列步骤。', null, null, '[{"key":"t1","text":"确认 2.1% 与 2.8% 的分子分母定义和统计时间段是否一致"},{"key":"t2","text":"查清改版生效的具体日期，并画出逐日转化率曲线"},{"key":"t3","text":"列出同期可能同时改变转化率的其他因素，例如投放渠道、价格、促销活动、竞品状况"},{"key":"t4","text":"设计可比对照，例如把未看到新首页的流量单独分桶，或按渠道分别比较改版前后"},{"key":"t5","text":"比较各解释给出的不同预测，写出暂时结论并标注仍不确定的部分"}]'::jsonb, '{"keys":["t1","t2","t3","t4","t5"]}'::jsonb, '[]'::jsonb, '{"summary":"检验一个归因结论的顺序是：先统一口径，再看时间线，再枚举竞争原因，再构造对照，最后按预测差异定结论。","steps":["口径不一致时两个百分比没有可比性，所以定义核对必须放在第一步。","逐日曲线能显示上升是从改版当天开始、还是改版前早已开始，这一步先于任何归因。","只有列出同期的其他变化，才知道对照要控制什么。","对照设计的目的是让改版这个因素能与其他因素分开变化，一次只改变它。","最后用“不同解释预测不同结果”来收敛结论，并保留不确定部分。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过口径与时间线直接做对照，等于在没有确认差异真实存在之前就去找原因。"},{"errorType":"correlation-as-causation","why":"把“改版之后上升”这一步直接当成结论，就会省略后面的对照设计。"}],"takeaway":"归因前先完成三步：数字可比、时间对齐、竞争原因列全。"}'::jsonb, array['因果归因', '步骤顺序', '公司报表']::text[], '原创题，场景来自互联网运营复盘会，用于训练把因果检验拆成有依赖顺序的步骤。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cau-007', 1, 'causal-reasoning', array['reverse-causation', 'common-cause', 'confounder']::text[], 5, 180, 'open-response', null, '一则新闻写道：“一项大型调查发现，有喝无糖饮料习惯的人体重指数平均高出 8%，可见无糖饮料让人发胖。”请评价这个说法：你能想到哪几种同样能说明这 8% 差异的因果解释？你更倾向哪一种，需要什么证据来区分？', null, null, null, '{"scale":[{"score":0,"label":"直接接受","criteria":"认为新闻的因果结论成立，不需要再补充任何信息。"},{"score":1,"label":"只表示怀疑","criteria":"觉得这个说法太武断，但说不出问题具体出在哪一步。"},{"score":2,"label":"给出至少两种解释","criteria":"能写出因果倒置、共同原因（如整体饮食或体重管理需求）等至少两种相容解释。"},{"score":3,"label":"指出指标口径问题","criteria":"还能说明体重指数高出 8% 是相对差还是绝对差、分组依据是否可靠，并把口径疑点写清楚。"},{"score":4,"label":"设计出可区分的证据","criteria":"进一步提出能区分上述解释的观察或实验，并交代自己最倾向哪种解释及其理由。"}],"guidance":"先按“同一条数据可有多种因果方向”列出至少两种解释，再检查 8% 这个指标怎么算出来的，最后写出一个能让不同解释给出不同预测的证据。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"同一体重差异至少容纳四种因果结构：饮料致胖、体重高者更依赖无糖饮料、两者被生活习惯共同推动、以及分组与口径造成的假差异。","steps":["写出观察事实：喝无糖饮料习惯者与不喝者的体重指数平均相差 8%。","解释一（正向因果）：无糖饮料影响食欲或代谢，从而推高体重。","解释二（因果倒置）：已经在控制体重的人更倾向换成无糖饮料，是体重状态改变了饮料选择。","解释三（共同原因）：整体饮食模式、含糖饮料总摄入量替换、体力活动水平同时决定两者。","解释四（口径与分组）：体重指数的相对差 8% 未说明绝对值，习惯分组靠自我报告，可能把偶尔饮用者归入习惯组。","给出区分办法：随机分配饮用者的干预试验；或纵向追踪，比较体重变化在前还是饮料更换在前；或控制总体饮食质量后再看组间差异是否仍在。"],"commonMistakes":[{"errorType":"correlation-as-causation","why":"把两组间的一次性差异直接读成饮料的效果。"},{"errorType":"false-dilemma","why":"只在“饮料让人发胖”和“完全无关”之间二选一，忽略了共同原因与口径问题。"},{"errorType":"conclusion-overreach","why":"由横断面调查跳到“可见”这种确定因果表述，超出了证据能支持的范围。"}],"takeaway":"同一组相关数据可以容纳多个因果方向，列出方向比急于选一个更重要。"}'::jsonb, array['因果倒置', '共同原因', '健康新闻', '开放题']::text[], '原创题，场景取自营养流行病学的媒体报道，量表按回答层级设计，供自评与可选的模型反馈使用。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cau-008', 1, 'causal-reasoning', array['reverse-causation', 'causal-mechanism']::text[], 4, 75, 'single-choice', null, '一家医院统计发现，手术中输入血量越多的病人，术后 30 天内死亡的比例越高。有人据此建议：“为降低死亡率，应当限制手术输血。”关于这个建议，下列哪项评价最准确？', null, '[{"key":"A","text":"病情更重、出血更多的病人才需要更多输血，观察到的正相关很可能把因果方向弄反了"},{"key":"B","text":"相关方向很明确，因此该建议应当直接采纳","errorType":"correlation-as-causation","reason":"把统计关联强度当成干预效果的依据"},{"key":"C","text":"只要把输血量减少一半，术后死亡率就会下降一半","errorType":"conclusion-overreach","reason":"把观察到的关联当作可线性外推的剂量效应"},{"key":"D","text":"问题出在样本量不够大，只要统计更多病人，这个建议就会成立","errorType":"premise-misidentification","reason":"把归因方向的问题误认成样本规模的问题"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"输血是随病情严重程度分配的，不是随机施加的；因此“输血多者死亡率高”更可能是病情决定了两个变量。","steps":["写出观察：输血量越高，术后 30 天死亡比例越高，这是一个正向关联。","追问谁决定输血量：出血量大、手术复杂、病情重的病人才被输入更多血。","识别因果结构：病情同时导致“多输血”和“高死亡风险”，输血与死亡之间只是被共同原因连起来。","评估干预含义：按观察关联去减少输血，等于把重症病人的必要处置也削减，风险反而上升；要判断输血的效果，需要在病情程度相同的病人内部比较。"],"commonMistakes":[{"option":"B","errorType":"correlation-as-causation","why":"关联的方向与强度都不能说明移除原因变量后结果会怎样变化。"},{"option":"C","errorType":"conclusion-overreach","why":"观察数据里的关联不是剂量效应曲线，减半外推没有任何依据。"},{"option":"D","errorType":"premise-misidentification","why":"扩大样本能缩小估计误差，却不会改变“病情同时决定两者”这一结构性问题。"}],"takeaway":"要评估“减少 X 会不会让 Y 变好”，先问是谁在决定 X。"}'::jsonb, array['因果倒置', '共同原因', '医疗数据']::text[], '原创题，场景取自医院手术质量统计的解读争议，用于训练区分治疗关联与治疗效果。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cond-001', 1, 'conditional-reasoning', array['modus-tollens', 'affirming-consequent']::text[], 2, 60, 'single-choice', null, '车间规定：如果一批零件通过终检，那么它会贴上绿色标签。现在发现 B 批次零件没有贴绿色标签。关于 B 批次，下列哪项结论是可靠的？', null, '[{"key":"A","text":"B 批次没有通过终检"},{"key":"B","text":"B 批次通过了终检，但标签漏贴了","errorType":"denying-antecedent","reason":"用可能例外来否定规则本身"},{"key":"C","text":"无法判断 B 批次是否通过终检"},{"key":"D","text":"B 批次贴了其他颜色标签"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[{"keys":["C"],"note":"如果允许怀疑规定本身可能被违反（例如标签漏贴），那么只能得出“按规则应判定未通过”，此解释同样合理。"}]'::jsonb, '{"summary":"把规定写成“若通过终检则贴绿标”。已知没有贴绿标，即否定了后件，可有效否定前件，得出没有通过终检。","steps":["符号化：P＝通过终检，Q＝贴绿色标签，规则为 若 P 则 Q。","已知事实是 非 Q（没有贴绿色标签）。","应用否定后件式（modus tollens）：若 P 则 Q；非 Q；所以非 P。","检查例外：只有在“规则可能不被执行”这一额外前提下，才需要保留无法判断的立场。"],"commonMistakes":[{"option":"B","errorType":"denying-antecedent","why":"把“可能存在的例外”当成否定推理规则的理由，方向弄反了。"},{"option":"D","errorType":"missing-reasoning-step","why":"题目没有给出任何关于其他颜色标签的信息，结论跳出了前提。"}],"takeaway":"否定后件可以否定前件；要得出可靠结论，先确认规则本身是否被假定严格执行。"}'::jsonb, array['否定后件式', '条件推理']::text[], '原创题，场景取自制造质检流程，用于训练否定后件式。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cond-002', 1, 'conditional-reasoning', array['affirming-consequent', 'modus-ponens']::text[], 2, 50, 'single-choice', null, '“如果这款产品降价，销量就会上升。”已知销量确实上升了。以下哪个判断最准确？', null, '[{"key":"A","text":"这款产品降价了","errorType":"affirming-consequent","reason":"由后件成立反推前件成立"},{"key":"B","text":"这款产品没有降价"},{"key":"C","text":"仅凭这两条信息，无法确定是否降价"},{"key":"D","text":"降价是销量上升的唯一原因","errorType":"correlation-as-causation","reason":"把一条充分条件当成唯一原因"}]'::jsonb, null, '{"keys":["C"]}'::jsonb, '[]'::jsonb, '{"summary":"“若降价则上升”只说明降价足以带来上升，并没有说上升只能来自降价。看到上升就断言降价，是肯定后件。","steps":["符号化：P＝降价，Q＝销量上升，规则为 若 P 则 Q。","已知 Q 成立。","肯定后件无效：Q 可能由广告、季节性需求、竞品缺货等造成。","同样不能否定前件，因此 A 与 B 都不成立，只能保留不确定。"],"commonMistakes":[{"option":"A","errorType":"affirming-consequent","why":"把充分条件误当成必要条件，认为结果出现就意味着原因出现。"},{"option":"D","errorType":"correlation-as-causation","why":"在没有排除其他原因时，把单一条件说成唯一原因。"}],"takeaway":"看到“如果……就……”，先问：这个条件是充分的还是必要的？"}'::jsonb, array['肯定后件', '条件推理', '事实与推测']::text[], '原创题，用于区分肯定前件与肯定后件两种推理。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cond-003', 1, 'conditional-reasoning', array['modus-ponens', 'modus-tollens', 'affirming-consequent', 'denying-antecedent']::text[], 3, 90, 'multi-choice', null, '已知规则：“只要申请资料齐全，系统就会自动受理。”下面哪些推理在形式上是有效的？（选出所有有效推理）', null, '[{"key":"A","text":"资料齐全，所以系统自动受理了"},{"key":"B","text":"系统没有自动受理，所以资料不齐全"},{"key":"C","text":"系统自动受理了，所以资料齐全","errorType":"affirming-consequent","reason":"肯定后件推出前件"},{"key":"D","text":"资料不齐全，所以系统不会自动受理","errorType":"denying-antecedent","reason":"否定前件推出否定后件"},{"key":"E","text":"资料不齐全，所以无法判断系统是否受理"}]'::jsonb, null, '{"keys":["A","B","E"]}'::jsonb, '[]'::jsonb, '{"summary":"“只要 P 就 Q”给出的是充分条件。有效形式只有肯定前件与否定后件；前件不成立时结论保持开放。","steps":["把规则写成 若 P（资料齐全）则 Q（自动受理），并确认 P 只是 Q 的充分条件。","A 是肯定前件式：P 成立则 Q 成立，有效。","B 是否定后件式：非 Q 则非 P，有效（与原命题等价的逆否命题）。","C 肯定后件推前件，无效，因为可能有其他原因触发受理。","D 否定前件推否定后件，无效；E 因此保留了正确的不确定性。"],"commonMistakes":[{"option":"C","errorType":"affirming-consequent","why":"把结果出现当成原因必然出现。"},{"option":"D","errorType":"denying-antecedent","why":"把“没资料就不受理”当成规则，但规则并没有这么说。"}],"takeaway":"四种形式里只有“肯定前件”和“否定后件”可靠，另外两种要看条件类型。"}'::jsonb, array['条件推理', '有效式', '易错']::text[], '原创题，覆盖条件推理四种常见形式。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cond-004', 1, 'conditional-reasoning', array['necessary-condition', 'only-if']::text[], 3, 45, 'true-false', null, '“只有年满 18 岁，才能参加这次投票。”这句话与“如果能参加这次投票，那么年满 18 岁”表达的是同一个条件关系。', null, null, null, '{"value":true}'::jsonb, '[]'::jsonb, '{"summary":"“只有 P 才 Q”把 P 说成 Q 的必要条件，等价于“若 Q 则 P”。两者真值条件一致。","steps":["识别句式：“只有 P 才 Q”中 P 是必要条件。","必要条件的标准翻译是 若 Q 则 P。","代入：P＝年满 18 岁，Q＝能参加投票，得到 若能参加投票则年满 18 岁。","对比两句，确认为同一条件关系。"],"commonMistakes":[{"errorType":"premise-misidentification","why":"把“只有”后面的内容误认成充分条件，方向就反了。"}],"takeaway":"“只要”带充分条件，“只有”带必要条件。"}'::jsonb, array['必要条件', '句式翻译', '条件推理']::text[], '原创题，针对“只有……才……”的翻译常见混淆点。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cond-005', 1, 'conditional-reasoning', array['implicit-premise', 'affirming-consequent']::text[], 4, 120, 'short-answer', null, '经理说：“上次上线新版本后投诉量上升了，所以新版本导致了投诉上升，必须先回滚。”请用两三句话指出这个推理中最需要先补充的信息。', null, null, null, '{"checkpoints":[{"id":"c1","label":"指出隐含前提","keywords":["隐含前提","前提"],"weight":3,"required":true},{"id":"c2","label":"给出另一种解释","keywords":["另一种","也可能是","其他解释"],"weight":2,"required":true},{"id":"c3","label":"提出可核对的数据","keywords":["对照","同期","数据"],"weight":2,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"这段话的隐含前提是：投诉量上升期间没有其他同时发生的变化。也可能是同期客服响应变慢或用户量增长造成的，这属于另一种解释。要区分它们，应调取上线前后同期的对照组数据，按渠道和时间段分别对照。"}'::jsonb, '[]'::jsonb, '{"summary":"该推理把“先后发生”当成“因果”，其成立依赖“没有其他同时变化”这一未说明前提。","steps":["把论证改写为：新版上线（P）之后投诉上升（Q），所以 P 导致 Q。","补出隐含前提：期间不存在其他能导致 Q 的变化。","列出替代解释：客服响应、用户规模、季节性、口径变化。","说明什么数据能区分这些解释：同期对照、分段统计、渠道拆分。"],"commonMistakes":[{"errorType":"correlation-as-causation","why":"仅凭时间先后与共变就断定因果方向。"},{"errorType":"insufficient-evidence","why":"没有对照组数据就选择不可逆的回滚动作。"}],"takeaway":"遇到“之后所以因为”，先找它没说出口的前提。"}'::jsonb, array['隐含前提', '条件推理', '因果']::text[], '原创题，场景来自互联网团队复盘会议。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cond-006', 1, 'conditional-reasoning', array['falsification', 'dependency-order']::text[], 3, 80, 'ordering', null, '你要检验“如果温度低于 0℃，这段水管就会爆裂”这一说法。按最合理的先后顺序排列下列步骤。', null, null, '[{"key":"s1","text":"明确结论里“温度低于 0℃”和“爆裂”各自的判定标准"},{"key":"s2","text":"列出除低温外还可能造成爆裂的因素"},{"key":"s3","text":"设计能控制这些因素、只改变温度的对比实验"},{"key":"s4","text":"记录结果并检查是否出现“低于 0℃ 但未爆裂”的情形"}]'::jsonb, '{"keys":["s1","s2","s3","s4"]}'::jsonb, '[]'::jsonb, '{"summary":"检验条件命题的正确顺序是：定义术语 → 枚举干扰因素 → 控制变量对比 → 用反例检验。","steps":["先固定测量口径，否则后面对比没有共同标准。","再列出可能的其他原因，才知道要控制什么。","然后设计一次只改变一个因素的对比。","最后专门寻找能推翻结论的情形，而不是只找支持它的例子。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过干扰因素直接做实验，结论无法排除其他原因。"},{"errorType":"ignoring-counterexample","why":"只记录支持结论的样本，不看反例。"}],"takeaway":"检验一个“如果……就……”，关键在于能否构造出反例。"}'::jsonb, array['可检验性', '步骤顺序', '条件推理']::text[], '原创题，用于训练把条件命题转成可检验设计。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cond-007', 1, 'conditional-reasoning', array['sufficient-condition', 'necessary-condition']::text[], 4, 150, 'open-response', null, '一位博主写道：“坚持每天读书一小时的人都不会焦虑。”请写出你对这句话的评价：它把什么当成了什么条件？你打算怎样看待这个结论？', null, null, null, '{"scale":[{"score":0,"label":"接受说法","criteria":"认为读书与焦虑的关系已被说清，不需要进一步证据。"},{"score":1,"label":"仅表怀疑","criteria":"觉得这句话夸张，但说不出问题出在哪里。"},{"score":2,"label":"指出条件类型混淆","criteria":"能说明它把读书当作不焦虑的充分条件，而证据至多支持相关。"},{"score":3,"label":"给出替代解释","criteria":"进一步指出可能是生活规律的人既读书又更少焦虑，属于共同原因。"},{"score":4,"label":"设计区分方式","criteria":"还能说明用什么观察或数据能把上述几种解释区分开，并标出自己的不确定处。"}],"guidance":"先判断句式把哪个条件当成了哪个条件，再补出至少一个同样成立的解释，最后说明需要什么证据。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"全称句式“坚持读书的人都不焦虑”把读书说成不焦虑的充分条件，同时隐含排除了所有反例，证据强度很弱。","steps":["把句子改写为 若坚持读书一小时则不会焦虑，识别其充分条件结构。","注意它是一个全称断言，一个稳定反例即可削弱。","列出替代解释：规律生活、社会经济地位、可支配时间可能是共同原因。","说明可区分证据：控制生活方式后的对照，或纵向追踪同一人前后变化。"],"commonMistakes":[{"errorType":"conclusion-overreach","why":"由部分人的经验推出“都不会”这样的全称结论。"},{"errorType":"correlation-as-causation","why":"把共现关系说成单向因果。"}],"takeaway":"评估一句话时，先把它拆成“若 P 则 Q”，再问证据够不够。"}'::jsonb, array['条件推理', '开放题', '论证分析']::text[], '原创题，量表依据常见回答层级设计，供自评与可选的模型反馈使用。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cond-008', 1, 'conditional-reasoning', array['denying-antecedent', 'exhaustive-cases']::text[], 3, 70, 'single-choice', null, '培训部门承诺：“参加完这门课，学员的项目交付准时率会提高。”小马没有参加这门课，但他的准时率今年提高了。对这个结果，下列哪种说法最合适？', null, '[{"key":"A","text":"承诺被证伪了，因为没上课也提高了","errorType":"denying-antecedent","reason":"由否定前件的结果推出规则不成立"},{"key":"B","text":"承诺没有被这个案例证伪，它只说了上课的效果"},{"key":"C","text":"小马如果上课，准时率一定会更高"},{"key":"D","text":"说明这门课对任何人都没有用","errorType":"hasty-generalization","reason":"由单个个例推出全称结论"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"“若上课则提高”并没有对没上课的人作出任何承诺，因此小马的情况既不能证实也不能证伪它。","steps":["符号化：P＝上课，Q＝准时率提高，规则为 若 P 则 Q。","已知 非 P 且 Q，这种情况不在规则覆盖范围内。","要证伪该规则，需要找到 P 且非 Q 的案例。","因此合适的说法是“本次没有提供判定信息”，而不是宣布承诺失败。"],"commonMistakes":[{"option":"A","errorType":"denying-antecedent","why":"误以为没上课就不该提高，从而把规则理解反了。"},{"option":"D","errorType":"hasty-generalization","why":"用一个未参与者的表现推广到所有人。"},{"option":"C","errorType":"conclusion-overreach","why":"在没有对照的情况下断言确定性的因果效果。"}],"takeaway":"检验一个条件承诺，要去找“前件成立但后件不成立”的例子。"}'::jsonb, array['否定前件', '证伪', '条件推理']::text[], '原创题，结合培训效果场景训练证伪意识。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cpv-001', 1, 'contrapositive-conversion', array['contrapositive', 'converse-error', 'modus-tollens']::text[], 2, 45, 'single-choice', '安装包发布流程。', '测试负责人说：“如果这批安装包通过了兼容性测试，它就能进入灰度发布。”以下哪句话与这句话逻辑等价？', null, '[{"key":"A","text":"如果这批安装包没有进入灰度发布，那么它没有通过兼容性测试"},{"key":"B","text":"如果这批安装包进入了灰度发布，那么它通过了兼容性测试","errorType":"affirming-consequent","reason":"把逆命题当成等价形式"},{"key":"C","text":"如果这批安装包没有通过兼容性测试，它就不能进入灰度发布","errorType":"denying-antecedent","reason":"把否命题当成等价形式"},{"key":"D","text":"这批安装包要么通过兼容性测试，要么进入灰度发布，二者必居其一","errorType":"false-dilemma","reason":"把一条条件关系压缩成二选一"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"“若 P 则 Q”只与它的逆否命题“若非 Q 则非 P”等价。逆命题和否命题都可能与原命题真值不同。","steps":["符号化：P＝通过兼容性测试，Q＝进入灰度发布，原命题为 若 P 则 Q。","写出逆否命题：若非 Q 则非 P，即“没进入灰度 → 没通过测试”，就是 A。","B 是逆命题（若 Q 则 P），C 是否命题（若非 P 则非 Q），两者都不是等价改写。","用一个情形检查：测试没通过但仍被特批灰度，这与原命题相容、与 C 冲突，说明 C 不等价。"],"commonMistakes":[{"option":"B","errorType":"affirming-consequent","why":"进入灰度的通道可能不止兼容性测试这一条，看到结果就反推原因。"},{"option":"C","errorType":"denying-antecedent","why":"原命题没有对“没通过测试”的情形作任何承诺。"},{"option":"D","errorType":"false-dilemma","why":"条件关系允许两个都发生，强行二选一会漏掉中间情形。"}],"takeaway":"改写条件句时，只有“前后件都否定并调换位置”这一种是等价的。"}'::jsonb, array['逆否命题', '等价改写', '发布流程']::text[], '原创题，场景为安装包灰度发布，用于区分四种命题形式。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cpv-002', 1, 'contrapositive-conversion', array['converse-error', 'affirming-consequent', 'modus-tollens']::text[], 3, 70, 'single-choice', '合同违约金条款复盘。', '合同附件规定：“若供应商在 3 月 31 日前交付，则不需要支付违约金。”已知供应商最终没有支付违约金。以下哪项最准确？', null, '[{"key":"A","text":"供应商一定在 3 月 31 日前交付了"},{"key":"B","text":"仅凭这两条信息，无法确定供应商是否按期交付"},{"key":"C","text":"这条规定同样说明：逾期交付就必须支付违约金","errorType":"denying-antecedent","reason":"由否定前件推出否定后件"},{"key":"D","text":"既然没付违约金，可见该交付期条款并未实际生效","errorType":"missing-reasoning-step","reason":"结论依赖条款效力这一未给出的前提"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[{"keys":["A"],"note":"如果把附件条款理解成交付期与违约金的充要约定（“当且仅当按期交付才免违约金”），A 才成立；但题干原文只给出单向条件，故默认按 B 判。"}]'::jsonb, '{"summary":"已知的是后件成立（没付违约金）。由“若 P 则 Q”和 Q 推不出 P，因为可能存在其他免违约金的情形。","steps":["符号化：P＝3 月 31 日前交付，Q＝不需要支付违约金，条款为 若 P 则 Q。","已知事实是 Q，属于肯定后件，形式上无效。","列举可能的其他免违约金情形：买方书面豁免、不可抗力、双方协商变更交付期。","反过来检查有效推理长什么样：若已知“支付了违约金”（非 Q），由逆否可得“未按期交付”（非 P）；但本题给的是 Q，推不出任何关于 P 的结论。"],"commonMistakes":[{"option":"A","errorType":"affirming-consequent","why":"把“按期交付足以免违约金”读成“免违约金只能来自按期交付”。"},{"option":"C","errorType":"denying-antecedent","why":"条款没有规定逾期一定罚，可能逾期仍被豁免。"},{"option":"D","errorType":"missing-reasoning-step","why":"从一条免除结果直接跳到条款效力判断，中间环节没有给出。"}],"takeaway":"看到“结果已经发生”，先问规则给的是单向条件还是双向约定。"}'::jsonb, array['肯定后件', '合同条款', '逆否']::text[], '原创题，场景取自采购合同违约金争议，训练识别后件成立时的可推出范围。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cpv-003', 1, 'contrapositive-conversion', array['contrapositive', 'only-if', 'converse-error']::text[], 4, 85, 'single-choice', '招聘筛选口径统一。', '招聘条件写：“只有通过初筛的候选人，才会收到面试邀请。”下列四句话中，哪一句与原句逻辑等价？', null, '[{"key":"A","text":"没有通过初筛的候选人，不会收到面试邀请"},{"key":"B","text":"通过了初筛的候选人，都会收到面试邀请","errorType":"affirming-consequent","reason":"由条件成立反推结果成立"},{"key":"C","text":"没有收到面试邀请的候选人，一定没有通过初筛","errorType":"denying-antecedent","reason":"否定前件推出否定后件"},{"key":"D","text":"只有收到面试邀请，才算通过了初筛","errorType":"premise-misidentification","reason":"把前件与后件的位置对调"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"原句译为“若收到邀请则通过初筛”。它的逆否命题是“若没通过初筛则不会收到邀请”，正是 A。","steps":["先做句式翻译：“只有 P 才 Q”＝若 Q 则 P；这里 P＝通过初筛，Q＝收到面试邀请。","对 若 Q 则 P 取逆否：若非 P 则非 Q，即“没通过初筛 → 收不到邀请”，得 A。","B 是 P→Q，即原命题的逆命题，不等价；初筛通过者也可能因名额已满而不被邀请。","C 是 非Q→非P，等于对原命题否定前件；D 把“收到邀请”说成“通过初筛”的必要条件，同样只是逆命题的另一种说法。"],"commonMistakes":[{"option":"B","errorType":"affirming-consequent","why":"把必要条件当成充分条件，认为过了初筛就必然被邀请。"},{"option":"C","errorType":"denying-antecedent","why":"没收到邀请的原因很多，不能反推没通过初筛。"},{"option":"D","errorType":"premise-misidentification","why":"“只有……才……”里被“只有”修饰的是必要条件，位置一换含义就变。"}],"takeaway":"两步走：先把“只有”句式译成“若 Q 则 P”，再统一用逆否改写来比对选项。"}'::jsonb, array['逆否等价', '只有句式', '招聘条件']::text[], '原创题，把“只有……才……”与逆否改写合并训练，常见于口径统一讨论。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cpv-004', 1, 'contrapositive-conversion', array['contrapositive', 'converse-error', 'exhaustive-cases']::text[], 4, 105, 'multi-choice', '客服 SLA 指标复盘。', '客服指标口径写：“只要投诉在 24 小时内得到响应，客户满意度就不低于 80%。”下列哪些说法与这条口径逻辑等价？（选出所有等价的说明）', null, '[{"key":"A","text":"若客户满意度低于 80%，则该投诉没有在 24 小时内得到响应"},{"key":"B","text":"或者该投诉没有在 24 小时内得到响应，或者客户满意度不低于 80%"},{"key":"C","text":"若客户满意度不低于 80%，则该投诉在 24 小时内得到了响应","errorType":"affirming-consequent","reason":"以逆命题冒充等价形式"},{"key":"D","text":"该投诉没有在 24 小时内得到响应，所以客户满意度低于 80%","errorType":"denying-antecedent","reason":"否定前件就否定后件"},{"key":"E","text":"不可能出现“24 小时内响应了、客户满意度却低于 80%”的情形"}]'::jsonb, null, '{"keys":["A","B","E"]}'::jsonb, '[]'::jsonb, '{"summary":"“若 P 则 Q”有三种等价说法：逆否命题 若非 Q 则非 P；选言式 非 P 或 Q；以及“P 且非 Q 不可能出现”。C、D 分别落在逆命题和否命题上。","steps":["符号化：“只要 P 就 Q”给出充分条件，这里 P＝24 小时内响应，Q＝满意度不低于 80%，口径即 若 P 则 Q。","A 是 若非 Q 则非 P，属于标准逆否改写，等价。","B 是 非 P 或 Q。用穷尽情形检查：响应不及时（非 P）时该句为真；响应及时（P）时要求 Q 为真，恰与口径一致，故等价。","E 说的是“P 且非 Q”不存在，这正是口径被违反的唯一形式，等价。","C 是 Q→P，D 是 非P→非Q。满意度 80% 可能来自长期服务口碑，响应不及时也可能因客户本来满意，两者都不与口径同真同假。"],"commonMistakes":[{"option":"C","errorType":"affirming-consequent","why":"由满意度达标反推一定响应及时，忽略了达标的其他来源。"},{"option":"D","errorType":"denying-antecedent","why":"口径没有规定响应不及时会怎样，推不出满意度低。"}],"takeaway":"判断等价时，只需检查两句话是否在同一个情形集上成立。"}'::jsonb, array['逆否', '选言等价', '多选', '指标口径']::text[], '原创题，场景为客服指标口径评审，覆盖条件式的三种常见等价表述。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cpv-005', 1, 'contrapositive-conversion', array['contrapositive', 'converse-error']::text[], 2, 40, 'true-false', '命题形式基础判断。', '“若 P 则 Q”成立时，它的逆否命题“若非 Q 则非 P”一定成立；而它的否命题“若非 P 则非 Q”不一定成立。', null, null, null, '{"value":true}'::jsonb, '[]'::jsonb, '{"summary":"原命题与逆否命题真值条件完全相同；否命题与逆命题只彼此等价，与原命题可以一真一假。","steps":["列出四种形式：原命题 P→Q、逆命题 Q→P、否命题 非P→非Q、逆否命题 非Q→非P。","逐一检查使之为假的情形：P→Q 只在“P 真 Q 假”时为假；非Q→非P 也只在“非Q 真且非P 假”即同样情形为假，两者同真同假。","反例验证否命题：设 P→Q 为真，而某情形中 P 假 Q 真，此时 非P→非Q 为假，说明否命题不必然成立。","因此题中两个分句都为真，判断为对。"],"commonMistakes":[{"errorType":"affirming-consequent","why":"误把逆命题也当作等价形式，就会认为后半句说错了。"},{"errorType":"denying-antecedent","why":"误以为否定前件就能否定后件，会把否命题当成等价的。"}],"takeaway":"四种形式里只有原命题与逆否命题互为等价，其余都要另找证据。"}'::jsonb, array['命题形式', '逆否等价', '判断题']::text[], '原创题，用于快速检验四种命题形式之间等价关系的掌握。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cpv-006', 1, 'contrapositive-conversion', array['contrapositive', 'modus-tollens', 'affirming-consequent']::text[], 3, 90, 'short-answer', '来料批次溯源核查。', '质检员说：“如果这批元件来自 A 供应商，那么它一定带有溯源码。”小王说：“这批元件没有溯源码，所以它不是 A 供应商的。”请判断小王的推理是否有效，并写出他实际用到的推理形式。', null, null, null, '{"checkpoints":[{"id":"c1","label":"判定推理有效并指出形式","keywords":["逆否"],"weight":3,"required":true},{"id":"c2","label":"说明等价的理由","keywords":["等价"],"weight":2,"required":true},{"id":"c3","label":"排除两种无效形式","keywords":["肯定后件","否定前件"],"weight":1,"required":false}],"correctRatio":0.7,"partialRatio":0.45,"modelAnswer":"小王的推理有效，他用的是逆否推理：原命题是“若来自 A 供应商则有溯源码”，其逆否命题为“若没有溯源码则不是 A 供应商的”，两者等价，所以结论可以可靠地推出。需要注意他并不是在肯定后件，也没有否定前件，而是把已知事实“没有溯源码”当作否定后件的一步；若他改说“这批元件有溯源码，所以来自 A 供应商”，那才是无效的逆推。"}'::jsonb, '[]'::jsonb, '{"summary":"由“若 P 则 Q”和“非 Q”可靠推出“非 P”，这是否定后件式，也等于使用与原命题等价的逆否命题。","steps":["符号化：P＝来自 A 供应商，Q＝带溯源码，原命题为 若 P 则 Q。","小王的前提给出 非 Q，结论给出 非 P，形式为 若 P 则 Q；非 Q；所以非 P。","对照逆否命题：非 Q → 非 P 与 原命题 P → Q 等价，因此推理有效。","对比错误方向：由“有溯源码”推“来自 A 供应商”是肯定后件；由“不来自 A 供应商”推“没有溯源码”是否定前件，两者都不可靠。"],"commonMistakes":[{"errorType":"affirming-consequent","why":"把有效推理误判为无效，通常是把它和“有溯源码所以来自 A”混为一谈。"},{"errorType":"premise-misidentification","why":"漏掉“没有溯源码”这一关键事实，就会以为结论没有依据。"}],"takeaway":"先找已知事实否定了哪个部分：否定后件才能否定前件。"}'::jsonb, array['否定后件', '逆否推理', '简答题']::text[], '原创题，场景为来料溯源核查，训练识别否定后件与逆否改写的同一性。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cpv-007', 1, 'contrapositive-conversion', array['contrapositive', 'falsification', 'dependency-order']::text[], 3, 85, 'ordering', '数据出境合规核查。', '合规规则写：“若某批数据出境，则它必须先通过安全评估。”你要用逆否改写来检查这条规则是否被违反。请按最合理的先后顺序排列以下步骤。', null, null, '[{"key":"s1","text":"把规则写成标准条件式：若数据出境，则已通过安全评估"},{"key":"s2","text":"写出等价的逆否命题：若未通过安全评估，则数据没有出境"},{"key":"s3","text":"依据两个命题确定要观察的字段，并把口径写清楚"},{"key":"s4","text":"调取系统实际记录，找出“未通过评估但数据已出境”的情形并判定"}]'::jsonb, '{"keys":["s1","s2","s3","s4"]}'::jsonb, '[]'::jsonb, '{"summary":"核查顺序是：标准化 → 逆否改写 → 确定观察口径 → 用记录检验。逆否改写把要查的情形变得容易观测。","steps":["不先写成条件式，就无法保证后续改写没有改变原意，所以 s1 必须第一步。","s2 的价值在于把“寻找违反情形”转化为可观测的方向：评估状态在先，出境事实在后。","字段和口径必须在取数之前确定，否则记录到手仍不知如何判定，故 s3 在 s4 之前。","s4 检查的“未通过评估但已出境”正是 非 Q 且 P，它同时推翻原命题与逆否命题，是有效的违反证据。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过逆否改写直接翻记录，容易把“已评估未出境”这类无关情形当成违反。"},{"errorType":"premise-misidentification","why":"把规则里的先后关系与条件关系混同，就会找错要观察的字段。"}],"takeaway":"改写不是为了换说法，而是为了让可观测的违反情形浮现出来。"}'::jsonb, array['逆否改写', '可检验性', '排序']::text[], '原创题，场景为数据出境合规核查，训练用逆否命题设计检查步骤。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cpv-008', 1, 'contrapositive-conversion', array['contrapositive', 'converse-error', 'conclusion-identification']::text[], 5, 150, 'open-response', '日常健康信息解读。', '有人说：“体检报告写着‘若该项指标异常则需要复查’，我没被要求复查，说明我这项指标完全正常。”请评价这个推理：写出它用到的规则形式，指出结论中超出证据的部分，并说明需要补充什么才能把话说满。', null, null, null, '{"scale":[{"score":0,"label":"全盘接受","criteria":"认为没被要求复查就等于指标完全正常，无需再确认其他条件。"},{"score":1,"label":"只表疑虑","criteria":"感觉这句话推得太快，但说不出哪一步不成立或差什么信息。"},{"score":2,"label":"识别有效形式","criteria":"能写出 若异常则复查，并指出没复查推出没异常是否定后件，形式有效。"},{"score":3,"label":"区分结论强度","criteria":"能区分“不属于该规则判定的异常”与“完全正常”，指出后者超出证据范围。"},{"score":4,"label":"补出隐含条件","criteria":"能说明结论成立还依赖规则被严格执行、判定口径覆盖该项指标等前提，并给出核对方法。"}],"guidance":"先把规则与已知事实分别符号化，检查推理形式；再比较结论措辞的强度与实际推出的强度；最后列出这条推理默认相信的隐含前提，并说明各用什么办法核对。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"否定后件可以可靠地否定前件，因此能得“该项指标未被规则判定为异常”；但“完全正常”比这更强，还要求规则覆盖全、执行到位。","steps":["符号化：P＝该项指标异常，Q＝被要求复查，规则为 若 P 则 Q。","已知 非 Q，套用否定后件式得 非 P，即“不属于该规则所说的异常”。","比较结论强度：“完全正常”还隐含指标处于理想区间、无临界值、无测量误差，这些都不是 非 P 能保证的。","补出隐含前提并给出核对方式：报告是否确实执行了该规则（看流程记录）、判定口径是否覆盖该项目（看参考区间说明）。"],"commonMistakes":[{"errorType":"conclusion-overreach","why":"把“未被判为异常”直接升级为“完全正常”，结论强于证据。"},{"errorType":"affirming-consequent","why":"另一种常见错法是反过来认为“被要求复查所以一定异常”，那是肯定后件。"},{"errorType":"missing-reasoning-step","why":"没有确认规则是否被严格执行，就把规则内容当成事实结果。"}],"takeaway":"形式有效只保证结论不比前提弱；措辞一加强，就要重新检查证据。"}'::jsonb, array['逆否', '结论强度', '开放题', '隐含前提']::text[], '原创题，场景为体检报告解读，量表按推理深度分层，供自评与可选的模型反馈使用。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cor-001', 1, 'correlation-vs-causation', array['correlation-scenarios', 'common-cause']::text[], 2, 50, 'single-choice', null, '某连锁咖啡店运营周报：上周下雨天数多，雨天外卖订单量比晴天高 40%，同时差评率从晴天的 3% 升到雨天的 5.1%。周报结论写“订单量大导致差评增多”。下列哪项评价最准确？', null, '[{"key":"A","text":"天气同时推动两个指标：雨天点单的人更多，配送也更慢更容易超时，差评上升可能来自超时而不是订单量本身"},{"key":"B","text":"订单量与差评率同向变化，这就足以说明是单量增加造成了差评增多","errorType":"correlation-as-causation","reason":"由两个指标共变直接推出因果关系"},{"key":"C","text":"只要先核对 5.1% 这个数有没有算错，原因就能确定下来","errorType":"missing-reasoning-step","reason":"把核对数据当成完成因果归因"},{"key":"D","text":"差评率只上升了 2.1 个百分点，幅度很小，可见天气根本没有影响","errorType":"equivocation","reason":"把百分点的小差异偷换成影响不存在"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"订单量与差评率都被天气推着走，共变方向一致并不说明二者互相导致；要判断因果，得看超时率这类中间指标。","steps":["把两个数字对齐：以晴天订单量为 1，雨天为 1.4；差评率晴天 3%、雨天 5.1%。","算出差评条数之比：1.4×5.1% ÷ 3% = 7.14 ÷ 3 = 2.38，即雨天差评条数约为晴天的 2.4 倍，其中一部分只是订单变多的结果。","比较率的两种说法：绝对上升 5.1% − 3% = 2.1 个百分点，相对上升 5.1 ÷ 3 = 1.7，即约 70%。","列出竞争解释：雨天配送慢、超时增多、骑手人手紧张同样能解释差评率上升。","给出区分办法：按是否超时拆开差评率，或比较晴天与雨天在相同超时水平下的差评率差异。"],"commonMistakes":[{"option":"B","errorType":"correlation-as-causation","why":"两指标同涨只说明存在关联，共同的天气原因也能造出这种同步。"},{"option":"C","errorType":"missing-reasoning-step","why":"确认数字没错只解决了前提真假，从关联到因果还需要排除第三因素这一步。"},{"option":"D","errorType":"equivocation","why":"2.1 个百分点听起来小，但对应的相对幅度约 70%，用绝对差否认影响是换了口径。"}],"takeaway":"两个指标一起变化时，先找出同时推着它们走的那个变量。"}'::jsonb, array['共同原因', '百分点与相对幅度', '消费数据']::text[], '原创题，场景取自连锁餐饮的运营周报，用于训练识别天气这类共同驱动因素。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cor-002', 1, 'correlation-vs-causation', array['spurious-correlation', 'correlation-scenarios']::text[], 3, 65, 'single-choice', null, '过去五年，某市新建地铁运营里程从 40 公里增至 160 公里，同期少儿编程机构从 12 家增至 48 家。有人据此写道“地铁修到哪里，孩子的编程学习兴趣就被带到哪里”。对这个说法，下列哪项判断最合适？', null, '[{"key":"A","text":"两条曲线都随城市扩张与家庭收入增长而上升，同步更可能来自共同的第三方变化，而不是彼此导致"},{"key":"B","text":"两者同步增长，说明地铁沿线家庭确实更倾向给孩子报编程班","errorType":"correlation-as-causation","reason":"由整体趋势同步直接推出具体机制"},{"key":"C","text":"把两个数都换成年均增长率，就能看出谁导致谁","errorType":"missing-reasoning-step","reason":"同一倍数的两条曲线换成增长率后依然完全同步"},{"key":"D","text":"五年这么长的时间都保持同步，说明这条关系已经不需要别的证据","errorType":"insufficient-evidence","reason":"用观察时间长短替代机制与对照证据"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"两条各自增长到 4 倍的曲线必然同步，这种同步可以只反映城市整体的变化趋势，属于典型的时间趋势型伪相关。","steps":["核对倍数：地铁 160 ÷ 40 = 4，编程机构 48 ÷ 12 = 4，两者都是 5 年增至 4 倍。","换算成增速：4 的五次方根约为 1.32，两条曲线的年均增速都约 32%，完全一致。","由此说明 C 的问题：把绝对量换成增长率，同步性一点没变，也就无法区分方向。","列出共同原因：城市人口、可支配收入、商业密度、教育投入同时推高两类供给。","说明什么证据才有帮助：控制家庭收入与城区后，比较新开通地铁的街区与未开通街区在同一时期的编程班变化差异。"],"commonMistakes":[{"option":"B","errorType":"correlation-as-causation","why":"全市总量层面的同步推不出“沿线家庭”这一具体机制，方向与中介都没有证据。"},{"option":"C","errorType":"missing-reasoning-step","why":"指标换算不增加新信息，因果判断还需要差异化的对照数据。"},{"option":"D","errorType":"insufficient-evidence","why":"长期共变仍然只是共变，时间长度不能替代对照与机制。"}],"takeaway":"两条一起上升的曲线，先怀疑它们背后有一条共同的上升趋势。"}'::jsonb, array['伪相关', '时间趋势', '城市数据']::text[], '原创题，场景取自城市基建与培训行业数据的对比报道，用于训练识别趋势型伪相关。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cor-003', 1, 'correlation-vs-causation', array['correlation-scenarios', 'common-cause', 'reverse-causation']::text[], 4, 110, 'multi-choice', null, '一项调查收集了 1,200 名小学生的教育平板日均使用时长与期末数学成绩，算得两者的相关系数约为 0.35。下列哪些说法与这份数据相容、且表述是稳妥的？（选出所有正确的）', null, '[{"key":"A","text":"更重视学习的家庭既买平板又多花时间辅导，家庭投入作为共同原因同样能造出 0.35 的相关"},{"key":"B","text":"也可能是数学成绩较好的孩子更愿意用平板练习，即方向与宣传所说相反"},{"key":"C","text":"相关系数为正且样本有 1,200 人，已经足以证明平板使用直接提高了成绩","errorType":"correlation-as-causation","reason":"把正相关的统计显著当成因果机制被证实"},{"key":"D","text":"0.35 只说明存在正向线性关联，并不能排除两个变量同时被第三个变量推动"},{"key":"E","text":"可以把 0.35 读成“平板解释了 35% 的成绩差异，其余 65% 来自其他因素”","errorType":"equivocation","reason":"把相关系数与它平方后的方差解释比例混为一谈"}]'::jsonb, null, '{"keys":["A","B","D"]}'::jsonb, '[]'::jsonb, '{"summary":"相关系数只描述关联强度与方向；0.35 至少容纳平板致效、成绩致用、家庭投入共同推动等多种解释。","steps":["先明确数据形态：日均使用时长与数学成绩同向变化，r 约 0.35，属于中等偏弱正相关。","把共变的几种解释列全：使用提高成绩；成绩好促使更多使用；家庭投入同时提高两者；成绩好的孩子被允许用更多功能。","算清 E 的错误：0.35 的平方约为 0.1225，即约 12% 的方差伴随变化，而且这仍是统计关联量，不是因果效应占比。","说明 C 的错误：样本量大只让估计更精确，不会改变横断面数据无法排除混淆这一结构问题。","给出能区分方向的证据：随机分到使用组与不限使用组的对照，或追踪同一批学生使用时长变化先于还是后于成绩变化。"],"commonMistakes":[{"option":"C","errorType":"correlation-as-causation","why":"相关方向与样本规模都不是因果证据，横断面关联仍然缺排除混淆这一步。"},{"option":"E","errorType":"equivocation","why":"同一个数字在前半句是相关系数、后半句被换成解释比例，词义中途发生了变化。"}],"takeaway":"看到一个相关系数，先写出它能容纳的几种方向，再谈它有多大。"}'::jsonb, array['相关系数', '教育产品宣传', '多种解释']::text[], '原创题，场景取自教育硬件厂商引用的调研数据，用于训练对单个相关系数做多种因果解释。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cor-004', 1, 'correlation-vs-causation', array['correlation-scenarios']::text[], 3, 55, 'true-false', null, '某健身 App 报告：“会员每周锻炼天数与静息心率的相关系数约为 0.02，几乎为零，说明锻炼与心率之间毫无关系。”判断：这个结论的下法是不正确的。', null, null, null, '{"value":true}'::jsonb, '[]'::jsonb, '{"summary":"0.02 说明几乎不存在线性关联，但“没有关系”比它强得多；曲线关系、口径问题都可能被同一个数字掩盖。","steps":["确认该指标度量的是什么：常见的相关系数只刻画线性趋势的强弱与方向。","构造一个能被它漏掉的情形：适度锻炼降低静息心率、训练量过大又让它回升，倒 U 形关系的线性相关可以接近 0。","检查口径：用“天数”而不是训练强度或时长，可能把真正起作用的变量抹平。","比较两个命题的强度：“无线性相关”成立时，“毫无关系”并不成立，因此该结论超出了证据范围。"],"commonMistakes":[{"errorType":"equivocation","why":"把“线性相关接近 0”与“两者毫无关系”当成同一件事，是关键词含义被替换。"},{"errorType":"conclusion-overreach","why":"由一个只测线性的数字推出关于一切关系的总判断，结论比证据走得远。"}],"takeaway":"先弄清指标测的是什么关系，再决定能否认掉整类关系。"}'::jsonb, array['相关系数', '非线性关系', '指标口径']::text[], '原创题，场景取自运动类应用的数据周报，用于训练区分“无线性相关”与“无任何关系”。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cor-005', 1, 'correlation-vs-causation', array['correlation-scenarios', 'spurious-correlation', 'confounder']::text[], 4, 140, 'short-answer', null, '某公司 1 至 6 月的投放费用（万元）为 20、25、30、40、50、55，同期销售额（万元）为 80、100、120、160、200、220。市场部说：“两者完全同步，投放每多花 1 元就多带来 4 元销售。”请用两三句话指出这个说法最可疑之处。', null, null, null, '{"checkpoints":[{"id":"c1","label":"指出需要反事实证据","keywords":["反事实"],"weight":3,"required":true},{"id":"c2","label":"指出共同驱动因素","keywords":["共同驱动"],"weight":2,"required":false},{"id":"c3","label":"怀疑两数同源或口径相同","keywords":["口径","同源"],"weight":2,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"六个月里销售与投放的比值全都等于 4，这种完美同步本身就是疑点：它更像是同一张计划表推出来的同源数字，或者两个数被同一个预算变量一起决定，而不是投放造成了销售。要检验这个 4 倍，至少需要三件事。第一，看反事实，也就是在减量甚至暂停投放的月份与渠道里销售怎样变化。第二，排除共同驱动，季节、平台大促和渠道库存会同时抬高两个数字。第三，核对口径，确认销售不是从投放预算倒推填出来的。三点都处理之后，4 倍这个说法才有讨论价值。"}'::jsonb, '[]'::jsonb, '{"summary":"六个点严格落在同一条正比例直线上，相关系数恰好为 1，这种完美同步在真实市场里几乎不会出现，更像数据同源而非因果效应。","steps":["逐一算比值：80÷20、100÷25、120÷30、160÷40、200÷50、220÷55 全都等于 4.0。","由此推出关联强度：所有点都满足销售 = 4×投放，两点之间的散布为零，线性相关系数为 1。","质疑完美性：真实投放通常存在边际递减与滞后，六个月都保持同一比例，更可能两个数来自同一份预算或目标计划。","指出因果缺口：即使同步是真的，也需要只改变投放的观察，例如暂停或减量渠道的对照，也就是反事实。","列出需要排除的共同驱动：季节需求、大促档期、渠道备货、竞品断货都会同时推高两个数字。"],"commonMistakes":[{"errorType":"correlation-as-causation","why":"把比值稳定当成因果系数，等于用“多花 1 元多卖 4 元”给一条直线安排了方向。"},{"errorType":"insufficient-evidence","why":"六个月共 6 个观测点且没有任何未投放的对照，不足以支撑可外推的投入产出比。"},{"errorType":"missing-reasoning-step","why":"从“同步”到“投放导致销售”之间缺少排除共同原因与构造反事实的中间步骤。"}],"takeaway":"关联完美得没有误差时，先怀疑两个数字是不是出自同一张表。"}'::jsonb, array['公司报表', '同源数据', '反事实']::text[], '原创题，场景取自营销投放复盘，六个数据点由编写者构造为严格正比例，用于训练对完美同步的怀疑。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cor-006', 1, 'correlation-vs-causation', array['correlation-scenarios', 'confounder']::text[], 3, 95, 'ordering', null, '某市 3 月在中心城区推行共享单车电子围栏，随后 6 月人行道占用投诉量比 3 月下降 22%，媒体写“电子围栏让投诉少了”。请按最合理的先后顺序排列评估这项说法的步骤。', null, null, '[{"key":"u1","text":"查清投诉量的来源与统计口径，确认下降 22% 是与哪个月、哪个范围比较得出的"},{"key":"u2","text":"拉出政策之前至少半年的逐月投诉曲线，判断下降是 3 月才开始还是早已存在趋势"},{"key":"u3","text":"列出同期其他可能改变投诉量的变化，如骑行总量、季节、投诉入口改版、其他城管措施"},{"key":"u4","text":"找未安装围栏的相似城区或另一座城市作对照，比较两地投诉曲线的变化差异"},{"key":"u5","text":"比较各解释对不同数据的预测，写出暂时结论并说明还剩哪些不确定"}]'::jsonb, '{"keys":["u1","u2","u3","u4","u5"]}'::jsonb, '[]'::jsonb, '{"summary":"评估一项政策与指标的相关，顺序是：统一口径、检查既有趋势、枚举同期变化、构造对照、最后按预测差异收敛结论。","steps":["第一步固定指标定义，口径一变（例如投诉入口改版）任何百分比都失去意义。","第二步看政策之前的趋势，如果投诉早已逐月下降，3 月后的 22% 就可能只是趋势延续。","第三步枚举同期变化，为后面选择对照提供依据。","第四步用对照隔离共同因素：两地都受季节与骑行总量影响，差值更能反映政策本身。","第五步区分预测而非收集支持性例子，并明确结论仍是暂时的。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过政策前的趋势检查就直接比较前后两个月，等于把已有下降记成新政策的功劳。"},{"errorType":"correlation-as-causation","why":"只看政策与投诉在时间上对应，就把对应关系写成因果结论。"}],"takeaway":"判断政策效果，关键是比较“有政策的地方”与“没有政策的地方”，而不是比较前后两个月。"}'::jsonb, array['城市政策', '步骤顺序', '对照']::text[], '原创题，场景取自城市治理措施成效报道，用于训练把共变核查排成有依赖顺序的步骤。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cor-007', 1, 'correlation-vs-causation', array['correlation-scenarios', 'confounder', 'survivorship-bias']::text[], 5, 190, 'open-response', null, '某商品页面写着：“本商品好评率 96%，其中 78% 的五星评价都提到‘到货快’，可见到货快是我们获得好评的主要原因。”请评价这段论证：除了它给出的因果解释，你还能想到哪几种同样能说明 78% 这个比例的说法？需要什么数据才能真正区分？', null, null, null, '{"scale":[{"score":0,"label":"接受论证","criteria":"认为 78% 已经说明到货快是好评的主要原因。"},{"score":1,"label":"仅表怀疑","criteria":"觉得这个推论有点跳，但说不清哪一步缺了依据。"},{"score":2,"label":"指出文本共现不等于原因","criteria":"能说明提到到货快只是评价文本里的共现，不衡量它对好评的贡献大小。"},{"score":3,"label":"补出替代解释","criteria":"至少给出共同原因、评价人群自我选择、默认好评模板等两种以上替代解释。"},{"score":4,"label":"设计可区分的数据","criteria":"进一步写出能区分这些解释的具体数据或分组，并说明自己最倾向哪一种及其余可能。"}],"guidance":"先分清“评价里提到某词的比例”与“该词造成好评的比例”是两个不同指标，再列出至少两种替代解释，最后给出能区分它们的分组数据。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"78% 是五星评价文本中提到“到货快”的比例，分母已经限定在好评之中，因此它无法衡量到货对好评的贡献。","steps":["把 78% 的分母说清楚：它统计的是五星评价，而不是全部下单者，因此只描述好评内部的用词分布。","解释一（共同原因）：同一仓储体系既让到货快又让商品完好，两者都由履约能力推动，评价里同时出现。","解释二（自我选择）：满意的人更愿意写长评，不满意的人直接退货而不评价，五星评价样本本身就偏向满意者。","解释三（表述习惯）：平台有默认好评文案与快捷标签，提到到货快可能只是点了模板按钮，与真实原因无关。","解释四（口径混淆）：96% 好评率的分母是评价者而非购买者，两个百分比不能直接连成因果链。","给出区分数据：把差评与中评的文本同样统计，比较“提到到货快”在好评与差评中的比例差；或按实际配送时长分层比较好评率；同时公开下单人数与评价人数的比值。"],"commonMistakes":[{"errorType":"correlation-as-causation","why":"由“好评里常提到到货快”直接写成就“到货快导致好评”。"},{"errorType":"base-rate-neglect","why":"只看到好评内部的 78%，不看差评与中评里同样的词出现多少，也不看有多少人根本没评价。"},{"errorType":"premise-misidentification","why":"把两个分母不同的百分比当成同一件事的两个证据。"}],"takeaway":"拿到一个百分比，先问它的分母是谁；分母不同的两个百分比连不成因果。"}'::jsonb, array['消费评价', '分母与口径', '开放题']::text[], '原创题，场景取自电商详情页的好评话术，量表按回答层级设计，供自评与可选的模型反馈使用。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cor-008', 1, 'correlation-vs-causation', array['correlation-scenarios', 'common-cause', 'confounder']::text[], 3, 60, 'single-choice', null, '某体检机构随访 30,000 名会员，发现常年服用鱼油者报告的心血管事件比不服用者少 30%。同一份数据显示，服用组人均每年体检 2.1 次，不服用组仅 0.7 次。下列哪项评价最准确？', null, '[{"key":"A","text":"两组连体检频率都是三倍关系（2.1 次对 0.7 次），说明他们在健康关注程度上本就系统不同，30% 的差距可能来自这种差别"},{"key":"B","text":"样本有 30,000 人，规模足够大，所以鱼油的作用已经被证实","errorType":"missing-reasoning-step","reason":"把样本规模当成可以替代对照的那一步"},{"key":"C","text":"鱼油要么是唯一原因，要么完全无关，结论只能在这两者里挑","errorType":"false-dilemma","reason":"把多种可能压缩成非此即彼的两项"},{"key":"D","text":"不服用组里也有人每年体检多次，可见两组在健康关注程度上没有实际差别","errorType":"hasty-generalization","reason":"由组内少数个例否定两组整体的平均差别"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"体检频率是健康意识的可见标记，它与是否服鱼油同向变化，正是一个与结果相关的混淆变量。","steps":["记录两组差异：事件率相差 30%，体检频率 2.1 次对 0.7 次，约为三倍。","把体检频率读作标记：会按时体检的人通常也更注意饮食、运动与用药，这些同样影响心血管事件。","指出结构：健康意识同时决定“是否服鱼油”和“事件多少”，因此 30% 可以被共同原因解释。","说明需要什么：在健康意识、年龄、吸烟状况等条件相同的人群内部比较，或随机分配的试验；大样本只让估计更窄，不改变分组不可比。"],"commonMistakes":[{"option":"B","errorType":"missing-reasoning-step","why":"样本量大能减少随机误差，却无法补上排除混淆变量这一步。"},{"option":"C","errorType":"false-dilemma","why":"忽略了共同原因、部分效应、口径差异等中间可能。"},{"option":"D","errorType":"hasty-generalization","why":"组内存在少数反例不等于两组均值没有差别，推的方向正好相反。"}],"takeaway":"两组连生活习惯都不一样时，组间差异就先别算在唯一因素头上。"}'::jsonb, array['混淆变量', '健康新闻', '共同原因']::text[], '原创题，场景取自体检机构发布的会员随访数据，用于训练把生活方式差异识别为混淆变量。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cex-001', 1, 'counterexample-rebuttal', array['counterexample-form', 'falsification']::text[], 2, 50, 'single-choice', '版本质量争议。', '有人主张：“所有通过回归测试的版本都不会出现闪退。”以下哪种情形如果确凿为真，构成对这一主张的反例？', null, '[{"key":"A","text":"某个版本通过了回归测试，上线当天就出现闪退"},{"key":"B","text":"某个版本没有通过回归测试，也没有出现闪退","errorType":"premise-misidentification","reason":"该情形不在主张所覆盖的范围内"},{"key":"C","text":"某个版本没有通过回归测试，出现了闪退","errorType":"denying-antecedent","reason":"以为没过测试就该闪退才算数"},{"key":"D","text":"有人说这个主张太绝对，但拿不出任何一个具体版本的情况","errorType":"insufficient-evidence","reason":"只有态度没有可用于判定的事实"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"主张可写成“若通过回归测试，则不会闪退”。反例必须让前件成立而后件落空，也就是“通过了测试但仍然闪退”。","steps":["把全称主张翻译成条件式：P＝通过回归测试，Q＝不出现闪退，主张为 所有 P 都是 Q。","写出反例的形式：存在一个对象，满足 P 且不满足 Q。","逐项比对：A 是 P 且非 Q，符合；B 是非 P 且 Q，C 是非 P 且非 Q，两者都不在原主张的承诺范围内。","D 只是表达对绝对化措辞的不满，没有提供可核对的事实，因而削弱不了主张。"],"commonMistakes":[{"option":"B","errorType":"premise-misidentification","why":"把“与主张无关的情形”误当成反驳材料，落点找错了。"},{"option":"C","errorType":"denying-antecedent","why":"主张没说没通过测试就一定会闪退，这个例子与主张同真。"},{"option":"D","errorType":"insufficient-evidence","why":"指出措辞绝对并不等于给出反例，削弱力度接近于零。"}],"takeaway":"要推翻“所有 P 都是 Q”，只需要找到一个 P 却不是 Q 的确凿事例。"}'::jsonb, array['反例形式', '全称主张', '版本质量']::text[], '原创题，场景取自研发质量争论，用于训练反例的最小形式要求。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cex-002', 1, 'counterexample-rebuttal', array['counterexample-form', 'rebuttal-target', 'straw-man']::text[], 3, 70, 'single-choice', '研发流程评审中的反驳练习。', '同事主张：“只要需求文档写得够细，开发就不会返工。”你想反驳他，下列哪一项真正构成反例？', null, '[{"key":"A","text":"有一份需求文档细到字段和接口级别，开发仍因理解偏差返工了"},{"key":"B","text":"有些返工是需求中途变更造成的，跟文档细不细没有关系","errorType":"premise-misidentification","reason":"反驳的是“文档是唯一原因”这一对方没说过的版本"},{"key":"C","text":"有个团队几乎不写需求文档，也很少返工","errorType":"denying-antecedent","reason":"用“不写文档也不返工”去推翻“写得细就不返工”"},{"key":"D","text":"文档细不细难以客观衡量，所以这个说法没有讨论价值","errorType":"missing-reasoning-step","reason":"由难以度量跳到没有价值"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"主张是“文档够细 → 不返工”。反例必须是“文档确实够细但仍返工”。B 攻击的是“文档是唯一原因”这一对方没说过的话，属于落点错位。","steps":["符号化：P＝文档写得够细，Q＝不返工，主张为 若 P 则 Q。","反例要求：给出 P 且非 Q 的实例，A 正是这种情形。","检查 B：返工另有原因，只说明 P 不是唯一条件；主张从未否认过其他原因存在，所以 B 反驳的是被夸大的版本。","检查 C 与 D：C 是 非P 且 Q，与主张相容；D 讨论的是可度量性，没有触及主张真假。"],"commonMistakes":[{"option":"B","errorType":"premise-misidentification","why":"把对方的主张加强成“返工只由文档粗糙引起”，再推翻这个加强版。"},{"option":"C","errorType":"denying-antecedent","why":"主张没有对“不写文档”的情形作任何承诺，因此它不算反证。"},{"option":"D","errorType":"missing-reasoning-step","why":"从概念难界定直接跳到命题无意义，中间缺少论证环节。"}],"takeaway":"反驳前先照原话复述一遍主张，检查你的例子打的是不是这句话本身。"}'::jsonb, array['反驳落点', '稻草人', '条件主张']::text[], '原创题，场景为需求评审争论，专门区分“真反例”与“打错对象的反例”。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cex-003', 1, 'counterexample-rebuttal', array['counterexample-form', 'rebuttal-target', 'evidence-relevance']::text[], 4, 90, 'single-choice', '劳动合规制度执行情况核查。', '制度写：“凡是单次加班超过 3 小时的员工，必须安排第二个工作日的调休。”工会想证明这条制度在实际执行中被违反，下列哪项是最直接的反例？', null, '[{"key":"A","text":"抽查的考勤与排班记录显示，张某上周一次加班 4 小时，第二个工作日并未安排调休"},{"key":"B","text":"李某加班 2 小时，第二个工作日没有调休","errorType":"premise-misidentification","reason":"该情形不满足制度设定的条件"},{"key":"C","text":"王某加班 5 小时并安排了调休，但他认为时长太短、制度不合理","errorType":"equivocation","reason":"把制度是否合理与是否被违反混为一谈"},{"key":"D","text":"多数部门都没严格执行这条制度，所以它形同虚设","errorType":"hasty-generalization","reason":"用未经核实的整体印象替换具体反例"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"制度设定了条件（加班超过 3 小时）与要求（次一工作日调休）。被违反只有一种形式：条件满足而要求未落实，A 用可核对记录给出这一形式。","steps":["符号化：P＝单次加班超过 3 小时，Q＝第二个工作安排了调休，制度为 若 P 则 Q。","确定反例形式：需要 P 且非 Q，且事实要能被第三方核对，否则只是说法。","A 同时满足两点：加班 4 小时（P 成立）、次一工作日无调休（Q 不成立），并有考勤与排班记录支撑。","B 是 非P，制度未作规定；C 中制度已被执行，争议转到合理性；D 是未经核实的总体印象，需要先落到具体个案。"],"commonMistakes":[{"option":"B","errorType":"premise-misidentification","why":"把制度没管的情形当成违反制度的证据。"},{"option":"C","errorType":"equivocation","why":"“执行了但不够好”与“没有按条文执行”是两件事，用词滑动就偏离了靶心。"},{"option":"D","errorType":"hasty-generalization","why":"以整体印象作结论，仍要回到具体个案才能成立。"}],"takeaway":"证明一条规定被违反，就要交出“条件已满足、要求未落实”的可核对个案。"}'::jsonb, array['反例', '必须句式', '合规执行']::text[], '原创题，场景为工会核查加班调休执行情况，训练把制度条文转成可违反形式。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cex-004', 1, 'counterexample-rebuttal', array['counterexample-form', 'implicit-premise', 'rebuttal-target']::text[], 4, 110, 'multi-choice', '上线安全检查有效性争论。', '有人主张：“只要产品上线前完成安全扫描，就不会发生数据泄露事故。”下列哪些情形如果确凿为真，构成对这一主张的反例？（选出所有反例）', null, '[{"key":"A","text":"某系统上线前完成了安全扫描，两周后仍发生数据库数据泄露"},{"key":"B","text":"某系统上线前按流程完成了安全扫描，但扫描清单未覆盖一个新引入的组件，随后该组件发生数据泄露"},{"key":"C","text":"某系统上线前没有做安全扫描，也没有发生数据泄露","errorType":"denying-antecedent","reason":"以为没做也没出事就能推翻主张"},{"key":"D","text":"某系统上线前没有做安全扫描，随后发生数据泄露","errorType":"premise-misidentification","reason":"把主张没覆盖的情形当成反驳材料"},{"key":"E","text":"某系统上线前只做了部分扫描就赶工发布，随后发生数据泄露","errorType":"equivocation","reason":"把“部分扫描”当作主张所说的“完成扫描”"}]'::jsonb, null, '{"keys":["A","B"]}'::jsonb, '[]'::jsonb, '{"summary":"主张形式是“完成扫描 → 不会泄露”。反例必须满足前件（按要求完成扫描）又不满足后件（确实发生了泄露），A 与 B 都符合这一形式。","steps":["符号化：P＝上线前完成安全扫描，Q＝不发生数据泄露事故，主张为 若 P 则 Q。","确定检验点：先看该案例的 P 是否成立，再看 Q 是否落空，两步都要有据。","A 直接给出 P 且非 Q；B 中的扫描按既定流程已经完成，泄露仍发生，同样满足反例形式，还解释了漏扫为何不影响 P 的成立。","C、D 的 P 不成立，主张本来就没对它们作承诺；E 用“部分扫描”替换“完成扫描”，属于偷换前提，只是暴露了执行不到位而非主张有误。"],"commonMistakes":[{"option":"C","errorType":"denying-antecedent","why":"由“没做也没出事”推主张错误，方向不成立。"},{"option":"D","errorType":"premise-misidentification","why":"泄露发生在未扫描的系统上，与“扫描后仍泄露”是两类事实。"},{"option":"E","errorType":"equivocation","why":"关键词“完成扫描”的含义被替换，看似反例其实没有满足前件。"}],"takeaway":"判定反例分两步：先确认它满足主张的前提，再确认主张的结论确实落空。"}'::jsonb, array['反例形式', '偷换概念', '多选', '安全检查']::text[], '原创题，场景为上线安全检查争论，重点区分真反例与偷换前提的反例。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cex-005', 1, 'counterexample-rebuttal', array['counterexample-form', 'rebuttal-target']::text[], 2, 45, 'true-false', '反驳方法讨论。', '要反驳“所有 A 都是 B”，只要举出一个结论与主张不同的例子就行，因此举一个不属于 A 的例子同样有效。', null, null, null, '{"value":false}'::jsonb, '[]'::jsonb, '{"summary":"有效反例必须落在主张的主域内：它是 A，却不是 B。不属于 A 的例子与主张不发生冲突，因而推翻不了它。","steps":["把主张写成 若对象是 A 则是 B，其假只可能出现在“是 A 且不是 B”的情形。","举一个不属于 A 的例子，等于让前件为假，此时无论结论是什么，主张都不受影响。","举例“某个非 A 的对象不是 B”，与“所有 A 都是 B”可以同时为真，故不构成反驳。","因此该说法把“结论不同”当成充分条件，判断为错。"],"commonMistakes":[{"errorType":"premise-misidentification","why":"把“与主张唱反调的例子”当成反例，忽略反例必须满足原主张的前提。"},{"errorType":"ignoring-counterexample","why":"反过来也会出错：主张内已存在真反例时，仍用例子数量众多来抵挡。"}],"takeaway":"检验一个例子能否反驳，先问它是否满足被反驳主张的前提。"}'::jsonb, array['反例条件', '全称主张', '判断题']::text[], '原创题，用于纠正“只要例子相反就是反例”的普遍误解。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cex-006', 1, 'counterexample-rebuttal', array['counterexample-form', 'implicit-premise', 'falsification']::text[], 4, 125, 'short-answer', '功能上线后的争论。', '有人在评审会上说：“我们的老客户从来没投诉过这个功能，所以这个功能没有任何问题。”请用两三句话回答：这句话隐含地把哪个条件当成了判断标准？什么样的一个反例就足以削弱它？', null, null, null, '{"checkpoints":[{"id":"c1","label":"把主张改写成可检验形式","keywords":["全称"],"weight":2,"required":true},{"id":"c2","label":"指出隐含前提的漏洞","keywords":["没有投诉"],"weight":3,"required":true},{"id":"c3","label":"给出满足前提却不满足结论的反例","keywords":["反例"],"weight":2,"required":false}],"correctRatio":0.7,"partialRatio":0.45,"modelAnswer":"这句话把“没有投诉”当成了“没有问题”的判断标准，等于提出全称主张：凡是使用这个功能的用户都不会遇到问题。漏洞在于两者并不等价，没有投诉可能只是问题没被发现、用户不知道投诉渠道，或者问题落在老客户的日常习惯之外。真正有削弱力的反例是：某位用户在使用该功能时确实遇到了问题，例如数据被误删或提交后页面卡死，即便他最终没有投诉，也已经与主张的结论不符。"}'::jsonb, '[]'::jsonb, '{"summary":"回答要点：先补出未说出口的等号（投诉等于问题的唯一表现），再把主张改写成可检验的全称形式，最后给出满足前提却推翻结论的反例。","steps":["识别隐含前提：用户遇到问题就一定会投诉；这是把“投诉”当成“问题”的必要表现。","把主张改写为全称形式：所有使用该功能的用户都不会遇到问题，从而可被单个反例检验。","列出替代解释：问题未被察觉、不知投诉渠道、投诉入口被隐藏、样本只有老客户而缺少新用户。","给出反例设计：在使用日志或回访中找到“遇到问题但未投诉”的用户，并说明该情形为何与前件相符、与后件冲突。"],"commonMistakes":[{"errorType":"ignoring-counterexample","why":"只用投诉记录作证据，等于只看能被自己看到的样本。"},{"errorType":"conclusion-overreach","why":"由“没收到投诉”直接跳到“没有任何问题”，结论远强于证据。"}],"takeaway":"遇到“没人反馈所以没问题”，先问：什么问题是他这条渠道看不到的？"}'::jsonb, array['隐含前提', '反例设计', '简答题']::text[], '原创题，场景来自产品评审会，训练把口头全称主张改写为可反驳形式。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cex-007', 1, 'counterexample-rebuttal', array['counterexample-form', 'rebuttal-target', 'dependency-order']::text[], 3, 95, 'ordering', '用户协议免责条款争论。', '产品负责人说：“只要用户注册时勾选了协议，我们公司就不承担数据泄露的责任。”你要用反例来检验这句话。请按最合理的先后顺序排列下列步骤。', null, null, '[{"key":"s1","text":"把这句话改写成条件式：若用户勾选了协议，则公司不承担数据泄露责任"},{"key":"s2","text":"写出反例必须满足的形式：前件成立（已勾选）且后件不成立（公司仍被认定担责）"},{"key":"s3","text":"说明这句话谈的是公司单方规定还是法律效果，据此确定有效的资料来源"},{"key":"s4","text":"在检索到的裁判文书、监管处理决定中筛选符合该形式的具体个案"},{"key":"s5","text":"核对个案中的关键用语与主张是否同一含义，再说明它反驳的是哪一部分"}]'::jsonb, '{"keys":["s1","s2","s3","s4","s5"]}'::jsonb, '[{"keys":["s1","s2","s4","s3","s5"],"note":"如果先按协议条款文本检索、再确定资料来源的性质，s3 与 s4 的顺序可以互换；前提是最终仍需在 s5 校验用语同一含义。"}]'::jsonb, '{"summary":"合理链条是：翻译主张 → 定出反例形式 → 界定主张谈论的对象并确定资料来源 → 检索符合条件的个案 → 校验用语一致性并说明反驳力度。","steps":["不先写成条件式，就无法判断什么算反例，因此 s1 在最前。","s2 把“反驳成功”变成一个可核对的形式要求，避免随手举例。","这句话把公司规定当成法律效果，所以必须先去裁判文书与监管决定这类能对“是否担责”作认定的来源找证据，故 s3 在检索之前。","s5 放在最后：只有确认“勾选协议”“数据泄露”等用语含义一致，反例才真正击中主张，否则可能只是打在一个被改写的版本上。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过 s2 直接找例子，往往找到的是与公司内部处理相关的案例，而非责任认定。"},{"errorType":"premise-misidentification","why":"把公司实际赔付了金额当成反例，却不检查用户是否勾选过协议，前件未核实。"}],"takeaway":"先定反例的形式，再去对的资料库里找，最后核对用语。"}'::jsonb, array['反驳步骤', '反例形式', '排序']::text[], '原创题，场景为免责条款效力争论，训练按依赖顺序组织反驳流程。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-cex-008', 1, 'counterexample-rebuttal', array['counterexample-form', 'rebuttal-target', 'only-if']::text[], 5, 150, 'open-response', '日常争论中的条件与反例。', '领导说：“只有客户满意度高的产品才是好产品。”有人反驳：“那款产品客户满意度很高，但售后成本高到亏损，所以它不是好产品。”请写出：这条主张的条件形式是什么？反驳者举的情形是否构成反例？如果他想反驳成功，应该举出什么样的例子？', null, null, null, '{"scale":[{"score":0,"label":"站队式回答","criteria":"只说支持或不支持哪一方，没有写出主张的条件形式。"},{"score":1,"label":"翻译不完整","criteria":"把主张写成“满意度高就是好产品”，方向已经翻错，后续判断随之失效。"},{"score":2,"label":"正确翻译主张","criteria":"写成“若是好产品则客户满意度高”，并指出满意度高只是必要条件。"},{"score":3,"label":"判定反驳落点","criteria":"指出反驳者的例子是“满意度高但不是好产品”，与前件未成立的情形相容，不构成反例。"},{"score":4,"label":"构造出有效反例","criteria":"给出“公认是好产品但客户满意度低”的例子，并说明还需论证为何该产品确实算好产品。"}],"guidance":"先把“只有……才……”译成条件式；再写出反例的形式要求；然后逐层检查反驳者的例子满足了前件还是否定了前件，最后自己构造一个真正击中主张的例子。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"“只有 P 才 Q”等于“若 Q 则 P”，P（满意度高）是 Q（好产品）的必要条件。反例应是 Q 成立而 P 不成立，即“是好产品却满意度低”。","steps":["符号化：P＝客户满意度高，Q＝是好产品，主张译为 若 Q 则 P。","写出反例形式：需要 Q 且非 P，也就是被公认是好产品、满意度却不高。","检查反驳者的例子：他给出 P 且非 Q（满意度高但不是好产品），这恰好与 若 Q 则 P 相容，因为该主张本来就允许满意度高却其他方面失败。","评估剩余空间：他的例子若要成立，还需要先论证“售后成本决定产品好坏”，这属于另提标准，而不是推翻原主张；真要反驳，可以改用“满意度高但产品明显失败”的情形去质疑该条件是否必要。"],"commonMistakes":[{"errorType":"affirming-consequent","why":"把必要条件当充分条件，就会以为满意度高的产品必须是好产品。"},{"errorType":"premise-misidentification","why":"误把“满意度高却不成功”看成对“满意度高是必要”的否定，方向找错。"},{"errorType":"equivocation","why":"在同一场争论里悄悄替换“好产品”的判定标准，反驳力度无法评估。"}],"takeaway":"先分清被反驳的是“没它不行”还是“有它足够”，再决定要找哪一种反例。"}'::jsonb, array['必要条件', '反例形式', '开放题', '争论场景']::text[], '原创题，场景为产品好坏标准的日常争论，量表按翻译—判定—构造三个层次设计。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dan-001', 1, 'decision-analysis', array['criteria-weighting', 'opportunity-cost']::text[], 2, 90, 'single-choice', null, '小林在两份工作之间犹豫。现公司：月薪 1.8 万，通勤 50 分钟，手上的项目稳定并让她持续做同一类系统。新公司：月薪 2.4 万，通勤 25 分钟，试用期三个月，对方明确说业务方向可能调整。小林说自己最看重未来两年的收入增长和技能积累。只按题干信息，下列哪项分析站得住？', null, '[{"key":"A","text":"只比较月薪就足以定结论，因为收入确实是她自己说出的标准之一","errorType":"premise-misidentification","reason":"把她给出的两条标准只留下方便的那一条"},{"key":"B","text":"新公司在收入这条标准上更优，但“业务方向可能调整”与她看重的技能积累这条标准存在冲突，需要先把方向调整的具体条件问清"},{"key":"C","text":"通勤从 50 分钟缩短到 25 分钟，是这次选择里决定性的优势","errorType":"conclusion-overreach","reason":"题干没有给出通勤在她标准中的位置，却称它决定性"},{"key":"D","text":"两家公司的差别只体现在收入和通勤两项上","errorType":"ignoring-counterexample","reason":"题干已给出第三处差别，却被当作不存在"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"她给了两条标准：收入增长和技能积累。逐项对照题干信息，新公司在第一条上占优，在第二条上有一个题干自己点出的不确定处。","steps":["先把她说的话写成标准清单：收入增长、技能积累，共两条，不能只留一条。","把两个方案分别放到每条标准下填值：收入 2.4 万对 1.8 万，新公司占优。","技能积累这条：现公司被描述为持续做同类系统，新公司则被明确说业务方向可能调整，两者走向不同。","因此合理的结论是有得有失、且第二条标准上信息不足，需要问清“方向调整”具体指什么。","通勤与差别范围都能从题干读出，但题干没有给通勤的权重，也没有把差异限定在两项上。"],"commonMistakes":[{"option":"A","errorType":"premise-misidentification","why":"把已经给出的第二条标准悄悄丢掉，比较就只剩下有利于一方的那一项。"},{"option":"C","errorType":"conclusion-overreach","why":"在没有权重的情况下把一项差异抬成决定性因素。"},{"option":"D","errorType":"ignoring-counterexample","why":"题干已列出试用期与业务方向，用它作反例即可推翻“只差两项”的说法。"}],"takeaway":"比较方案前，先把对方（或你自己）说过的标准全部列出来，一条都不许漏。"}'::jsonb, array['决策分析', '评价标准与权重', '换工作']::text[], '原创题，用换工作情境训练先列全标准再比较，正确项只使用题干已有信息。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dan-002', 1, 'decision-analysis', array['criteria-weighting', 'reversibility', 'opportunity-cost']::text[], 3, 130, 'ordering', null, '小陈工作四年，攒下 60 万元。她在“继续租房（月租 4500 元，押金两个月）”与“用这 60 万付首付买房（月供 6800 元，首付一旦支付不可退回）”之间拿不定主意，打算一周内理清思路。请按合理的先后顺序排列下列步骤。', null, null, '[{"key":"p1","text":"写下这次决定要满足的目标，例如每月可支配现金、居住稳定性、通勤时间、资产增值，并排出它们的重要程度"},{"key":"p2","text":"给最重要的两条目标各设一条不可突破的门槛，例如付完月供后每月剩余现金不得低于某个数额"},{"key":"p3","text":"在目标与门槛都已确定的前提下，把两个方案在每条目标上的具体数值填出来，并补上维修、搬家、利息这些看不见的隐性成本"},{"key":"p4","text":"分别写出选一个方案就放弃了什么，并标出其中不可撤销的部分，例如首付资金被长期占用、换城市的灵活性下降"},{"key":"p5","text":"先做一次可逆的试探：连续三个月每月存下 6800 元模拟月供，观察生活是否吃紧，再决定是否签购房合同"}]'::jsonb, '{"keys":["p1","p2","p3","p4","p5"]}'::jsonb, '[]'::jsonb, '{"summary":"买房与租房的比较必须按“定标准与权重 → 设门槛 → 填数值 → 列机会成本与不可逆项 → 可逆试探”的顺序推进，每一步都以上一步为前提。","steps":["第 1 步在最前：没有目标和权重，第 3 步填出来的数值无从取舍。","第 2 步依赖第 1 步：门槛是从最重要的那几条目标推出来的，先有排序才知道给哪几条设门槛。","第 3 步依赖第 1、2 步：条目和门槛定下来才能逐项填值，也才知道隐性成本要往哪几格里填。","第 4 步依赖第 3 步：只有把两个方案的数值都摆出来，才能看清选一边就放弃了另一边什么。","第 5 步在最后：不可逆的签约要排在可逆试探之后；模拟月供成本低，却能在真实约束下检验第 2 步的门槛。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过定权重直接比较总价与租金，等于用别人的权重替自己做决定。"},{"errorType":"insufficient-evidence","why":"未做可逆试探就签不可撤销的合同，证据强度与决策的不可逆程度不匹配。"}],"takeaway":"不可逆的程度越高，越要把便宜的、可撤销的验证放在签字之前。"}'::jsonb, array['决策分析', '步骤顺序', '租房与买房', '可逆性']::text[], '原创题，用租房与买房的比较训练定标准、列机会成本与先做可逆试探的顺序。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dan-003', 1, 'decision-analysis', array['sunk-cost', 'opportunity-cost']::text[], 3, 100, 'single-choice', null, '阿强报了为期六个月的线下编程班，学费 1.2 万元，合同写明开课后不退。上了两个月后他确定自己听不懂也不喜欢，但他说“钱都交了，不能浪费，得把剩下的四个月上完”。关于他这个理由，下列评价最准确的是？', null, '[{"key":"A","text":"理由成立：既然学费退不回来，就只能靠读完把它换回点什么","errorType":"premise-misidentification","reason":"把收不回的成本当成还能被本次选择改变的东西"},{"key":"B","text":"学费 1.2 万元已经付出且按合同无法收回，接下来真正要比的是这四个月的时间与精力还能用在哪些别的用途上"},{"key":"C","text":"既然沉没成本不该主导，他应该立刻退班，并且从此不再碰任何编程学习","errorType":"conclusion-overreach","reason":"由“不该被学费绑住”推出要放弃一切后续学习"},{"key":"D","text":"只要他坚持上完，学费一定能通过之后的涨薪赚回来","errorType":"insufficient-evidence","reason":"题干没有给出任何收入变化的数据"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"合同已写明不退，学费在任何选择下都一样收不回，所以它不参与接下来这次比较；会变的是接下来的四个月时间。","steps":["先分清两类成本：已付出且收不回的 1.2 万元，以及接下来还要投入的四个月时间与精力。","检验方法：分别设想“上完”和“不再上”，看学费这笔钱有没有区别；没有区别就说明它不该主导。","真正有区别的是未来的投入与产出，所以比较应放在时间用途、其他学习方式、休息收益上。","否定沉没成本并不等于否定继续，如果四个月收益仍高于其他用途，继续也可以。","题干未提供任何涨薪数字，因此不能靠“赚回来”为当前决定辩护。"],"commonMistakes":[{"option":"A","errorType":"premise-misidentification","why":"把不可收回的支出当成还能通过后续行为赎回的东西，前提认错了。"},{"option":"C","errorType":"conclusion-overreach","why":"从一条修正原则推出与自己长期目标相关的过度结论。"},{"option":"D","errorType":"insufficient-evidence","why":"用没有数据支撑的收益预期来证明当前投入合理。"}],"takeaway":"做决定时把已经花掉且收不回的钱写在一栏纸上，另一栏只放未来的投入与产出。"}'::jsonb, array['决策分析', '沉没成本', '机会成本']::text[], '原创题，用培训班场景训练识别沉没成本与只比较未来代价。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dan-004', 1, 'decision-analysis', array['criteria-weighting', 'reversibility']::text[], 4, 130, 'multi-choice', null, '一家小厂要选供应商。甲：报价低 8%，交期 15 天，无本地售后。乙：报价高 8%，交期 7 天，有本地售后，可按月结算。该厂过去三个月因缺料停线两次，每次损失约 4 万元。老板说未来半年最在意的就是不再因缺料停线。按题干信息，下列哪些说法站得住？（选出所有站得住的）', null, '[{"key":"A","text":"在“不再因缺料停线”权重更高这个前提下，交期应先于报价参与比较"},{"key":"B","text":"按题干给出的停线损失估算，交期慢 8 天所造成的损失有可能超过报价低 8% 带来的节省"},{"key":"C","text":"乙同时有本地售后和月结，所以乙在每条标准上都优于甲，不必再加权比较","errorType":"conclusion-overreach","reason":"把两项优势推广成所有标准上占优"},{"key":"D","text":"应把老板那句“最在意不再停线”写成可比较的权重，连同采购成本、现金流一起定权重后再算总账"},{"key":"E","text":"两家报价只差 8%，说明选错了随时能换回来，因此不必检查合同期限与退出条款","errorType":"missing-reasoning-step","reason":"从价差小直接跳到决定可逆，缺少对转换代价的检查"}]'::jsonb, null, '{"keys":["A","B","D"]}'::jsonb, '[]'::jsonb, '{"summary":"老板已经把优先级说出来，剩下的工作是把优先级变成权重、用题干的停线损失做量纲，并单独检查这一决定的可逆程度。","steps":["先确认标准与权重：不再停线为第一优先，报价与结算条件次之，这来自题干而非个人偏好。","统一量纲：题干给出每次停线约 4 万元，因此可以把交期差异折算成金额，与报价差放在同一把尺上比较。","在都定权重量好之后才谈总账，才能看清贵 8% 是否买到更低的停线概率。","乙的两项优势只在对应标准上成立，报价这条上它明确更差，因此不能说全维度占优。","可逆性要单独评估：合同期限、切换供应商的验证周期都构成转换代价，与价差大小无关。"],"commonMistakes":[{"option":"C","errorType":"conclusion-overreach","why":"把局部优势写成全标准优势，正好跨过了报价这条对它不利的标准。"},{"option":"E","errorType":"missing-reasoning-step","why":"结论需要“换供应商的代价很小”这一环，但题干没有提供任何支持。"}],"takeaway":"决策分析三步走：把话变成权重，把差异变成同一个量纲，再单独问一句这一步能不能反悔。"}'::jsonb, array['决策分析', '供应商选择', '加权比较', '可逆性']::text[], '原创题，所有结论均可从题干给出的价差、交期与停线损失数据推出。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dan-005', 1, 'decision-analysis', array['sunk-cost', 'opportunity-cost', 'reversibility']::text[], 3, 120, 'short-answer', null, '会上有人说：“我们已经在这套旧系统上投了 80 万，现在换新系统等于那 80 万白花，所以应该继续用旧系统。”请用三到四句话说明：这次决定应当怎么处理已投的 80 万，真正要比的是什么，以及还需要补哪一条信息。', null, null, null, '{"checkpoints":[{"id":"c1","label":"指出这 80 万已付出且收不回","keywords":["收不回","沉没成本"],"weight":3,"required":true},{"id":"c2","label":"把比较对象转向未来的投入与产出","keywords":["未来","比较"],"weight":3,"required":true},{"id":"c3","label":"写出留在旧系统所放弃的机会成本","keywords":["放弃","机会成本"],"weight":2,"required":false},{"id":"c4","label":"补出迁移这一步的可逆程度与退出方案","keywords":["可逆","退出方案"],"weight":2,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"这 80 万已经花掉且收不回，属于沉没成本，两种选择下这笔钱都没有区别，不该继续主导结论。真正要比较的是从今往后的投入和产出：旧系统未来每年的维护费、人力与被它卡住的需求，新系统的迁移费用与收益。同时要把留在旧系统所放弃的东西写清楚，也就是机会成本，例如新业务上线速度和团队不再被迫做的重复工作。最后补一条信息：这次迁移有多可逆，能不能并行保留旧系统一段时间、有没有退出方案；越难反悔，越需要更硬的证据才签字。"}'::jsonb, '[]'::jsonb, '{"summary":"“不能浪费已投入”是典型的沉没成本论证。正确的做法是把已花掉的钱移出比较，只比未来，并同时评估这一步的可逆性。","steps":["用“两种选择下这笔钱是否不同”检验它是否属于沉没成本，结论是相同，因此应移出比较。","把未来的成本与收益逐项列出，形成同一时间范围内的可比较清单。","补上机会成本：留在旧系统意味着放弃某些新业务能力和团队时间。","评估可逆性：能并行运行就有退路，证据门槛可以低一些；一次性停用旧系统则不可逆，需要更强的验证。","最后可以把结论写成条件句：如果未来两年维护费高于迁移差额，就迁移，反之继续。"],"commonMistakes":[{"errorType":"premise-misidentification","why":"把无法收回的历史支出当成还能被当前选择改变的前提。"},{"errorType":"false-dilemma","why":"把它说成“要么白花 80 万要么继续用”，漏出了并行运行与分阶段迁移这些安排。"}],"takeaway":"问一句“这笔钱在两个选项下会不会不一样”，一样就出局，不一样才进入比较。"}'::jsonb, array['决策分析', '沉没成本', '系统替换']::text[], '原创题，取自技术选型会议里的沉没成本论证，要点与范文逐条对应。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dan-006', 1, 'decision-analysis', array['criteria-weighting', 'opportunity-cost', 'reversibility']::text[], 5, 170, 'ordering', null, '一位工程师在考虑是否接受外地一份薪资更高、但需要举家搬迁的工作。她给自己定了两周的决策流程。请按步骤之间的依赖先后，把下列六步排序。', null, null, '[{"key":"q1","text":"写下她在意的标准：收入、孩子上学、专业成长、家庭时间，并排出它们的重要程度"},{"key":"q2","text":"给最重要的两条标准各定一条门槛，例如孩子转学的适应期不得超过一个学期"},{"key":"q3","text":"在标准与门槛已定的前提下，分别填出留下与去外地在每条标准上的具体数值，并标出还拿不到、需要去问的项"},{"key":"q4","text":"把两个选择各自放弃了什么列成机会成本清单，其中写明搬过去再搬回来需要付什么代价"},{"key":"q5","text":"按第 1 步的权重给两个方案打分，再做一次敏感性检查：把最看重的两条权重翻倍，结论会不会反过来"},{"key":"q6","text":"先谈下一个可逆的安排：去外地短期工作两周、孩子暂不转学，再据结果决定是否签搬迁和租房合同"}]'::jsonb, '{"keys":["q1","q2","q3","q4","q5","q6"]}'::jsonb, '[]'::jsonb, '{"summary":"顺序原则是：标准与权重先定，门槛其次，然后取值、列机会成本、加权打分与敏感性检查，最后用可逆安排压住不可逆的签字。","steps":["第 1 步在前：没有权重，第 3 步的数值只能凭直觉取舍。","第 2 步依赖第 1 步：门槛只能挂在权重最高的那几条标准上。","第 3 步依赖第 1、2 步：条目和门槛确定了才知要填哪些格子，也才能发现哪一项数据缺失。","第 4 步依赖第 3 步：机会成本来自两个方案的差值，数值未填就无法列出放弃了什么。","第 5 步依赖第 1 与第 4 步：打分需要权重与完整清单；敏感性检查用来判断结论是否只差在权重上。","第 6 步在最后：搬迁与合同不可逆，短期试用可逆，把可逆的一步放在签字之前是整个流程的收尾原则。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过机会成本清单直接打分，标准里就少了一整块信息，分数没有依据。"},{"errorType":"insufficient-evidence","why":"在权重一改就会翻转的情况下仍直接签下不可逆的合同。"}],"takeaway":"打分之后一定要多做一步：把最看重的权重挪一挪，看结论会不会跟着翻。"}'::jsonb, array['决策分析', '步骤顺序', '搬迁决策', '可逆性']::text[], '原创题，用举家搬迁的工作选择训练权重、机会成本与可逆试探的先后关系。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dan-007', 1, 'decision-analysis', array['criteria-weighting', 'sunk-cost', 'opportunity-cost']::text[], 4, 150, 'short-answer', null, '你的团队只能接一件事：一个是报价较高但要求两周内交付的外包项目，另一个是继续做自有产品（预计三个月后开始有收入），两者无法同时推进。请写出你的分析步骤，并说明怎么处理“已经为产品投入的半年时间”和“错过这单也许就没有类似客户”这两点。', null, null, null, '{"checkpoints":[{"id":"c1","label":"先列出标准并给权重","keywords":["标准","权重"],"weight":3,"required":true},{"id":"c2","label":"把已投入的半年时间算作沉没成本","keywords":["半年","沉没成本"],"weight":3,"required":true},{"id":"c3","label":"写出两个选择各自的机会成本","keywords":["机会成本","放弃"],"weight":2,"required":true},{"id":"c4","label":"区分可逆与不可逆部分并去问","keywords":["可逆","不可逆"],"weight":2,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"第一步把标准列出来并给权重：三个月内的现金、风险大小、对产品的推进影响各占多少，没有权重就没法比较。第二步把已经投入产品的半年时间算作沉没成本，它在两个选择里都收不回，所以只能当背景信息，不该给继续做产品这一项额外加分。第三步分别写出机会成本：接外包就放弃三个月的产品进度，做产品就放弃这笔试单的现金和这类客户资源。第四步区分可逆与不可逆的部分：交付时间或许可以谈、客户或许可以排到下一批，这些是可逆的；团队解散和产品延期三个月则偏向不可逆。最后先向客户问一句能否延后两周交付，用回答检验“只能二选一”是不是真的成立，再按权重做最终取舍。"}'::jsonb, '[]'::jsonb, '{"summary":"两个方案互斥时，分析顺序是先定权重、把历史投入移出比较、列清双方放弃了什么，再检查这个二选一里哪些部分其实可以谈。","steps":["把“现金、风险、产品推进”写成标准并赋权重，缺权重时任何排序都只是偏好。","已投入的半年时间在两个选项下都一样收不回，检验后应归入沉没成本、不参与加分。","机会成本要对两个方向各列一份：一边是产品进度，一边是这笔现金与客户资源。","按权重给两个方案打分，并特别标出哪些部分可逆（交期、客户排期）哪些不可逆（团队遣散、延期三个月）。","最后用一次低成本的询问去测试题目给定的约束，避免把一个可能松动的约束当成不可改变的前提。"],"commonMistakes":[{"errorType":"false-dilemma","why":"未去确认交期能否谈、客户能否排队，就把两个方案当作唯一可能性。"},{"errorType":"premise-misidentification","why":"用已投入的半年时间为“必须继续做产品”辩护，把收不回的东西当成前提。"}],"takeaway":"二选一之前先检查这个“二”是不是别人替你划好的，能谈的条件就还是可逆项。"}'::jsonb, array['决策分析', '机会成本', '沉没成本', '取舍']::text[], '原创题，用外包项目与自有产品的冲突训练权重、沉没成本与可逆性检查。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dan-008', 1, 'decision-analysis', array['criteria-weighting', 'opportunity-cost', 'reversibility', 'sunk-cost']::text[], 5, 180, 'open-response', null, '你要在两条路里选一条，家里只能支持其中一条：读研两年，期间没有工资，毕业后的岗位方向与现在不同；或者直接工作，月薪 1.1 万元，两年后可以跳槽。请写出你的分析：你会定哪些标准与各自权重、两条路分别放弃了什么、哪些部分可逆哪些不可逆、以及正式决定前你打算做一次什么可逆的试探。', null, null, null, '{"scale":[{"score":0,"label":"只给偏好","criteria":"直接说读研更好或工作更好，没有给出任何比较标准，也没有说明自己据什么判断。"},{"score":1,"label":"列标准但未加权","criteria":"写出收入、发展、兴趣等若干条标准，但没有排重要程度，因此两条路仍然无法比较。"},{"score":2,"label":"加权并算清放弃","criteria":"给标准排了权重，同时列出两条路各自放弃的两年工资、时间与发展窗口，指出了机会成本。"},{"score":3,"label":"区分可逆性","criteria":"进一步分清哪些两年后还能改（岗位方向、跳槽），哪些错过就难补（招生批次、连续两年资历），并据此提出不同的证据要求。"},{"score":4,"label":"设计可逆试探并设门槛","criteria":"还写出正式决定前的低成本试探，如旁听课程、找在读的人问一周安排、拿到一份录用或实习机会，并预先写明看到什么结果就放弃当前倾向。"}],"guidance":"按“定标准与权重 → 填两条路各自的数值 → 列双方放弃了什么 → 标注可逆与不可逆 → 设计一次可逆试探并预设放弃条件”五段来写，250 字以内。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"这类人生选择没有标准答案，能拉开差距的是有没有先定权重、有没有把放弃的东西算出来、有没有按可逆程度分配证据要求。","steps":["先把题干已有的信息换成可比条目：两年的工资差、无收入期、方向改变、两年后可跳槽。","权重必须自己给并写明理由，因为不同权重会直接给出不同答案，这一步要透明。","机会成本双向列：读研放弃两年工资与资历连续，工作放弃方向转换与应届生身份可用的那次机会。","区分可逆与不可逆：跳槽与转岗偏可逆，招生批次与某些年龄窗口偏不可逆，不可逆的那一侧需要更强证据。","最后设计一次可逆试探并预设放弃条件，同时注意不要在理由里用已花的时间当作必须读研的依据。"],"commonMistakes":[{"errorType":"appeal-to-majority","why":"用“大家都考研”或“大家都说早工作好”来替代自己的权重与证据。"},{"errorType":"conclusion-overreach","why":"由两年的差异推出这一生的收入或发展已被决定。"},{"errorType":"circular-reasoning","why":"用“我已经准备了这么久所以必须读研”来证明读研值得，准备时间本身并非收益证据。"}],"takeaway":"把权重写成数字、把放弃写成清单、把可逆性写成一道门槛，选择的质量就会明显变化。"}'::jsonb, array['决策分析', '开放题', '读研与工作', '机会成本']::text[], '原创题，量表按回答层级递进设计，供自评与可选的模型反馈使用。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ded-001', 1, 'deductive-reasoning', array['syllogism', 'validity-vs-truth']::text[], 2, 50, 'single-choice', null, '线上读书群里两条笔记：①所有被标成重点的章节都收进了目录；②有些收进目录的章节没有配套练习。如果这两条都为真，下面哪项必然为真？', null, '[{"key":"A","text":"有些被标成重点的章节没有配套练习","errorType":"missing-reasoning-step","reason":"把两个前提各自提到的集合直接当成有交集"},{"key":"B","text":"凡是收进目录的章节都被标成了重点","errorType":"premise-misidentification","reason":"把第一条前提的方向弄反了"},{"key":"C","text":"有配套练习的章节里，有些被标成了重点","errorType":"conclusion-overreach","reason":"从可能为空的集合里推出存在性结论"},{"key":"D","text":"现有前提不足以确定“重点章节”与“没有配套练习的章节”是否重叠"}]'::jsonb, null, '{"keys":["D"]}'::jsonb, '[]'::jsonb, '{"summary":"两条前提只给出“包含”和“有交集”两种关系，没有锁定那两个子集的位置，所以任何关于它们交集的存在性结论都不能必然推出。","steps":["把第一条改写成集合关系：重点章节 ⊆ 目录章节。","第二条是：目录章节 与 没有练习的章节 至少有一个共同成员。","那个共同成员可能完全落在重点章节之外，也可能部分落在其中，前提没有排除任一种。","A 断言存在“既是重点又没练习”的章节，无法保证；B 是第一条的非法换位；C 还需要知道重点章节有没有练习。","因此唯一稳妥的判断是 D：现有前提不足以确定这两个集合是否重叠。"],"commonMistakes":[{"option":"A","errorType":"missing-reasoning-step","why":"两条前提分别只说到目录，中间缺少把“没练习”和“重点”连起来的一环。"},{"option":"B","errorType":"premise-misidentification","why":"“所有重点都在目录里”不等于“所有目录里的都是重点”，换位后前提变了。"},{"option":"C","errorType":"conclusion-overreach","why":"前提甚至没有保证重点章节一定存在，更不能保证它们有配套练习。"}],"takeaway":"看到“所有／有些”的推理，先画集合图，问清前提是否真的锁定了两个集合的相对位置。"}'::jsonb, array['三段论', '必然为真', '集合关系']::text[], '原创题，场景取自线上读书群的笔记约定，用于训练判断结论是否被前提必然推出。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ded-002', 1, 'deductive-reasoning', array['modus-tollens', 'contrapositive', 'denying-antecedent']::text[], 3, 80, 'single-choice', '项目在群里同步了三条约定，成员据此讨论本周发布安排。', '项目群三条记录：①如果这次代码评审通过，测试排期就会提前；②测试排期没有提前；③只要测试排期提前，就能赶在本周五发布。据此必然能推出下列哪一项？', null, '[{"key":"A","text":"代码评审没有通过，本周五也无法发布","errorType":"denying-antecedent","reason":"由排期没提前就断言周五发布不了"},{"key":"B","text":"代码评审没有通过；本周五能否发布，现有条件不足以确定"},{"key":"C","text":"代码评审其实通过了，只是排期被别的事挡住了","errorType":"insufficient-evidence","reason":"引入前提里没有的新信息来替换已推出的结论"},{"key":"D","text":"③说明“排期提前”是“周五发布”的必要条件","errorType":"premise-misidentification","reason":"把“只要……就……”的充分条件读成必要条件"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"①②合起来是否定后件式，能有效推出评审未通过；但③只说排期提前足以赶上周五，没提前时周五情况保持开放。","steps":["符号化：P＝评审通过，Q＝排期提前，R＝周五能发布。三条记录是 P→Q、非 Q、Q→R。","由 P→Q 与 非 Q，用否定后件式得到 非 P，即评审没有通过。","Q→R 与非 Q 组合属于否定前件，推不出 非 R，所以周五能否发布无法确定。","检查选项：A 多算了“周五无法发布”；C 与已推出的 非 P 冲突且另加假设；D 把充分条件说成必要条件。","只有 B 恰好停在前提允许的距离上。"],"commonMistakes":[{"option":"A","errorType":"denying-antecedent","why":"排期没提前只是失去一条充分路径，不能据此宣布周五一定发不了。"},{"option":"C","errorType":"insufficient-evidence","why":"“被别的事挡住”在前提里没有任何依据，却推掉了有效的否定后件结论。"},{"option":"D","errorType":"premise-misidentification","why":"“只要 Q 就 R”给出的是充分条件，必要条件应是“若 R 则 Q”。"}],"takeaway":"多条条件串起来时，逐条问“这一条给我一个方向还是双向”，不要顺路把方向换掉。"}'::jsonb, array['演绎链条', '否定后件式', '条件推理']::text[], '原创题，场景取自软件项目群里的排班与发布约定，用于训练多前提链条。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ded-003', 1, 'deductive-reasoning', array['validity-vs-truth', 'syllogism', 'affirming-consequent']::text[], 4, 100, 'single-choice', null, '一篇数码测评写道：“凡是通过 3C 认证的充电器都不会过热；这款充电器没有过热；所以它通过了 3C 认证。”对这段论证，下列哪项评价是正确的？', null, '[{"key":"A","text":"推理形式是有效的，只是第一条前提未必属实","errorType":"premise-misidentification","reason":"把结论听起来合理当成了形式有效"},{"key":"B","text":"推理形式无效：从“通过认证就不会过热”和“没有过热”，推不出“通过了认证”"},{"key":"C","text":"只要两条前提为真，结论就一定为真","errorType":"conclusion-overreach","reason":"在形式无效的前提下仍宣布结论必然成立"},{"key":"D","text":"结论一定为假，这款充电器肯定没通过认证","errorType":"insufficient-evidence","reason":"由推理无效反手宣布结论为假"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"论证形式是“若 P 则 Q；Q；所以 P”，属于肯定后件；能找到前提全真而结论为假的解释，因此形式无效，结论真假也不由它决定。","steps":["拆出结构：P＝通过 3C 认证，Q＝不会过热；前提是 P→Q 与 Q，结论是 P。","检验有效性的方法：设想前提都真而结论为假，看是否有矛盾。","构造解释：某充电器没通过认证，但本身发热极低，同样满足“没有过热”。前提全真、结论为假且无矛盾。","所以形式无效，A 与 C 都不成立；无效也不等于结论为假，D 说过头了。","B 准确地只判定形式层面出了问题。"],"commonMistakes":[{"option":"A","errorType":"premise-misidentification","why":"有效性只看形式，这段的形式本身就漏环，不能只归因到前提真假。"},{"option":"C","errorType":"conclusion-overreach","why":"“前提真则结论必真”是有效性的定义，此处并不满足。"},{"option":"D","errorType":"insufficient-evidence","why":"无效推理的结论可真可假，需要额外证据才能判定。"}],"takeaway":"评一段演绎，只问一句：前提全真时结论还能是假的吗？能，它就无效。"}'::jsonb, array['有效性', '真理与有效', '论证评估']::text[], '原创题，场景取自网购数码产品的测评文章，用于区分推理有效性与前提真实性。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ded-004', 1, 'deductive-reasoning', array['syllogism', 'validity-vs-truth']::text[], 2, 40, 'true-false', null, '团购群里有人说：“这次到货的草莓里有几盒是坏的，所以坏草莓里肯定有几盒不是这次到货的。”请判断：这个推理在形式上是否有效？', null, null, null, '{"value":false}'::jsonb, '[]'::jsonb, '{"summary":"前提只说“到货的草莓”与“坏草莓”两个集合有交集，结论却要求存在不属于本次到货的坏草莓，这一步前提里没有依据。","steps":["把前提改写为：有些到货的草莓是坏的，即两个集合至少共用一个成员。","结论要求的是：有些坏的草莓不在本次到货范围内，这是一个新的存在性断言。","设想所有坏草莓都出自本次到货，此时前提仍为真，结论却为假。","存在前提真而结论假的解释，说明推理无效，应判为“否”。"],"commonMistakes":[{"errorType":"premise-misidentification","why":"把“有些 S 是 P”的合法换位（有些 P 是 S）当成了“有些 P 不是 S”。"},{"errorType":"ignoring-counterexample","why":"没有考虑“坏草莓全部来自本次到货”这种同样符合前提的情形。"}],"takeaway":"“有些”开头的判断只能对称换位，不能顺手加上“不是”。"}'::jsonb, array['三段论', '换位', '有效性判断']::text[], '原创题，场景取自社区团购的售后对话，针对“有些”命题的换位错误。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ded-005', 1, 'deductive-reasoning', array['modus-tollens', 'necessary-condition', 'exhaustive-cases']::text[], 4, 130, 'multi-choice', '车间本周只排早班与晚班，每条约定都已张贴在看板上。', '车间排班约定：①如果小李排早班，小王也会排早班；②只有小陈排早班，小周才排早班；③小陈和小王不会同周都排早班；④本周小周排了早班。关于本周，下面哪些判断必然为真？（选出所有必然为真的）', null, '[{"key":"A","text":"小陈本周排了早班"},{"key":"B","text":"小王本周没有排早班"},{"key":"C","text":"小李本周没有排早班"},{"key":"D","text":"小李本周排了早班","errorType":"missing-reasoning-step","reason":"跳过③④两环，链条没推到底"},{"key":"E","text":"仅凭这些条件无法确定小陈是否排早班","errorType":"premise-misidentification","reason":"把②里的必要条件当成了充分条件"}]'::jsonb, null, '{"keys":["A","B","C"]}'::jsonb, '[]'::jsonb, '{"summary":"②“只有小陈排早班，小周才排早班”等于“小周排早班则小陈排早班”，配合④就能一环环推出三个人的班次。","steps":["翻译②：只有 P 才 Q 等于 若 Q 则 P，即 小周早班 → 小陈早班。","由④小周排早班，肯定前件得 小陈排早班，即 A 为真。","由③小陈与小王不同周都排早班，且小陈已排早班，得 小王没排早班，即 B 为真。","由①小李早班 → 小王早班；现已知小王没排早班，否定后件得 小李没排早班，即 C 为真。","D 与 C 直接冲突；E 低估了②的翻译结果，小陈是否排早班已被④确定。"],"commonMistakes":[{"option":"D","errorType":"missing-reasoning-step","why":"只用了①，漏掉④→②→③这条主线，才误以为小李可以排早班。"},{"option":"E","errorType":"premise-misidentification","why":"把“只有小陈排早班”读成“小陈排早班就一定人人都排早班”，方向反了。"}],"takeaway":"链条题先把每句条件统一成“若……则……”，再从已知事实那一端一路推到底。"}'::jsonb, array['多前提链条', '必要条件', '排班场景']::text[], '原创题，场景取自制造车间的排班看板，用于训练把自然语言条件转成链条推理。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ded-006', 1, 'deductive-reasoning', array['affirming-consequent', 'implicit-premise', 'necessary-condition']::text[], 4, 140, 'short-answer', null, '业主群里有人写：“凡是装了门禁卡的住户都能刷卡进地库，老张能刷卡进地库，所以他一定装了门禁卡。”请用两三句话指出这段推理的问题，并说明要让它成立还需要补充什么前提。', null, null, null, '{"checkpoints":[{"id":"c1","label":"判定推理形式无效","keywords":["无效","不能必然推出"],"weight":3,"required":true},{"id":"c2","label":"点明肯定后件的错误","keywords":["肯定后件","后件"],"weight":2,"required":true},{"id":"c3","label":"给出需要补充的前提","keywords":["补充前提","必要条件"],"weight":2,"required":true},{"id":"c4","label":"举出同样成立的解释","keywords":["代刷","访客二维码"],"weight":1,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"这段推理形式无效：第一条话只说明装了门禁卡足以刷卡进地库，而老张能进地库属于肯定后件，不能反推他装了卡。也可能是家人代刷或用了访客二维码。要补充前提“凡是能刷卡进地库的住户都装了门禁卡”，也就是把装卡说成进地库的必要条件，结论才站得住。"}'::jsonb, '[]'::jsonb, '{"summary":"原规则只把“装门禁卡”写成“能刷卡进地库”的充分条件，推理却从结果反推原因，必须补上反向规则才有效。","steps":["符号化：P＝装了门禁卡，Q＝能刷卡进地库；群里的话是 若 P 则 Q。","已知 Q，结论写 P，这是肯定后件，形式无效。","列出前提兼容的其他解释：家人代刷、访客二维码、物业临时授权。","补出反向规则 若 Q 则 P，也就是“装卡是进地库的必要条件”，此时 P→Q 与 Q→P 合成充要条件，结论才成立。","顺带检查：补充前提本身是否为真，需要向物业核实，它是新增假设而不是群里那句话。"],"commonMistakes":[{"errorType":"affirming-consequent","why":"把“有卡就能进”听成“能进就一定有卡”。"},{"errorType":"missing-reasoning-step","why":"没有把缺少的反向规则写出来，就直接宣布结论可靠。"}],"takeaway":"看到“能……所以一定……”，先问一句：这条规则反过来也成立吗？"}'::jsonb, array['肯定后件', '隐含前提', '业主群场景']::text[], '原创题，场景取自小区业主群关于门禁的日常争论。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ded-007', 1, 'deductive-reasoning', array['dependency-order', 'validity-vs-truth', 'implicit-premise']::text[], 3, 95, 'ordering', null, '同事在周报里写了一段推论，你要判断它是否站得住。按最合理的先后顺序排列下列步骤。', null, null, '[{"key":"s1","text":"把周报里的推论拆成“前提—结论”的形式，逐条编号"},{"key":"s2","text":"假设这些前提都为真，检查结论是否被它们唯一确定"},{"key":"s3","text":"找出推导中被省略的一环，尤其是没说出口的限定条件"},{"key":"s4","text":"逐条核对前提本身是否为真，包括制度条款是否已换新版"},{"key":"s5","text":"写出结论：哪部分已被保证，哪部分还依赖未确认的事实"}]'::jsonb, '{"keys":["s1","s2","s3","s4","s5"]}'::jsonb, '[{"keys":["s1","s4","s2","s3","s5"],"note":"也可以先核对前提真实性再做形式检验；两种顺序都能得到同一份结论，只是先查形式更能省下核对成本。"}]'::jsonb, '{"summary":"评估一段演绎要先把内容格式化，再在“假定前提为真”的条件下检查形式，最后才回到事实层面核对前提。","steps":["不先拆成前提与结论，后面既没法检查形式，也没法核对具体条款。","形式检验只需假设前提为真，因此可以先于事实核对完成，能快速定位问题在结构还是材料。","推导中缺失的一环通常就藏在限定条件里，必须在形式检验之后立刻找出来。","确认结构没问题或问题在哪之后，再逐条核对前提真伪，例如制度是否有新版本。","最后把结论分成“已被保证”和“仍悬着”两部分写下，避免把有效性当成真理性。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过形式检验直接核对事实，会误以为材料充足就等于推论可靠。"},{"errorType":"premise-misidentification","why":"把周报里的背景介绍当成结论所在的前提，检查对象就错了。"}],"takeaway":"先问“形式通不通”，再问“材料真不真”，最后写清哪部分还悬着。"}'::jsonb, array['步骤顺序', '论证评估', '职场写作']::text[], '原创题，场景取自团队周报评审，用于训练评估他人推论的操作顺序。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ded-008', 1, 'deductive-reasoning', array['validity-vs-truth', 'implicit-premise', 'evidence-relevance']::text[], 5, 180, 'open-response', null, '家庭聚会上，一位亲戚说：“我认识的三个抽烟的人都活过了八十岁，可见吸烟没那么可怕，那些医学指南是在吓唬人。”请写出你的评价：他这段话要成立还依赖哪些没说出口的前提？这些前提可靠吗？你会给出一个怎样的结论？', null, null, null, '{"scale":[{"score":0,"label":"照单全收","criteria":"认为亲眼见到的例子最有说服力，不需要再追问别的条件。"},{"score":1,"label":"仅表怀疑","criteria":"觉得这话不对劲，但说不出问题具体出在哪一步。"},{"score":2,"label":"补出隐含前提","criteria":"能写出该论证依赖“这三个例子能代表所有吸烟者”“指南的结论与个案可以对照”等未说明的前提。"},{"score":3,"label":"评估前提强度","criteria":"进一步指出三个熟人样本量小、年龄层集中，而且只数了活下来的人，前提本身并不可靠。"},{"score":4,"label":"给出匹配证据的结论","criteria":"还能说明指南依据的是大样本人群比较，写出自己既不否认风险、也不把个案当证据的结论与信心程度。"}],"guidance":"先补出他依赖的未说明前提，再逐个评估这些前提的证据强度，最后写一个与证据宽度相匹配的结论。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"这段话把“存在三个高寿命吸烟者”当成对统计结论的反驳，它要成立需要样本可代表、指标可对照两个前提，而这两个前提都站不住。","steps":["把论证补全：三个熟人都高寿（前提）→ 他们能代表吸烟者整体（隐含前提）→ 所以指南的关联被推翻（结论）。","检查隐含前提：样本量 3、来自同一社交圈，且只包含活到八十岁以上还能被认识到的吸烟者，属于有系统性缺失的样本。","检查对照关系：指南比较的是同龄人群体的死亡率差异，个案寿命无法与之对照，两者说的不是同一件事。","给出与证据匹配的结论：个案可以提示我们要去看大样本证据，但不能否定它；能说的只是“我对具体风险幅度还不清楚”。"],"commonMistakes":[{"errorType":"hasty-generalization","why":"从三个熟人的寿命推出关于所有吸烟者的结论。"},{"errorType":"ignoring-counterexample","why":"只统计能被见到的长寿吸烟者，没有把早逝的吸烟者纳入同一份观察。"},{"errorType":"conclusion-overreach","why":"由“我的例子和指南不一致”跳到“指南是在吓唬人”。"}],"takeaway":"有人用身边个例反驳统计结论时，先问：他的样本是怎么被挑出来的，和结论比的是同一件事吗？"}'::jsonb, array['隐含前提', '证据强度', '家庭沟通', '开放题']::text[], '原创题，场景取自家庭聚会的健康话题讨论；量表依据从接受到补前提、再到评估证据强度的常见回答层级设计。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ind-001', 1, 'inductive-reasoning', array['inductive-strength', 'sample-size']::text[], 2, 50, 'single-choice', null, '小赵在同一家网店一次买了两只同一批次的充电头，两周内两只都坏了，于是下结论：“这家店卖的充电头全都质量不合格。”下列哪项评价最准确？', null, '[{"key":"A","text":"两只都坏，足以支持“全都不合格”这个结论","errorType":"hasty-generalization","reason":"把两个个案直接当成全店结论的证据"},{"key":"B","text":"样本只有两只、又来自同一批次，既不多样也不独立，至多说明这一批可能有问题"},{"key":"C","text":"两只都坏，说明这家店充电头的不合格率就是 100%","errorType":"conclusion-overreach","reason":"把两件的比例说成全店的比例"},{"key":"D","text":"可以确定问题出在小赵自己的使用方式上","errorType":"insufficient-evidence","reason":"没有任何使用环节的信息就锁定了原因"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"同一批次的两只产品在工艺和来料上高度相关，不能当两个独立样本；“全都”是覆盖全店的全称结论，证据宽度远不够。","steps":["先确认结论范围：“这家店卖的充电头全都不合格”是关于全部库存的全称判断。","再确认样本：数量 2，且来自同一批次，二者共享同一生产工艺，失败原因很可能相同。","共享原因意味着这两个观察近似于一次观察，样本的多样性接近于零。","因此合理的归纳止步于“这一批可能有问题，值得向店铺和厂家核对该批次的整体反馈”。","A 与 C 都把范围从一批扩到全店；D 引入的前提（使用方式）在题目里根本没有信息。"],"commonMistakes":[{"option":"A","errorType":"hasty-generalization","why":"两件坏样本数量小、又不具代表性，却直接支撑了全称结论。"},{"option":"C","errorType":"conclusion-overreach","why":"2/2 只是这一只小样本里的比例，不能当成全店不合格率。"},{"option":"D","errorType":"insufficient-evidence","why":"题目没给出任何使用场景信息，锁定用户原因是凭猜测。"}],"takeaway":"评估归纳结论时，先看它说了多大范围，再看样本是否覆盖了这个范围。"}'::jsonb, array['归纳强度', '样本代表性', '消费决策']::text[], '原创题，场景取自网购数码配件后的差评经历，用于训练评估个案归纳的证据宽度。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ind-002', 1, 'inductive-reasoning', array['inductive-strength', 'sample-size']::text[], 3, 75, 'single-choice', '学生会做了一份关于图书馆开放时间的问卷。', '学生会随机抽取 50 名大一新生询问“是否赞成延长图书馆开放时间”，48 人赞成，于是宣布“全校学生都需要延长开放时间”。下列哪项信息最能削弱这一推断？', null, '[{"key":"A","text":"被抽中的 50 人里有 48 人表示赞成","errorType":"insufficient-evidence","reason":"样本量大但覆盖不到高年级，仍不足以支撑全校结论"},{"key":"B","text":"大三、大四学生多数在校外实习，白天几乎不在学校"},{"key":"C","text":"延长开放时间需要增加夜间安保和照明预算"},{"key":"D","text":"抽样是随机进行的，所以这个样本一定代表全校","errorType":"conclusion-overreach","reason":"随机只能保证对被抽的那个人群有代表性"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"推断的问题不在人数而在覆盖范围：抽样框只包含大一新生，任何说明高年级与大一需求不同的信息都会直接削弱它。","steps":["找出结论的范围：全校学生；找出样本的范围：只有大一新生。","两者之间缺的前提是“大一新生与高年级学生对开放时间的需求相同”。","B 直接攻击这条前提：高年级多数在校外实习，几乎用不到夜间开放。","A 只是重复原有证据；C 谈的是成本，与“需要的人有多少”无关；D 误把随机当成覆盖全校。"],"commonMistakes":[{"option":"A","errorType":"insufficient-evidence","why":"48/50 支持的是大一本群体的意见，对全校推断并不构成削弱，也不构成充分支持。"},{"option":"D","errorType":"conclusion-overreach","why":"随机抽样只在抽样框内保证代表性，抽样框本身缺了高年级就无法外推。"}],"takeaway":"看到“调查结果显示大家……”，先比对结论范围与抽样范围是不是同一个。"}'::jsonb, array['抽样代表性', '归纳强度', '校园场景']::text[], '原创题，场景取自高校学生会的问卷公告，用于训练识别抽样框与结论范围不一致。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ind-003', 1, 'inductive-reasoning', array['analogical-reasoning', 'inductive-strength']::text[], 3, 45, 'true-false', null, '两家门店属于同一家连锁咖啡品牌、使用相同的豆子和供应链。有人说：“由此可以必然推出这两家门店的美式咖啡口味相同。”请判断这个说法是否正确。', null, null, null, '{"value":false}'::jsonb, '[]'::jsonb, '{"summary":"相同品牌和供应链只是相关的相似点，类比至多提高某种可能，推不出“必然”；出杯还受设备校准、水质、店员和存放时间影响。","steps":["识别推理类型：由两家店在若干属性上相同，推出在另一个属性上也相同，属于类比推理。","类比强度取决于相似点与目标属性的相关程度，豆子与供应链确实相关，因此“口味接近”是有力的推测。","但磨粉刻度、萃取水温、水质硬度和出品间隔这些差异会明显改变口味，前提并未排除它们。","“必然推出”要求任何情况下都不可能出现例外，而这里显然能设想到口味不同的情形，所以该说法不成立。"],"commonMistakes":[{"errorType":"conclusion-overreach","why":"把类比给出的或然性说成了必然性。"},{"errorType":"equivocation","why":"把“同品牌、同供应链”悄悄换成了“所有出品条件都相同”。"}],"takeaway":"类比只能回答“有多可能”，回答不了“是不是必然”。"}'::jsonb, array['类比推理', '必然与或然', '消费场景']::text[], '原创题，场景取自连锁咖啡门店的消费体验，针对类比结论被说成必然的常见错误。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ind-004', 1, 'inductive-reasoning', array['inductive-strength', 'variable-control', 'confounder']::text[], 4, 115, 'multi-choice', '投放渠道、素材版本和站内页面这一段时间内都可能调整。', '运营同事看到“换上新广告素材后，点击到注册的转化率在三天内从 4% 升到 6%”，就下结论：“是新素材带来了注册提升。”下列哪些做法能提高这个归纳结论的可靠性？（选出所有正确的）', null, '[{"key":"A","text":"同期保留一组流量继续投放旧素材做对照，比较两组注册率"},{"key":"B","text":"把观察窗口从三天延长到四周，看两组差异是否稳定存在"},{"key":"C","text":"逐项核对同期是否有促销、节假日或渠道投放结构变化并予以排除"},{"key":"D","text":"只呈现转化率最高的那一天数据，让结论看起来更明确","errorType":"ignoring-counterexample","reason":"只挑支持结论的样本，回避其余天数的表现"},{"key":"E","text":"把结论改写成“用新素材必然提高注册率”，这样表述更清楚","errorType":"conclusion-overreach","reason":"把或然的归纳结论升级成必然规律"}]'::jsonb, null, '{"keys":["A","B","C"]}'::jsonb, '[]'::jsonb, '{"summary":"原结论是“时间上的共变所以是因果”，要加强它就要提供对照、扩大观察、并排除同期其他变化，而不是筛选数据或加强措辞。","steps":["把结论写成因果假设：素材更换（P）导致注册率上升（Q）。","A 提供同期对照：如果只有新素材那组上升，排除了大盘同步上行的解释。","B 延长窗口：三天差异可能是波动，四周稳定差异会显著提高归纳强度。","C 排除混淆因素：促销、节假日、渠道结构都可能同时改变点击人群构成。","D 减少而不是增加证据量，属于选择性报告；E 只改变措辞强度，不改变证据，两者都不影响结论的可靠性。"],"commonMistakes":[{"option":"D","errorType":"ignoring-counterexample","why":"隐藏其余天数等于回避可能推翻结论的观察。"},{"option":"E","errorType":"conclusion-overreach","why":"措辞变强并不会让证据变多，结论的风险反而更大。"}],"takeaway":"想让一个归纳更可信，就增加能区分不同解释的观察，而不是修饰结论的语气。"}'::jsonb, array['归纳强度', '对照实验', '工作协作']::text[], '原创题，场景取自互联网运营例会的效果讨论，用于训练加强或削弱归纳结论的具体做法。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ind-005', 1, 'inductive-reasoning', array['inductive-strength', 'base-rate', 'spurious-correlation']::text[], 4, 140, 'short-answer', null, '一则新闻写道：“本市去年查处网络诈骗案件 120 起，比前年的 80 起增加五成，可见治安正在急剧恶化。”请用两三句话说明：要让这个归纳结论站住，还需要哪些信息？', null, null, null, '{"checkpoints":[{"id":"c1","label":"指出统计口径可能变化","keywords":["口径","统计标准"],"weight":3,"required":true},{"id":"c2","label":"指出基数与总量的作用","keywords":["基数","总量"],"weight":2,"required":true},{"id":"c3","label":"给出另一种解释","keywords":["也可能是","另一种解释"],"weight":2,"required":true},{"id":"c4","label":"提出可核对的数据","keywords":["报案量","破案率"],"weight":1,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"先要确认统计口径有没有变：如果去年新增了线上报案通道或调整了诈骗的认定标准，查处数上升也可能只是记录更全。前年基数只有 80 起，增加 40 起看起来是五成，放在全市案件总量里未必算急剧恶化。也可能是破案率提高带来查处数上升，而实际发生的案件没有增加。要判断治安走势，应对照同期的报案量、立案数和受害人数。"}'::jsonb, '[]'::jsonb, '{"summary":"“查处数增加”到“治安恶化”之间隔着口径、基数和方向三层问题：查处数同时受案件数量与执法力度影响，不能直接当治安水位。","steps":["把论证拆开：前年 80 起、去年 120 起（前提）→ 案件实际增多（隐含前提）→ 治安恶化（结论）。","第一处需要补的信息是口径：报案通道、认定标准、统计范围任一项变化都会改变数字。","第二处是基数与占比：40 起的绝对增量在五成比例下显得很大，但相对案件总量可能微不足道。","第三处是解释方向：破案率上升会让查处数增加而案件数减少，这与“恶化”给出完全相反的图景。","因此需要同期的报案量、立案数、受害人数作为对照数据，才能把几种解释区分开。"],"commonMistakes":[{"errorType":"insufficient-evidence","why":"只用一个指标的变化就推出整体状况的趋势。"},{"errorType":"base-rate-neglect","why":"只看到百分比涨幅，忽略了两年基数都很小这一事实。"},{"errorType":"correlation-as-causation","why":"把查处数与治安状况之间的相关直接当成单向因果。"}],"takeaway":"读到“数字涨了所以变坏了”，先查口径、基数，再问有没有反向解释。"}'::jsonb, array['统计口径', '新闻阅读', '归纳评估']::text[], '原创题，场景取自本地新闻对社会治安数据的报道，用于训练对统计类归纳结论补充所需信息。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ind-006', 1, 'inductive-reasoning', array['inductive-strength', 'dependency-order', 'common-cause']::text[], 3, 100, 'ordering', null, '妈妈说：“小区里几位每天散步的老人都很硬朗，可见散步能让人长寿。”你想认真检验这个说法。按最合理的先后顺序排列下列步骤。', null, null, '[{"key":"s1","text":"写清“每天散步”和“硬朗、长寿”分别怎么测量，避免各说各话"},{"key":"s2","text":"把观察对象从这几位邻居扩展到不同年龄、职业和居住条件的人群"},{"key":"s3","text":"列出除散步外还可能同时影响寿命的因素，如饮食、慢性病、就医条件"},{"key":"s4","text":"在尽量对齐这些因素的条件下，比较散步组与不散步组的差别"},{"key":"s5","text":"专门寻找反例：长期散步但早逝、几乎不散步却高寿的人"},{"key":"s6","text":"给出带不确定性说明的结论，写清样本量和混杂因素还限制了什么"}]'::jsonb, '{"keys":["s1","s2","s3","s4","s5","s6"]}'::jsonb, '[{"keys":["s1","s3","s2","s4","s5","s6"],"note":"先列举混杂因素再扩大样本也说得通：知道要控制什么，扩展样本时就能顺带收集这些信息，只是可能多跑一趟。"}]'::jsonb, '{"summary":"检验一个生活经验式的归纳，顺序是：定义术语 → 扩大并多样化样本 → 枚举共同原因 → 控制后比较 → 主动找反例 → 带着不确定性下结论。","steps":["口径不固定，后面所有比较都没有共同标准，因此定义先行。","几位邻居的样本既不多样也不随机，扩展人群是提高归纳强度的第一步。","散步的人往往饮食规律、就医更方便，这些是典型的共同原因，必须先列出来。","列清楚之后才能在可比条件下分组，否则比较的是生活方式而不是散步。","反例检查放在结论之前，因为一个稳定的反例就能削弱“散步使人长寿”。","最后把结论写成有范围的判断，而不是把相关性说成确定的因果。"],"commonMistakes":[{"errorType":"ignoring-counterexample","why":"只收集支持说法的例子，不去找相反情形。"},{"errorType":"correlation-as-causation","why":"跳过共同原因清单，直接宣布散步导致长寿。"}],"takeaway":"检验生活经验式的结论，先定口径再扩样本，最后专门去找反例。"}'::jsonb, array['步骤顺序', '归纳检验', '家庭沟通']::text[], '原创题，场景取自家人之间关于锻炼与长寿的日常争论，用于训练设计可执行的检验顺序。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ind-007', 1, 'inductive-reasoning', array['survivorship-bias', 'inductive-strength', 'correlation-scenarios']::text[], 4, 110, 'single-choice', null, '一篇帖子写道：“我采访了 20 位创业成功的人，其中 15 位都辍过学，可见辍学是创业成功的重要原因。”下列哪项评价最准确？', null, '[{"key":"A","text":"20 位成功者的样本量已经足够大，结论可信","errorType":"insufficient-evidence","reason":"只谈样本数量，忽略样本是怎么被挑出来的"},{"key":"B","text":"采访对象全部从成功者里挑选，缺少同样辍学却没成功的人，样本存在系统性缺失"},{"key":"C","text":"辍学与成功在这些人身上同时出现，说明辍学带来了成功","errorType":"correlation-as-causation","reason":"由共现直接跳到因果方向"},{"key":"D","text":"只要再采访 20 位成功者核实一遍，就能确认这个结论","errorType":"ignoring-counterexample","reason":"重复同一种有偏抽样，仍然没有纳入失败者"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"要判断辍学是否有助于成功，需要比较“辍学的人里有多少成功”；只采访成功者，等于把失败的那一半样本整体丢掉了。","steps":["先看结论要比较什么：辍学者与不辍学者的成功比例，或成功者与失败者的辍学比例。","帖子的样本只覆盖“已成功”这一格，辍学后创业失败的人根本进不了采访名单。","缺失的正是能推翻结论的那一类反例，因此扩大成功者样本也不会改变偏差。","另外，辍学可能与年龄、家庭支持、行业相关，即使差异真实也不等于它造成了成功。","所以最准确的评价是 B；A、D 把偏差样本当作证据，C 把共现当因果。"],"commonMistakes":[{"option":"A","errorType":"insufficient-evidence","why":"数量再多也补不上抽样方向造成的缺口。"},{"option":"C","errorType":"correlation-as-causation","why":"共现至少还有四种解释，这里直接选定了一个方向。"},{"option":"D","errorType":"ignoring-counterexample","why":"重复同一种有偏抽样只会加深偏差，不能代替缺失的失败者样本。"},{"errorType":"appeal-to-majority","why":"拿“受访者里多数人都辍过学”当作辍学值得效仿的理由，人数多并不改变样本有偏。"}],"takeaway":"下归纳结论前，先问一句：看不见的那部分样本到哪里去了？"}'::jsonb, array['幸存者偏差', '样本缺失', '阅读新闻']::text[], '原创题，场景取自社交平台上的创业经验访谈帖，用于训练识别系统性样本缺失。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-ind-008', 1, 'inductive-reasoning', array['inductive-strength', 'conclusion-identification', 'falsification']::text[], 5, 175, 'open-response', null, '备考两周后你写下：“我做的 8 套历年真题里，错题几乎都集中在函数章节，所以这次考试我函数部分一定会失分。”请评价这段归纳：哪一部分站得住、哪一部分说过头了？你打算据此做什么、不做什么？', null, null, null, '{"scale":[{"score":0,"label":"全盘接受或全盘否定","criteria":"要么立刻认定函数必然失分，要么认为这种统计毫无意义，不做任何后续安排。"},{"score":1,"label":"只说样本太少","criteria":"指出 8 套题太少，但说不出这组数据究竟支持到什么程度。"},{"score":2,"label":"分清结论强弱","criteria":"能说明“错题集中在函数”是可核对的事实，而“一定失分”把或然说成了必然。"},{"score":3,"label":"补上遗漏的解释","criteria":"进一步提出别的可能：函数章节占比本身更高，或其他章节已经复习过、错不出更多。"},{"score":4,"label":"设计可区分做法","criteria":"还能说出怎样验证，比如按章节统计错题率与题目占比、再做一套未做过的题，并写下时间投入的安排。"}],"guidance":"先分开事实与推测，再补出至少一个同样能解释现状的原因，最后给出一个能区分不同解释的验证动作。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"这段归纳的前半部分是可核对的观察，后半部分把它推成必然预测；而错题分布同时受各章题目占比和复习进度影响，需要按占比重新比较。","steps":["分离事实与结论：8 套题的错题分布是可点数的观察，“一定会失分”是关于未来单次考试的必然判断。","评估强度：8 套题不算小，但都是同一人自选题目，题量分配并不随机。","补充解释：如果函数章节在每套卷子里占比最高，错题集中是正常结果；也可能其他章节刚复习过。","构造可区分的数据：按章节统计“错题数／该章题数”得到失分率，而不是只数错题条数。","据此安排行动：把时间投给失分率最高且分值占比高的章节，而不是笼统地认定函数会失分。"],"commonMistakes":[{"errorType":"conclusion-overreach","why":"从“历史上集中在函数”跳到“这次一定失分”，跨越了或然到必然。"},{"errorType":"base-rate-neglect","why":"只看错题条数，忽略了各章节在试卷中的题目占比。"},{"errorType":"hasty-generalization","why":"用有限的自选练习推断一次正式考试的结果。"}],"takeaway":"把自己的错题统计当证据前，先把它换算成“每章的失分率”，再决定复习投向哪里。"}'::jsonb, array['归纳评估', '学习备考', '开放题']::text[], '原创题，场景取自考生刷真题后的自我总结，量表按从接受说法到设计验证的常见回答层级设计。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-fal-001', 1, 'logical-fallacies', array['evidence-relevance', 'inductive-strength']::text[], 2, 50, 'single-choice', null, '一条热搜下的高赞评论写道：“两万多人都在说这家店不坑，这么多人试过了还能有这口碑？放心点就是了。”下列对这条评论逻辑问题的判断，哪项最准确？', null, '[{"key":"A","text":"它把“说好的人多”当成了“店确实好”的证据，而人数多少并不能代替对价格、食材、卫生的实际核对"},{"key":"B","text":"它属于稻草人，因为这条评论歪曲了反对者的说法"},{"key":"C","text":"它属于人身攻击，因为它针对的是那些去消费的人"},{"key":"D","text":"它没有逻辑问题，两万多人这个规模已经足以证明这家店不坑","errorType":"appeal-to-majority","reason":"把相信的人多当成结论为真的理由"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"评论给出的唯一依据是“评价它的人多”，这是诉诸多数：相信某个说法的人数，与这个说法是否为真并没有必然关系。","steps":["拆出结构：前提是“两万多条评论说它不坑”，结论是“这家店不坑，可以放心点”。","找出缺失的桥梁：评论默认“说它好的人多，它就真的好”，但评论数量同时受传播量、活动返现、从众心理影响。","换成相关的检验：要判断一家店，需要与结论同指向的证据，例如价格公示、食材来源、卫生检查记录、可复现的口味评价。","区分相似谬误：这段话没有改写任何对手的主张，所以不是稻草人；也没有攻击某个具体人的身份或品行，所以不是人身攻击。","看选项 D 自身：它给出的仍然是一条多数证据，等于用一个谬误去回答另一个谬误。"],"commonMistakes":[{"option":"D","errorType":"appeal-to-majority","why":"声量是关注度的指标，不是质量的指标，人数多不会自动提高结论为真的可能性。"},{"option":"B","errorType":"premise-misidentification","why":"稻草人要求先改写对方的主张再去反驳；这段评论里根本没有对手的主张，它只是把人数当成了前提。"}],"takeaway":"看到“多少人都说……”，先问一句：这些人给出的是人数证据，还是质量证据？"}'::jsonb, array['诉诸多数', '证据相关性', '谬误辨析']::text[], '原创题，场景取自社交平台热搜评论区，用于区分人数证据与质量证据。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-fal-002', 1, 'logical-fallacies', array['ad-hominem', 'straw-man']::text[], 3, 75, 'single-choice', null, '讨论是否取消加班餐补时，甲说：“可以取消餐补，但要把省下的钱换成等额调休。”乙回应：“你的意思就是员工不该拿任何补贴，公司想让大家白干。”丙回应：“你提这个建议是因为你家离公司近，反正你晚上不需要在外面吃饭。”关于乙和丙的回应，下列判断哪项正确？', null, '[{"key":"A","text":"乙用了稻草人：它把甲的主张改写成“员工不该拿任何补贴”再去反驳；丙用了人身攻击：它抛开主张本身，只谈甲的住址"},{"key":"B","text":"乙和丙都用了稻草人，因为两个人都没有拿出数据"},{"key":"C","text":"乙和丙都用了人身攻击，因为两个人都不满甲"},{"key":"D","text":"丙比乙更有说服力，因为丙说出了甲不便否认的私人情况","errorType":"ad-hominem","reason":"用与主张真假无关的私人情况来评价主张"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"区分两者的关键是落点：稻草人改变的是“对方说了什么”，人身攻击改变的是“由谁来说”。乙改写了甲的主张，丙则把话题从主张转移到甲这个人。","steps":["先固定甲的主张：取消餐补，同时把这笔钱换成等额调休，这是一个有补偿条件的替换方案。","看乙的反驳对象：“员工不该拿任何补贴”并不是甲说过的话，而是把它放大成对公司有利的极端版本，属于稻草人。","看丙的反驳对象：丙没有转述甲的任何主张，只说明甲家离公司近，因此评价落点在人而不是论点，属于人身攻击。","给出可迁移的判据：如果反驳的内容能在对方原话里找到对应，就不算稻草人；如果反驳里出现的是对方的身份、动机、处境而非对方的话，就要考虑人身攻击。","补一句：质疑利益冲突并非天然无效，但必须先说明这个处境如何影响论证内容本身，否则只是转向于人。"],"commonMistakes":[{"option":"D","errorType":"ad-hominem","why":"住址远近与“该不该用调休替换餐补”这件事的论证质量无关，把它当成说服力来源正是人身攻击的结构。"},{"option":"B","errorType":"premise-misidentification","why":"“没有数据”不等于稻草人。乙的问题在于制造了一个甲没有说过的主张，丙的问题在于根本没讨论主张。"},{"option":"C","errorType":"premise-misidentification","why":"乙攻击的是改写后的主张，不是甲这个人；把两者都归为人身攻击就抹掉了两种谬误的关键差别。"}],"takeaway":"先问“他反驳的是哪句话”：那句话是对方原话还是被改写过的版本，决定是稻草人还是别的毛病。"}'::jsonb, array['人身攻击', '稻草人', '相似谬误区分']::text[], '原创题，场景取自职场福利讨论，专为区分稻草人与人身攻击而写。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-fal-003', 1, 'logical-fallacies', array['slippery-slope', 'false-dilemma', 'appeal-to-authority']::text[], 4, 110, 'multi-choice', null, '家长会上，一位家长劝孩子：“你现在每天少玩一小时手机，将来才考得上好大学；考不上好大学就找不到好工作，找不到好工作这辈子就完了。你要么现在听我的，要么以后别后悔。我同事是大学老师，他说现在的孩子就是自制力太差，所以你必须听我的。”这段话中确实存在哪些论证问题？（选出所有符合的项）', null, '[{"key":"A","text":"从“少玩一小时手机”一路推到“这辈子就完了”，中间每一环都没有给出理由，属于滑坡式连锁推断"},{"key":"B","text":"把“现在听我的”和“以后别后悔”摆成仅有的两种结局，排除了其他组合，属于错误二分"},{"key":"C","text":"用“我同事是大学老师”来代替对这个孩子自制力的具体评估，属于不当的诉诸权威"},{"key":"D","text":"“考不上好大学”与“找不到好工作”之间的因果早有公开数据支持，这里只是复述，不算跳跃","errorType":"insufficient-evidence","reason":"把链条说得顺口当成了链条已被证明"},{"key":"E","text":"“所以你必须听我的”是在陈述一条事实证据，而不是在提出主张","errorType":"premise-misidentification","reason":"把整段话的结论误认成提供依据的前提"}]'::jsonb, null, '{"keys":["A","B","C"]}'::jsonb, '[]'::jsonb, '{"summary":"这段劝学话里叠了三种缺陷：没有中间论证的连锁推断（滑坡）、被压缩成两项的结局（错误二分）、头衔与话题不匹配的转述（不当诉诸权威）。","steps":["把整段话拆成三条独立推理：手机时间到学业、学业到职业到人生、以及“听我的”这一结论的依据。","第一处有四个节点（少玩手机、考上好大学、找到好工作、人生不废），节点之间没有给出机制或数据，只靠“就会”串起来，这是滑坡的典型结构。","第二处“要么……要么……”漏掉了“不完全照办但事后并不后悔”等情形；判断错误二分的操作方法是主动构造第三种可能，若能构造则两项并不穷尽。","第三处“大学老师”的头衔与“这个孩子的自制力”这一具体判断并不对应，而且内容是二手转述、无法核对；即便承认教师对教育问题有一般发言权，用它来代替对孩子的评估仍属于不当诉诸权威。","对照 D 与 E：D 把连锁的流畅度误当成已证明的因果；E 把论证的结论（必须听我的）当成了提供证据的前提，两者都属于前提与结论的角色错认。"],"commonMistakes":[{"option":"D","errorType":"insufficient-evidence","why":"题目里没有出现任何数据或机制说明，仅仅“大家都这么说”不足以填补链条上的跳跃。"},{"option":"E","errorType":"premise-misidentification","why":"“必须听我的”是这段话最终要人接受的主张，它由前面的句子支持，本身不是支持别的前提。"}],"takeaway":"一段话里可能同时有几种毛病。逐句问“这句话靠什么支持”，能一次拆出多个谬误。"}'::jsonb, array['滑坡', '错误二分', '诉诸权威', '多谬误识别']::text[], '原创题，场景取自家庭劝学对话，用于在一句话里同时识别三种谬误。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-fal-004', 1, 'logical-fallacies', array['false-dilemma', 'conclusion-identification']::text[], 3, 45, 'true-false', null, '健身房广告写着：“要么现在开始锻炼，要么就这样一天天老下去。”有同学据此认为，只要一句话只给出两个选项，它就必然犯了错误二分的谬误。这个“给出两个选项就等于谬误”的判断是否正确？', null, null, null, '{"value":false}'::jsonb, '[]'::jsonb, '{"summary":"两个选项本身并不违规。只有当列出的选项既不穷尽、又被当作穷尽时，才构成错误二分；由这一则广告推出“凡是二分都是谬误”走得太远。","steps":["写出判定标准：错误二分要求选项互斥、选项穷尽、且说话人否认存在其他可能。","构造一个合法二分：“明天要么下雨，要么不下雨。”它穷尽了所有情形，却没有传递任何信息，因此不是谬误。","回到广告：它的问题不在“给了两项”，而在把“锻炼”与“变老”硬绑成仅有的两条路，忽略了调整饮食、循序渐进、改变作息等其他可能。","检查那位同学的推理：他从一个可疑例子跳到“任何二分表述都是谬误”，这是把结论推广到全称，超出了例子能支持的范围。"],"commonMistakes":[{"errorType":"false-dilemma","why":"把“看到两个选项”直接等同于“犯了谬误”，跳过了是否穷尽这一步检验。"},{"errorType":"conclusion-overreach","why":"由一则广告的可疑表述，推出关于所有二分表述的全称判断，结论明显比证据更远。"}],"takeaway":"遇到二选一，先自己数一遍可能：能不能构造出让两项同时不成立的情形。"}'::jsonb, array['错误二分', '判定标准', '全称结论']::text[], '原创题，针对“凡是二分即谬误”这一常见过度概括而写。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-fal-005', 1, 'logical-fallacies', array['appeal-to-authority', 'evidence-relevance', 'sample-size']::text[], 4, 130, 'short-answer', null, '一位有百万粉丝的短视频博主在镜头里说：“这款稳健型基金我自己买了两年，收益很稳，你们跟着我买就行。”请用三到四句话回答：作为投资建议，这段话的主要逻辑问题在哪里；并且在什么条件下，引用别人的经验确实可以算作证据。', null, null, null, '{"checkpoints":[{"id":"c1","label":"指出以身份和人数代替依据","keywords":["粉丝","博主","身份"],"weight":3,"required":true},{"id":"c2","label":"说明个人经历只是个别样本","keywords":["两年","个人","样本"],"weight":2,"required":true},{"id":"c3","label":"列出可核对的证据类型","keywords":["历史净值","持仓","费率","招募说明书"],"weight":2,"required":false},{"id":"c4","label":"给出引用经验可用的条件","keywords":["专业范围","可核对","利益"],"weight":3,"required":true}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"主要问题在于用博主的身份和粉丝量代替了投资依据：他自己买了两年只是一段个人经历，样本量只有一人，还可能恰好赶上这段时间的行情。要判断它是否真的稳健，可核对的证据应包括招募说明书与基金合同里的投资范围、持仓和费率，以及公开的历史净值与最大回撤。引用别人的经验在同时满足三个条件时才算证据：对方处在该问题的专业范围内、说法本身可核对、并且他与结论没有直接利益关系。"}'::jsonb, '[]'::jsonb, '{"summary":"问题不在于“引用了他人的经验”，而在于把一人两年的持有体验、加上粉丝数量，当成了适合所有投资者的结论的充分依据。","steps":["拆出结构：前提是“博主自己买了两年、收益稳”，结论是“你们跟着买就行”。","指出缺口：从“对我这两年被合适”到“对你们都合适”之间，缺少关于风险承受能力、投资期限和费率的说明。","补充相关证据：招募说明书与投资范围、费率结构、历史净值与最大回撤、博主是否收取带货分成。","给出界线：当引用对象处于该问题的专业范围内、说法可独立核对、且与结论无利益关联时，引用专家意见是合理的间接证据，否则只是借身份压过论证。","顺带注意：粉丝数量衡量的是传播力，与投资建议的可靠性不构成同指向的证据。"],"commonMistakes":[{"errorType":"insufficient-evidence","why":"一人两年的体验既没有排除时段行情因素，也没有覆盖不同风险偏好的投资者。"},{"errorType":"conclusion-overreach","why":"前提只支持“对他本人这段时间可能合适”，结论却推到“你们跟着买就行”，范围明显被放大。"},{"errorType":"hasty-generalization","why":"把单个样本的表现直接当作适用于所有人的稳定规律，是典型的以偏概全。"}],"takeaway":"听到“我自己也在用”，先问三件事：他是不是这个领域的可靠来源、说法能不能独立核对、他有没有从中得利。"}'::jsonb, array['诉诸权威', '投资建议', '样本量']::text[], '原创题，场景取自短视频带货式投资分享，不指向任何真实平台或产品。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-fal-006', 1, 'logical-fallacies', array['slippery-slope', 'falsification']::text[], 3, 90, 'ordering', null, '班会上有同学主张：“一旦允许课间把手机带进教室，就会有人课堂偷玩；偷玩一多，成绩就会下滑；成绩下滑，班级评优就没了；评优没了，这个班就完了。”要检验这个滑坡式说法，请按最合理的先后顺序排列下列步骤。', null, null, '[{"key":"s1","text":"把这条连锁的每一环单独写出来，明确每一步的因果断言"},{"key":"s2","text":"找出其中证据最薄弱的一环，把讨论集中到这一环上"},{"key":"s3","text":"针对这一环追问实际数据或已有案例，而不是想象中的场景"},{"key":"s4","text":"检查是否存在能中断链条的补救措施，例如限时收纳、分区域使用"},{"key":"s5","text":"综合以上判断整条链条该被接受、被削弱还是保持开放"}]'::jsonb, '{"keys":["s1","s2","s3","s4","s5"]}'::jsonb, '[{"keys":["s1","s3","s2","s4","s5"],"note":"若认为“哪一环最薄弱”本身要靠数据才能判断，那么先逐环索要记录、再回头锁定最弱的一环同样说得通；两种顺序都保留了拆链、取证、找中断措施、最后总判的依赖关系。"}]'::jsonb, '{"summary":"对付滑坡式主张的正确顺序是：拆链、定位最弱环节、用可核对的证据检验该环节、寻找中断链条的措施、最后才对整条链做判定。","steps":["连锁推断由多个条件句串成，任何一环都可能断裂，所以第一步必须把每一环写成可单独检验的断言。","逐环争论代价太高，第二步要挑出证据最少、跳跃最大的那一环，把有限讨论集中在它上面；如果一时看不出哪一环最弱，可以先统一索要数据再据此锁定，这种顺序同样讲得通。","第三步问的是“有什么记录支持这一环”，例如其他班级实行类似安排后的实际数据，而不是最坏情景的想象。","第四步考虑中间措施能否阻断传递：如果有可行措施能防住课堂偷玩，那么后续各环就不必然发生。","最后一步才给整体判定，并同时说明还有哪些环节仍未被检验，避免从“一环不成立”跳到“全部不成立”。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过逐环拆分、直接争最后一环的结局吓不吓人，讨论就会停在情绪而不是证据上。"},{"errorType":"ignoring-counterexample","why":"只推演想象中的最坏场景，不看已经实行的班级里是否真出现了成绩下滑。"},{"errorType":"false-dilemma","why":"把结论压成“要么完全禁止、要么班级完蛋”，漏掉了中间措施这一类选项。"}],"takeaway":"检验滑坡的诀窍是把链条拆成环，然后逐环问：这一环的证据在哪里，有没有办法让它传不下去。"}'::jsonb, array['滑坡', '可检验性', '步骤顺序']::text[], '原创题，场景取自班级事务讨论，用于训练把滑坡主张转为可检验步骤。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-fal-007', 1, 'logical-fallacies', array['straw-man', 'conclusion-identification', 'implicit-premise']::text[], 5, 180, 'open-response', null, '父亲说：“有知识才能改变命运。”孩子回答：“隔壁修车的张师傅没什么学历，挣得比很多大学生还多，可见‘有知识才能改变命运’是假话。”请写一段评价：孩子的反驳有没有击中父亲的说法？如果没有，问题出在哪个词上？你会怎么把它改成一个更稳妥的表述？', null, null, null, '{"scale":[{"score":0,"label":"接受反驳","criteria":"认为张师傅的例子已经推翻了父亲的说法，不需要再讨论用词问题。"},{"score":1,"label":"只觉别扭","criteria":"感到孩子的说法有些不对，但说不清问题出在哪一句、哪一个词上。"},{"score":2,"label":"指出词义被替换","criteria":"能说明孩子把父亲说的“知识”换成了“学历”，同时把“改变命运”换成了“收入更高”。"},{"score":3,"label":"区分两种缺陷","criteria":"进一步说明这既涉及偷换概念，也带有稻草人式改写，并给出两者的区分标准。"},{"score":4,"label":"改写并给出反例条件","criteria":"还能改写原句、标明范围与条件，并说明什么样的例子才真正构成对该命题的反驳。"}],"guidance":"先分别写出两人各在用什么词、指向什么；再判断反驳针对的是否还是原来那个主张；最后改写原句，把适用范围和条件写清楚。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"孩子的举证同时换掉了两个词：把“知识”换成“学历”，把“改变命运”换成“挣得多”。替换之后被判为假的主张，已经不是父亲原先那句。","steps":["锁定父亲命题中的关键词“知识”，在他的用法里接近“系统的学识与能力积累”，而“改变命运”指的是处境的整体改善。","看孩子的证据：他说的是“没什么学历”和“挣得多”，这是把两个较宽的说法换成两个较窄、可观察的说法。","注意维修手艺本身也是专业知识：张师傅的例子既可能支持原命题（他有另一种知识），也不构成稳定反例，因为样本只有一人、衡量只看收入。","给出区分标准：偷换概念发生在同一个论证内部某个词的含义悄悄改变；稻草人发生在把对方说过的主张改写成更容易攻击的版本。这里两者都有，落点是“换完词义再宣布对方为假”。","一个更稳妥的改写示例：在多数情况下，持续积累学识会提高一个人改善处境的可能性，但它是条件之一，不保证收入高低；要反驳它，需要给出“有学识却处境长期不变”或“毫无学识而处境长期改善”的可核对对照。"],"commonMistakes":[{"errorType":"equivocation","why":"在同一段讨论里把“知识”悄悄换成“学历”，再用换后的说法判定原命题为假。"},{"errorType":"ignoring-counterexample","why":"把一个可能反而支持原命题的手艺例子，当成已经确证的反例来使用。"},{"errorType":"hasty-generalization","why":"由一个人的收入状况，推广到对一条普遍说法的真假判定，样本明显不足。"}],"takeaway":"反驳之前先对齐词义：两个人说的到底是不是同一个词、同一件事、同一个衡量标准。"}'::jsonb, array['偷换概念', '稻草人', '开放题', '词义对齐']::text[], '原创题，量表按常见回答层级由弱到强设计，供自评与可选的模型反馈使用。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-fal-008', 1, 'logical-fallacies', array['implicit-premise', 'validity-vs-truth']::text[], 3, 60, 'single-choice', null, '一家餐馆墙上写着：“本店招牌菜，顾客最爱。”有人问凭什么说它是招牌菜，服务员答：“因为这道菜顾客最爱。”再问怎么知道顾客最爱它，服务员答：“因为墙上写着它是顾客最爱的招牌菜。”下列对这段对话的评价哪项最准确？', null, '[{"key":"A","text":"服务员的两条理由互相依赖：用“招牌”证明“顾客最爱”，又用“顾客最爱”证明“招牌”，要证的结论被放进了前提里"},{"key":"B","text":"服务员是在诉诸权威，因为他引用了墙上写着的文字"},{"key":"C","text":"“招牌菜”和“顾客最爱”在对话中含义发生了变化，这是偷换概念"},{"key":"D","text":"只要顾客确实最爱这道菜，这段回答就没有任何问题","errorType":"insufficient-evidence","reason":"该说法本身从未被独立核对，只是被重复了一遍"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"这是一个循环论证：待证的两条主张互为唯一理由，绕了一圈没有引入任何独立于结论的证据，与“是否恰好为真”是两回事。","steps":["把对话写成两个命题：P＝这是招牌菜，Q＝顾客最爱它；服务员给出的理由是 Q 因为 P，而 P 因为 Q。","检查循环特征：把待证结论放进前提里，推理形式上有效但内容上什么也没新提供，因为两条前提的成立都依赖结论本身。","对照选项 B：诉诸权威需要引用某个该领域的可靠来源，而墙上的标语正是被追问的对象，不能给自己的真实性作证。","对照选项 C：偷换概念要求同一词在论证前后取两个不同含义；这里两个词的含义前后一致，问题出在互为理由而不是换词。","要打破循环，需要一条独立证据：点单记录、翻台数据或第三方平台的复购统计，任一条都能让 Q 与 P 脱开互证。"],"commonMistakes":[{"option":"D","errorType":"insufficient-evidence","why":"“顾客确实最爱”正是需要被证明的东西，把它假设为真就取消了整个问题。"},{"option":"C","errorType":"premise-misidentification","why":"判断偷换概念要指出同一个词的两个不同含义；这里找不到含义漂移，只找到了互相依赖的前提。"},{"errorType":"circular-reasoning","why":"容易被忽略的一点：前提重复结论的措辞，看起来像给了理由，实际没有引入独立证据。"}],"takeaway":"追问一句“这个理由的依据是什么”：如果答案绕回原结论，就等于没给理由。"}'::jsonb, array['循环论证', '独立证据', '餐饮文案']::text[], '原创题，场景取自餐馆宣传语问答，用于训练识别结论被藏进前提的结构。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-nsc-001', 1, 'necessary-sufficient-conditions', array['necessary-condition', 'sufficient-condition', 'only-if']::text[], 2, 50, 'single-choice', '产品需求评审会，讨论版本发布卡点。', '评审会上负责人说：“只有把支付模块的漏洞全部修完，这个版本才允许发布。”已知这个版本已经发布了。以下哪项一定正确？', null, '[{"key":"A","text":"支付模块的漏洞已经全部修完"},{"key":"B","text":"只要支付模块的漏洞全部修完，这个版本就一定可以发布","errorType":"premise-misidentification","reason":"把“只有”引导的必要条件当成充分条件"},{"key":"C","text":"如果这个版本没有发布，说明漏洞一定没修完","errorType":"denying-antecedent","reason":"否定前件就推出否定后件"},{"key":"D","text":"仅凭这两句话无法判断漏洞是否修完"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[{"keys":["D"],"note":"如果允许怀疑这条规则本身可能被违反（例如带病强发），那么严格说只能得到“按规定应当已全部修完”，此时保留无法判断同样讲得通。"}]'::jsonb, '{"summary":"“只有 P 才 Q”把 P 说成 Q 的必要条件，等价于“若 Q 则 P”。已知版本已发布，即肯定后件，可推出漏洞已全部修完。","steps":["识别句式：“只有……才……”中，“只有”后面的内容是必要条件。","符号化：P＝漏洞全部修完，Q＝版本允许发布，规则译为 若 Q 则 P。","已知事实是 Q（版本已经发布），用肯定前件式对“若 Q 则 P”作推理，得到 P。","检查方向：B 把 P 当成足以发布的条件，C 对“若 Q 则 P”作了否定前件的推理，两者都不在规则承诺范围内。"],"commonMistakes":[{"option":"B","errorType":"premise-misidentification","why":"规则只说没修完就不能发布，没说修完就必须发布，还可能卡在别的条件上。"},{"option":"C","errorType":"denying-antecedent","why":"由“没发布”推“没修完”不成立，版本可能因其他原因推迟发布。"}],"takeaway":"读到“只有……才……”，先写成“若结果则条件”，再决定能推出什么。"}'::jsonb, array['必要条件', '句式翻译', '合规卡点']::text[], '原创题，场景取自互联网产品版本发布评审，用于训练“只有……才……”的翻译。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-nsc-002', 1, 'necessary-sufficient-conditions', array['sufficient-condition', 'necessary-condition']::text[], 3, 65, 'single-choice', '招聘流程条件辨析。', '招聘启事写：“只要通过两轮技术面试，就会收到录用意向书。”已知小王没有收到录用意向书。以下哪项结论可靠？', null, '[{"key":"A","text":"小王至少有一轮技术面试没有通过"},{"key":"B","text":"小王两轮技术面试都没有通过","errorType":"conclusion-overreach","reason":"把“并非两轮都通过”加强成“两轮都没通过”"},{"key":"C","text":"如果一个人没通过两轮面试，他就不会收到意向书","errorType":"denying-antecedent","reason":"否定前件推出否定后件"},{"key":"D","text":"凡是收到意向书的人都通过了两轮面试","errorType":"affirming-consequent","reason":"由结果反推唯一途径"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"“只要 P 就 Q”给出充分条件。已知没有 Q，用逆否可得不 P，即“并非两轮都通过”，等价于至少一轮没过，但不能细化到具体哪一轮。","steps":["符号化：P＝两轮技术面试都通过，Q＝收到录用意向书，规则为 若 P 则 Q。","已知 非 Q，套用否定后件式（等价于逆否命题）得到 非 P。","把 非 P 译回自然语言：“并非两轮都通过”＝至少有一轮没通过，这是 A。","B 把“至少一轮”加强为“两轮都”，D 从 Q 反推 P，C 从 非P 推 非Q，三者都超出了规则给出的信息。"],"commonMistakes":[{"option":"B","errorType":"conclusion-overreach","why":"否定合取只需要其中一项不成立，不需要两项都不成立。"},{"option":"C","errorType":"denying-antecedent","why":"启事没有说意向书只能靠两轮面试获得，可能存在别的通道。"},{"option":"D","errorType":"affirming-consequent","why":"把充分条件当成必要条件，认为收到就一定走过这条通道。"}],"takeaway":"“只要”给的是够用条件，否定它只能否定到“至少一处不满足”。"}'::jsonb, array['充分条件', '逆否', '招聘条件']::text[], '原创题，场景为招聘启事条件句，用于区分充分条件与必要条件。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-nsc-003', 1, 'necessary-sufficient-conditions', array['necessary-condition', 'only-if', 'sufficient-condition']::text[], 4, 90, 'single-choice', '个人信息合规条款理解。', '合规条款写：“除非取得用户单独同意，否则平台不得向第三方提供该用户的个人信息。”据此，下列哪一项是该条款允许的？', null, '[{"key":"A","text":"取得某用户单独同意后，把该用户的收货地址提供给合作快递"},{"key":"B","text":"用户在注册页勾选了打包在服务协议里的共享条款，平台据此提供其行踪轨迹","errorType":"equivocation","reason":"把“勾选打包协议”与条款要求的“单独同意”混为一谈"},{"key":"C","text":"这条意味着：只要取得单独同意，平台就必须向第三方提供个人信息","errorType":"affirming-consequent","reason":"把必要条件反读成充分条件"},{"key":"D","text":"用户没有明确反对，就等于取得了单独同意，可以提供","errorType":"premise-misidentification","reason":"用“未反对”替换条款规定的前提"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"“除非 P 否则不 Q”等于“若 Q 则 P”，P（单独同意）是 Q（对外提供）的必要条件。条件满足后禁止令解除，因此 A 合规。","steps":["句式转换：“除非 P 否则不 Q”＝“如果不 P 那么不 Q”＝逆否后“若 Q 则 P”。","代入：P＝取得单独同意，Q＝向第三方提供个人信息。","A 中 P 已成立且提供了信息，条款设定的禁止条件不再适用，属于允许范围。","B 偷换了“单独同意”的含义；C 把必要条件当成充分条件；D 用沉默替换同意，都改变了条款真正要求的前提。"],"commonMistakes":[{"option":"B","errorType":"equivocation","why":"条款写的是单独同意，打包勾选不满足这一特定含义，前后用词不同一。"},{"option":"C","errorType":"affirming-consequent","why":"条款只禁止“未经同意就提供”，没有规定“同意后就必须提供”。"},{"option":"D","errorType":"premise-misidentification","why":"把“没有反对”误认成条款要求的那个前提条件。"}],"takeaway":"看到“除非……否则不……”，先改写为“若要做成这件事，必须先满足什么”。"}'::jsonb, array['除非否则', '必要条件', '合规条款']::text[], '原创题，场景取自个人信息保护条款，针对“除非……否则不……”的翻译易错点。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-nsc-004', 1, 'necessary-sufficient-conditions', array['necessary-condition', 'only-if', 'contrapositive']::text[], 3, 95, 'multi-choice', '员工合规制度与签署权限。', '制度规定：“只有完成年度合规培训，员工才能签署客户合同。”设 P＝完成培训，Q＝能签署合同。下列哪些判断与这条制度一致？（选出所有一致的判断）', null, '[{"key":"A","text":"如果某员工签署了客户合同，那么他完成了年度合规培训"},{"key":"B","text":"如果某员工没有完成年度合规培训，那么他不能签署客户合同"},{"key":"C","text":"如果某员工完成了年度合规培训，那么他能签署客户合同","errorType":"affirming-consequent","reason":"把必要条件当成充分条件，由条件成立反推可以签署"},{"key":"D","text":"如果某员工不能签署客户合同，那么他没有完成培训","errorType":"denying-antecedent","reason":"否定前件推出否定后件"},{"key":"E","text":"完成年度合规培训是签署客户合同不可缺少的条件"}]'::jsonb, null, '{"keys":["A","B","E"]}'::jsonb, '[]'::jsonb, '{"summary":"“只有 P 才 Q”译为 若 Q 则 P。它同时等价于 若非 P 则非 Q，也等价于把 P 称作 Q 的必要条件；反过来从 P 推 Q 或从非 Q 推非 P 都不成立。","steps":["把制度写成标准形式：若 Q（能签署合同）则 P（完成培训）。","A 就是这条原命题本身，直接一致。","B 是它的逆否命题：若非 P 则非 Q，与原命题逻辑等价，因此一致。","E 是“P 是 Q 的必要条件”的自然语言复述，与制度同一含义。","C 从 P 推 Q，相当于在“若 Q 则 P”上肯定后件；D 从非 Q 推非 P，相当于否定前件。合同签署还可能受授权、职级等其他条件影响，两者都不被制度保证。"],"commonMistakes":[{"option":"C","errorType":"affirming-consequent","why":"完成培训只是不可缺少的条件之一，不是签好合同的全部条件。"},{"option":"D","errorType":"denying-antecedent","why":"不能签署合同的原因很多，未必是没完成培训。"}],"takeaway":"判断条件方向时，用“没它行不行”测必要，用“有它够不够”测充分。"}'::jsonb, array['必要条件', '逆否等价', '多选']::text[], '原创题，场景为企业合规培训签署权限，训练同一条件关系的多种自然语言表达。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-nsc-005', 1, 'necessary-sufficient-conditions', array['necessary-condition', 'sufficient-condition', 'only-if']::text[], 3, 50, 'true-false', '研发排期会议上的口头约定。', '“必须先把需求文档评审通过，开发才可以排期。”这句话与“只要需求文档评审通过，开发就可以排期”表达的是同一个条件关系。', null, null, null, '{"value":false}'::jsonb, '[]'::jsonb, '{"summary":"前一句把“评审通过”说成“可以排期”的必要条件，后一句把它说成充分条件，两者方向相反，不是同一条件关系。","steps":["第一句改写：若可以排期，则需求文档已评审通过（P 是 Q 的必要条件）。","第二句改写：若需求文档已评审通过，则可以排期（P 是 Q 的充分条件）。","构造情形：文档评审通过但资源不足无法排期。这与第一句相容，却与第二句冲突。","存在这样的分歧情形，说明两句不等价，故判断为错。"],"commonMistakes":[{"errorType":"premise-misidentification","why":"把“必须”引导的必要条件读成充分条件，推理方向整个反了。"},{"errorType":"affirming-consequent","why":"把“若可排期则已评审”与“若已评审则可排期”这对互逆命题视为等价。"}],"takeaway":"“必须”“只有”指没它不行；“只要”指有它足够，两者不可互换。"}'::jsonb, array['必要条件', '充分条件', '句式辨析']::text[], '原创题，针对研发排期口头约定中的条件方向混淆。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-nsc-006', 1, 'necessary-sufficient-conditions', array['necessary-condition', 'rebuttal-target', 'implicit-premise']::text[], 4, 120, 'short-answer', '上线流程争议。', '法务说：“只有通过安全测评，产品才能上线。”产品经理回应：“竞品从来没做过测评也照样上线，所以这条要求没必要。”请用两三句话说明：这条规则里“通过安全测评”是什么条件，产品经理的举例是否构成对这条规则的有效反驳。', null, null, null, '{"checkpoints":[{"id":"c1","label":"判定条件类型","keywords":["必要条件"],"weight":3,"required":true},{"id":"c2","label":"指出反驳落点错位","keywords":["反驳落点","本公司"],"weight":2,"required":true},{"id":"c3","label":"说明什么才算真正推翻","keywords":["反例","并非必要"],"weight":2,"required":false}],"correctRatio":0.7,"partialRatio":0.45,"modelAnswer":"在这条规则里，通过安全测评是产品上线的必要条件，也就是没通过就不能上线，而不是通过了就一定该上线。产品经理举的竞品例子说的是其他公司的做法，它既没有否定本公司的这条规定，也没有论证这个条件本身并非必要，属于反驳落点错位。要真正推翻这条规定，需要构造反例，例如公司严格执行了测评却仍频繁发生上线事故，或者拿出测评与上线质量无关的证据。"}'::jsonb, '[]'::jsonb, '{"summary":"回答要分两步：先把“只有……才……”译成必要条件，再检查对方的例子打在原主张的哪一处——别家公司的做法不能否定本公司规定。","steps":["符号化：P＝通过安全测评，Q＝产品上线，规则为 若 Q 则 P，即 P 是 Q 的必要条件。","明确必要条件被推翻的方式：出现“Q 成立但 P 不成立”的情形，即本公司未测评却合规上线。","分析对方的证据对象：竞品属于其他公司，落在本公司这条规定的适用范围之外。","补充评价：即便承认竞品做法有效，也只涉及“这条要求是否值得”，而不涉及“这条规定是否被违反”。"],"commonMistakes":[{"errorType":"premise-misidentification","why":"把必要条件当成充分条件，就会误以为测评完就该无条件上线。"},{"errorType":"ignoring-counterexample","why":"用别家公司的事例替换本公司范围内的反例，等于回避了真正需要检验的情形。"}],"takeaway":"反驳一条规定前，先确认你的例子是否落在这条规定所管辖的范围之内。"}'::jsonb, array['必要条件', '反驳落点', '简答题']::text[], '原创题，场景来自上线流程争论，训练条件类型判定与反驳对象核对。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-nsc-007', 1, 'necessary-sufficient-conditions', array['necessary-condition', 'sufficient-condition', 'falsification']::text[], 3, 85, 'ordering', '验收一条需求表述。', '需求文档写：“必须支持离线模式，才能进入商用版本。”你要判断这句话提出的是必要条件还是充分条件，并检查候选版本是否满足。请按最合理的先后顺序排列以下步骤。', null, null, '[{"key":"s1","text":"把句子改写为“若进入商用版本，则支持离线模式”，标出前件与后件"},{"key":"s2","text":"用“没它行不行”和“有它够不够”两个测试判定它属于哪类条件"},{"key":"s3","text":"列出候选版本清单，确认哪些版本已经或计划进入商用"},{"key":"s4","text":"在已商用版本中查找“不支持离线模式”的情形，作为检验结果"}]'::jsonb, '{"keys":["s1","s2","s3","s4"]}'::jsonb, '[]'::jsonb, '{"summary":"合理顺序是：先把自然语言译成标准条件式，再判定条件类型，然后确定要核查的样本范围，最后在该范围内找违反结论的情形。","steps":["不先改写就判定条件类型，容易把“必须”前后的内容位置弄错，所以 s1 必须在最前。","条件类型决定检验方向：必要条件的违反形式是“结论成立但条件不成立”，即已商用却不支持离线。","没有版本清单就无从核查，因此 s3 必须在具体检查之前完成。","s4 之所以只查已商用版本，是因为“支持离线但未商用”这类情形并不违反原要求，查了也不构成证据。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过改写直接查清单，判定标准不稳定，结果无法复核。"},{"errorType":"denying-antecedent","why":"去检查“没商用的版本是否支持离线”，检验方向与原命题无关。"}],"takeaway":"先定形式，再定检验方向，最后才找样本。"}'::jsonb, array['必要条件', '检验步骤', '排序']::text[], '原创题，场景为产品需求验收，训练把“必须”句式转成可检验步骤。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-nsc-008', 1, 'necessary-sufficient-conditions', array['sufficient-condition', 'necessary-condition', 'conclusion-identification']::text[], 5, 150, 'open-response', '日常争论中的条件混用。', '同事在群里说：“考试及格的同学都复习了。小明复习了，所以他一定及格。”请评价这个论证：原句把什么说成了什么条件？要使小明的结论站得住，需要把原句改成哪个条件关系？', null, null, null, '{"scale":[{"score":0,"label":"直接接受","criteria":"认为复习过就应当能及格，论证没有明显问题。"},{"score":1,"label":"仅表怀疑","criteria":"觉得推理有点别扭，但说不出哪一步不成立。"},{"score":2,"label":"识别条件类型","criteria":"能指出原句是“若及格则复习过”，复习只是及格的必要条件。"},{"score":3,"label":"说明推理失效原因","criteria":"能说明由“复习了”推不出“及格”，属于肯定后件式的无效逆推。"},{"score":4,"label":"给出可成立的改写与检验","criteria":"能把原句改写为“只要复习就及格”并指出该改写如何被反例检验，同时补充需要的事实依据。"}],"guidance":"先把“都”字句翻译成条件式，判定复习是哪种条件；再检查从小明的事实能推出什么；最后说明要怎样改写原句才让结论有效，以及改写后需要什么样的证据支持。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"“及格的同学都复习了”等于“若及格则复习过”，复习是必要条件；由复习反推及格是无效逆推。要结论成立，必须把复习升级为充分条件，而那是更强的主张。","steps":["翻译原句：P＝及格，Q＝复习过，句子为 若 P 则 Q。","已知小明 Q 成立，由 若 P 则 Q 与 Q 推不出 P，这是肯定后件。","说明改写代价：把原句改成“只要复习就及格”（若 Q 则 P）后推理才有效，但这一改写需要一个及格且未复习的反例就能推翻，证据要求更高。","补充可检验做法：查看复习与及格的实际分布，或直接向同学询问复习但没及格的人是否存在。"],"commonMistakes":[{"errorType":"affirming-consequent","why":"看到结果出现就断定条件出现，忽略了复习也可能与及格无关的其他情形。"},{"errorType":"conclusion-overreach","why":"在只有一句话作证据时，就给出“一定及格”这种确定性结论。"}],"takeaway":"遇到“……的都……”先翻译成“若属于前者则具有后者”，再决定能不能反着推。"}'::jsonb, array['充分条件', '必要条件', '开放题', '论证改写']::text[], '原创题，量表按回答深度分层，用于自评与可选的模型反馈。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dec-001', 1, 'problem-decomposition', array['subgoal-split', 'dependency-order']::text[], 2, 90, 'single-choice', null, '运营群里说：移动端注册转化率这周突然掉得很厉害，得赶紧查。面对这个还没查过的问题，下面哪一项最适合作为第一个动作？', null, '[{"key":"A","text":"先确认“注册转化率”的统计口径和取数管道有没有变化，也就是分子、分母、时间窗和数据是否完整"},{"key":"B","text":"立刻回滚本周上线的注册页改版，先把数字拉回来再说","errorType":"insufficient-evidence","reason":"在没有任何定位证据时就选择代价较高的动作"},{"key":"C","text":"在群里发起投票，让每个人写下自己觉得最可能的原因，按票数处理","errorType":"appeal-to-majority","reason":"用多少人相信代替了证据是否支持"},{"key":"D","text":"默认是注册表单太长把人吓退了，先精简字段再观察两天","errorType":"premise-misidentification","reason":"把尚未验证的猜测当成问题真正的前提"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"拆解“指标突然下降”这类问题，第一个子目标必须是确认这个数字本身可信，因为后面所有分支都建立在它之上。","steps":["先把模糊的抱怨改写成可回答的问题：哪一个环节、哪一段用户、从什么时候开始下降。","回答它的最早前提是数据可信：埋点未改动、分母定义未改动、日志没有缺天，否则“下降”可能只是口径变了。","口径确认后才有意义做拆分：按设备、渠道、新老用户、页面步骤分别看下降集中在哪一片。","回滚、加字段、发优惠券都是干预动作，属于最后一步，跳过前面步骤会让动作没有指向。","群投票收集的是猜测而不是证据，票数不能替代任何一个子目标的验证结果。"],"commonMistakes":[{"option":"B","errorType":"insufficient-evidence","why":"还没有把下降定位到某个环节，就用不可逆的发布动作去赌一个未验证的原因。"},{"option":"C","errorType":"appeal-to-majority","why":"把多人共同的直觉当作判断依据，绕过了每个子目标各自需要的证据。"},{"option":"D","errorType":"premise-misidentification","why":"把“表单太长”这个假设当成问题前提，后续观察会被这个预设带偏。"}],"takeaway":"拆问题的第一步是确认“这个问题是不是真的存在”，其次才是“它由什么造成”。"}'::jsonb, array['问题拆解', '步骤依赖顺序', '指标排查']::text[], '原创题，场景取自互联网运营排查指标的常见流程，用于训练先核对口径再拆分支。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dec-002', 1, 'problem-decomposition', array['dependency-order', 'subgoal-split']::text[], 3, 130, 'ordering', null, '某电商站点移动端下单转化率连续三天从 4.1% 降到 2.6%。团队要把“查清原因”拆成可以依次执行的五个子目标。请按步骤之间的依赖先后排序。', null, null, '[{"key":"s1","text":"核对指标口径与取数链路：埋点、分母定义、统计时间窗、日志完整性是否在这一周被改动过"},{"key":"s2","text":"在口径可信的前提下，把下降按设备、渠道、新老用户、下单各环节拆分，定位下降集中在哪一片"},{"key":"s3","text":"把定位到的那片用户与时间段，同发版记录、活动上下线、投放变更、外部事件逐条对齐时间"},{"key":"s4","text":"针对对齐后最可疑的那一个变更，做只改变该因素的对比：小流量回滚或保留对照组"},{"key":"s5","text":"用第 4 步的结果写出结论与影响范围，再决定是紧急修复、长期优化还是继续观察"}]'::jsonb, '{"keys":["s1","s2","s3","s4","s5"]}'::jsonb, '[]'::jsonb, '{"summary":"这条顺序的依赖关系是：数据可信是一切比较的前提，定位是时间对齐的前提，时间对齐是单因素验证的前提，验证是行动决策的前提。","steps":["第 1 步必须在最前：如果口径或管道变了，第 2 步拆出来的“下降”可能只是统计假象。","第 2 步在第 1 步之后：只有确认指标真实下滑，拆分才有意义；拆分把一个大问题缩成一片可处理的范围。","第 3 步在第 2 步之后：变更清单很长，只有把范围缩小到某类用户某个时段，才能判断哪条变更与它时间重合。","第 4 步在第 3 步之后：时间重合只给出嫌疑，不能排除共同原因，必须一次只改变一个因素才能定因。","第 5 步在最后：修复方式的取舍取决于已确认的原因和影响面，先动手会让结论失去可检验性。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过口径核对直接拆分，等于在没有共同标准的情况下比较数据。"},{"errorType":"correlation-as-causation","why":"只做第 3 步的时间对齐就下结论，把同时发生当成了因果。"}],"takeaway":"排子目标顺序时，先问“这一步的结论会不会被下一步推翻”，被推翻的那一步就要往前放。"}'::jsonb, array['问题拆解', '依赖顺序', '指标下滑排查']::text[], '原创题，围绕电商转化率下降的排查流程设计，五个步骤互不重叠。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dec-003', 1, 'problem-decomposition', array['subgoal-split', 'dependency-order']::text[], 3, 120, 'short-answer', null, '周报显示客服平均响应时间比上月更快，但团队普遍感觉最近更忙更累，有人据此主张“直接给客服加人”。请用三到四句话写出你会怎么拆解这个矛盾，并说明每一步为什么必须排在另一步之前。', null, null, null, '{"checkpoints":[{"id":"c1","label":"先核对两边的口径与来源","keywords":["口径","数据来源"],"weight":3,"required":true},{"id":"c2","label":"把“忙”拆成可测量的子指标","keywords":["子指标","拆成"],"weight":3,"required":true},{"id":"c3","label":"列出至少两个能同时解释两边的假设","keywords":["两个","假设"],"weight":2,"required":false},{"id":"c4","label":"安排一个能区分假设的最小观察","keywords":["区分","观察"],"weight":2,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"先核对口径：响应时间怎么计算、数据来源是哪张表、有没有把排队时长排除在外，团队感受则用具体记录还原，两类证据要分开保存。这一步必须最先做，否则两边可能根本不在同一把尺子上。再把“忙”拆成可测的子指标，例如排队量、单次会话轮次、加班时长、被打断次数。接着列出至少两个能同时解释两边的假设：简单问题被更快结单而复杂问题堆积，或者总人手不变但咨询集中到了少数时段。最后安排一个能区分这些假设的最小观察，比如按问题复杂度分层抽查一周，看耗时上升出现在哪一层。"}'::jsonb, '[]'::jsonb, '{"summary":"数据与感受冲突时，先拆的是“两边各自在测什么”，而不是“该加多少人”，否则会把口径差异误当成结论。","steps":["把冲突写成三个子目标：口径是否一致、感受对应哪些可测指标、什么证据能区分不同解释。","口径核对排在第一位，因为后两个子目标都以“两边比较成立”为前提。","把感受翻译成子指标，才能判断它究竟指向工作总量、难度结构还是时段分布。","至少构造两个同样成立的假设，避免只验证一个猜测。","最后设计分层观察：分层是关键，它让不同假设给出不同的预测，从而能被区分开。"],"commonMistakes":[{"errorType":"premise-misidentification","why":"把“团队觉得累”直接当作“人手不足”的证据，忽略了它可能由难度结构造成。"},{"errorType":"insufficient-evidence","why":"在没有分层数据的情况下选择长期且难以撤销的加人决定。"}],"takeaway":"两组证据打架时，先查它们是不是在同一把尺子上量的。"}'::jsonb, array['问题拆解', '事实与感受', '口径核对']::text[], '原创题，场景取自客服团队周报与团队感受冲突的复盘，要点与范文逐一对应。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dec-004', 1, 'problem-decomposition', array['subgoal-split', 'variable-control']::text[], 4, 160, 'ordering', null, '团队想做一个“自动整理会议纪要”的新功能，但资源有限，两周后就要决定是否投入全量开发。你要设计上线前的最小验证。请按依赖先后排列下列六个步骤。', null, null, '[{"key":"t1","text":"写下唯一的目标行为：用户愿意把生成的纪要保存下来或转发给同事"},{"key":"t2","text":"给这个目标行为定出可核对的判定口径与成功门槛数值，并写明低于多少就放弃"},{"key":"t3","text":"在门槛已确定的前提下，挑出成本最低但仍能触发该行为的验证形态，例如人工代做或静态原型"},{"key":"t4","text":"确定要控制的变量：只改变有无该功能这一点，入口位置、受邀人群与使用时段保持一致"},{"key":"t5","text":"把第 4 步的对照方式落成具体安排：样本量、观察时长与提前写好的终止条件"},{"key":"t6","text":"汇总数据并回到第 2 步的门槛，判定是投入全量、调整形态还是放弃"}]'::jsonb, '{"keys":["t1","t2","t3","t4","t5","t6"]}'::jsonb, '[]'::jsonb, '{"summary":"最小验证的顺序由“先定义再测量、先控制再执行、先设终止条件再收集数据”三条依赖决定。","steps":["第 1 步在最前：没有明确的目标行为，后面所有指标都可能换成另一个说法。","第 2 步依赖第 1 步：门槛要挂在这个行为上，否则成功与失败没有分界。","第 3 步依赖第 2 步：先有门槛才能判断某种粗糙形态是否仍能触发同一行为，人工代做就是这类低成本形态。","第 4 步依赖第 3 步：形态定了才知道要固定哪些条件，才能做到一次只改变一个因素。","第 5 步依赖第 4 步：样本与时长来自对照设计；终止条件必须预先写下，避免事后按结果找理由。","第 6 步依赖第 2 与第 5 步：判定标准与数据都齐了才谈得上去做取舍。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过判定口径直接做原型，结果出来后无法说清算不算成功。"},{"errorType":"conclusion-overreach","why":"在没有固定人群与时段的情况下，把一小群人的正反馈推广为可以全量投入。"}],"takeaway":"先写成功门槛和终止条件，再开始收集数据；顺序反了，数据会替你说出你想要的话。"}'::jsonb, array['问题拆解', '最小验证', '变量控制']::text[], '原创题，面向新功能上线前的低成本验证设计，六个步骤各占一个依赖环节。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dec-005', 1, 'problem-decomposition', array['subgoal-split', 'dependency-order']::text[], 4, 110, 'single-choice', null, '负责人说：“我们 App 留存太差了，你想办法提一下。”下面四种回应，哪种把这个问题拆解得最合理？', null, '[{"key":"A","text":"把它改写成几个可分别回答的子问题：哪些用户的留存差、差在哪个时间点、差到什么程度、此前做过哪些尝试及结果"},{"key":"B","text":"先列一批常见的提留存手段（签到、推送、新手引导），然后逐个试一试看哪个有效","errorType":"missing-reasoning-step","reason":"跳过定位环节，直接进入手段清单"},{"key":"C","text":"先问清负责人心里的目标数字，然后把达到这个数字当作唯一要回答的问题","errorType":"premise-misidentification","reason":"把对方的模糊表述当成问题的全部前提"},{"key":"D","text":"留存差说明产品定位有问题，先重新讨论定位，其他都不用查","errorType":"conclusion-overreach","reason":"在没有分群数据时把原因锁定到最宏观的一层"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"“留存太差”是一句评价而不是一个问题，拆解的作用是把它换成有明确判定标准的一组子问题。","steps":["先补齐“差”的可核对含义：与谁比、比哪段用户、比哪个时间窗。","按用户与时间分层，才能发现是整体下滑还是某一环节塌陷。","回看已有尝试，可以排除重复劳动并缩小候选原因范围。","以上三步都为“该改哪里”提供指向；直接进入手段清单会让每个方案都无法判断该不该采纳。","目标数字是判断标准之一，但不能替代定位过程，只盯数字容易用错手段达成它。"],"commonMistakes":[{"option":"B","errorType":"missing-reasoning-step","why":"在没有定位到流失环节的情况下逐个试手段，缺少把结果归因的中间环节。"},{"option":"C","errorType":"premise-misidentification","why":"把别人给出的数字当成问题本身，漏掉了需要被回答的那一部分。"},{"option":"D","errorType":"conclusion-overreach","why":"由一个笼统的负面评价直接跳到最宏观的因果结论。"}],"takeaway":"遇到形容词式的问题（太差、太慢、太高），第一步是把它翻译成带比较对象的数字。"}'::jsonb, array['问题拆解', '子目标拆解', '留存']::text[], '原创题，针对工作中常见的“形容词式需求”如何拆成可验证子问题。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dec-006', 1, 'problem-decomposition', array['subgoal-split', 'variable-control']::text[], 3, 110, 'multi-choice', null, '你把“两家商场门店客流下降”这件事拆成了若干子问题。按照“子问题之间要有依赖顺序、每个子问题要能独立判定”的要求，下列哪些做法是合格的？（选出所有合格做法）', null, '[{"key":"A","text":"先确认两家门店的客流计数方式与统计区间相同，再分别拆成进店量、试穿量、成交率三层"},{"key":"B","text":"把所有可能的原因一次列成清单，然后不分先后同时开始逐一验证，每条都花同样的力气","errorType":"missing-reasoning-step","reason":"缺少按可排除可能多少来安排先后的这一步"},{"key":"C","text":"每拆出一层就补一句“这一步用什么观察结果判定真假”，判定不了的往下再拆一层"},{"key":"D","text":"同一层的子问题保持互不重叠，且合起来能覆盖上一层那个问题"},{"key":"E","text":"先挑自己最有把握的那条分支验证，其他分支等这条得出结论后再看","errorType":"ignoring-counterexample","reason":"只检验支持自己猜测的分支，不主动找能推翻它的分支"}]'::jsonb, null, '{"keys":["A","C","D"]}'::jsonb, '[]'::jsonb, '{"summary":"合格的拆解要求两件事：每层子问题能被独立判定，层与层之间有明确先后；B 与 E 恰好破坏了这两点。","steps":["A 对：两家门店若要比较，计数口径相同是最前面的前提，否则分层结果没有可比性。","C 对：给每层配判定标准，才能确认这个子问题真的可独立回答，而不是一个更大的疑问。","D 对：同层互斥且穷尽，才不会出现两处重复验证或一片空白没被覆盖。","B 错：不分先后的均匀投入，放弃了“先做能排除最多可能的步骤”这一顺序原则。","E 错：优先验证自己有把握的分支，等于系统性地不去找反例。"],"commonMistakes":[{"option":"B","errorType":"missing-reasoning-step","why":"缺少为子问题排序这一环，导致资源平均铺开、排除速度慢。"},{"option":"E","errorType":"ignoring-counterexample","why":"只收集支持既定猜测的结果，可能推翻它的分支被排到最后甚至不做。"}],"takeaway":"拆完每一层都问两句：这一步怎么判定？判定不了是不是说明我拆得还不够细？"}'::jsonb, array['问题拆解', '子问题判定', '穷尽互斥']::text[], '原创题，用零售门店客流场景考查拆解合格性的两条判据。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dec-007', 1, 'problem-decomposition', array['dependency-order', 'variable-control', 'subgoal-split']::text[], 5, 170, 'short-answer', null, '一家公司同一周收到三个信号：投放获客成本上升、客服工单量上升、复购率下降。老板要求本周内定出主要原因。请用四五句话写出你的拆解方式、为什么按这个顺序做，以及哪一步最容易被跳过。', null, null, null, '{"checkpoints":[{"id":"c1","label":"先分别定义三个信号的口径","keywords":["口径","定义"],"weight":3,"required":true},{"id":"c2","label":"检查三者是否由同一个原因同时驱动","keywords":["同一个","共同原因"],"weight":3,"required":true},{"id":"c3","label":"按能排除多少可能来排序步骤","keywords":["排序","排除"],"weight":2,"required":false},{"id":"c4","label":"点出最易跳过的一步是控制变量","keywords":["控制变量","跳过"],"weight":2,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"第一步把三个信号各自的口径定义清楚：获客成本按哪个渠道算、工单按哪一类分、复购用哪个时间窗，口径不一致时三者无法比较。第二步检查三者是否由同一个原因同时驱动，例如一次调价可以推高工单又压低复购，那样三条线索其实只需验证一件事。第三步按“哪一步能排除最多可能”来排序：先做一两个小时就能整片排除的核对，把耗时最多的实验放在后面。第四步是整套流程里最容易被跳过的一步，也就是控制变量：不把渠道、人群和时间固定住，后续实验的结果仍然无法归因。最后为每一步写明判定标准、负责人和截止时间，按顺序同步结论。"}'::jsonb, '[]'::jsonb, '{"summary":"多个信号同时出现时，最有价值的拆解是判断它们是否共享同一个原因，这一步能一次性缩小候选范围。","steps":["把三个笼统信号各写成一句可判定的陈述，明确比较基准与时间窗。","先找共同原因，是因为一个假设若成立可以覆盖三条线索，比三条独立排查便宜得多。","在共同原因排查之后，再按排除效率给剩余分支排序：先做信息量最大的核对。","控制变量是归因的前提；缺少它，即便某个分支被验证，也无法排除同时发生的变化。","一周的时限要求为每一步设截止时间与放弃条件，避免在一条分支上耗尽时间。"],"commonMistakes":[{"errorType":"correlation-as-causation","why":"三条线索同周出现就认定它们互相导致，没有做共同原因检查。"},{"errorType":"missing-reasoning-step","why":"跳过控制变量直接做实验，结论仍会被同期其他变化解释掉。"}],"takeaway":"同时有几个异常时，先问它们是不是同一件事的三个侧面，再决定分别排查什么。"}'::jsonb, array['问题拆解', '共同原因', '控制变量']::text[], '原创题，用多信号同时恶化的经营场景训练拆解顺序与变量控制意识。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-dec-008', 1, 'problem-decomposition', array['subgoal-split', 'dependency-order', 'variable-control']::text[], 5, 180, 'open-response', null, '你负责的一个工具类小程序，“新用户首日完成关键动作的比例”最近两周明显下降。请在下方写出你的拆解方案：分成哪几个子问题、按什么顺序处理、每个子问题用什么证据判定，以及你需要控制哪些变量。', null, null, null, '{"scale":[{"score":0,"label":"没有拆解","criteria":"把下降当成一个整体问题，只给出一个笼统猜测或直接建议改界面，没有子问题。"},{"score":1,"label":"按对象分片","criteria":"把用户或页面分成若干片来查看，但没有说明这些片之间谁先谁后，也没有判定标准。"},{"score":2,"label":"给出依赖顺序","criteria":"明确写出先做哪一步，并说明它为什么必须在另一步之前，例如先确认口径再分渠道对比。"},{"score":3,"label":"为每个子问题配证据","criteria":"每个子问题都写清用什么观察结果判定真假，并提到需要核对埋点、统计窗等数据前提。"},{"score":4,"label":"补上变量控制与放弃条件","criteria":"进一步说明要固定哪些条件、一次只改变一个因素，并预先写明看到什么结果就放弃当前假设。"}],"guidance":"建议按“子问题清单 → 顺序与依赖理由 → 每个子问题的判定证据 → 需要控制的变量与放弃条件”四段来写，200 字以内即可。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"这道题考查的不是找到真因，而是能否把一个模糊的下滑现象拆成有先后、有判据、可控变量的子问题。","steps":["先界定问题：哪个指标、与哪个基准比、下降幅度是否超出正常波动。","第一层拆分按来源（投放与自然量）与设备版本分层，第二层按首日流程的各环节拆分。","顺序依赖：口径核对先于分片对比，分片对比先于变更对齐，对齐先于单因素验证。","每个子问题配一个判据，例如某一层的降幅是否显著大于其他层，避免只凭印象。","变量控制包括固定人群、时段与入口，一次只改变一个因素；同时预先写下放弃条件。"],"commonMistakes":[{"errorType":"hasty-generalization","why":"只看两三个用户的抱怨截图就宣布找到了原因。"},{"errorType":"conclusion-overreach","why":"由两周的下滑直接推出改版失败这类范围更大的结论。"}],"takeaway":"拆解是否合格，取决于每个子问题是否有一句“看到什么就算它成立或不成立”。"}'::jsonb, array['问题拆解', '开放题', '变量控制', '依赖顺序']::text[], '原创题，量表按常见的四种回答层级递进设计，供自评与可选的模型反馈使用。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-sta-001', 1, 'statistical-intuition', array['base-rate', 'conditional-probability']::text[], 4, 120, 'single-choice', null, '某体检项目面向普通人群筛查一种患病率为 1% 的疾病。该方法对真正患病者的检出率为 99%，对未患病者也有 5% 会误报阳性。随机筛出一名结果阳性的人，他真正患病的概率大约是多少？请按 10,000 人计算，结果保留一位小数。', null, '[{"key":"A","text":"约 99%，因为方法对患病者的检出率就是 99%","errorType":"base-rate-neglect","reason":"把检出患病者的概率倒过来当成患病者的比例"},{"key":"B","text":"约 16.7%，也就是差不多六分之一"},{"key":"C","text":"约 50%，因为结果只有阳性和阴性两种可能","errorType":"false-dilemma","reason":"把两种结果当成等概率的两选一"},{"key":"D","text":"约 95%，因为误报率只有 5%，剩下都是准确的","errorType":"premise-misidentification","reason":"把未患病者中被误报的比例当成阳性者中被误报的比例"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"1% 的基础概率让未患病者基数极大，5% 的误报在这里产生的假阳性人数远超真阳性，所以阳性者中真正患病的只约六分之一。","steps":["按 10,000 人拆开：患病者 10,000×1% = 100 人，未患病者 9,900 人。","算真阳性：100×99% = 99 人。","算假阳性：9,900×5% = 495 人。","阳性总数：99 + 495 = 594 人，其中真正患病 99 人。","求条件概率：99 ÷ 594 = 0.16667，保留一位小数为 16.7%，恰为六分之一。","对照直觉：把 99% 当成阳性者患病概率，方向就反了，它说的是患病者中有多少被测出。"],"commonMistakes":[{"option":"A","errorType":"base-rate-neglect","why":"99% 是患病者中被检出的比例，忽略 1% 患病率就把它换成了阳性者患病的比例。"},{"option":"C","errorType":"false-dilemma","why":"阳性和阴性是两类结果，但两类的人数并不相等，检出率与误报率也不同。"},{"option":"D","errorType":"premise-misidentification","why":"5% 的分母是 9,900 名未患病者而不是全部阳性者，直接把 100%−5% 当成准确率用错了前提。"}],"takeaway":"看到阳性别急，先算“真阳性有几人、假阳性有几人”，基础概率决定分母。"}'::jsonb, array['基础概率', '条件概率', '筛查检测']::text[], '原创题，参数为编写者设定（患病率 1%、检出率 99%、误报率 5%），结论 16.7% 由 99÷594 直接算得。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-sta-002', 1, 'statistical-intuition', array['sample-size']::text[], 2, 55, 'single-choice', null, '两家咖啡店的真实好评率都约为 80%。甲店当月只收到 8 条评价，乙店收到 800 条评价。只从评价条数看，下列判断最可靠的是哪一项？', null, '[{"key":"A","text":"甲店更容易出现极端比例，比如当月 8 条全是好评，或者显示的好评率不足六成"},{"key":"B","text":"乙店更容易出现极端比例，因为 800 条评价里出现异常情况的次数更多","errorType":"premise-misidentification","reason":"把评价总数多当成更容易出现极端比例的理由"},{"key":"C","text":"两店出现 100% 全好评的可能性相同，因为它们的真实好评率都是 80%","errorType":"equivocation","reason":"把平均水平相同偷换成波动幅度相同"},{"key":"D","text":"只要把甲店的评价条数补到 80 条，就能保证它的月度好评率正好显示为 80%","errorType":"conclusion-overreach","reason":"把样本量变大当成结果必然等于真实比例"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"比例本身的波动幅度随样本量增大而收窄，8 条评价时随机性很大，800 条评价时结果通常紧贴 80%。","steps":["先算甲店全好评：0.8 的 8 次方 = 0.16777216，即约 16.8% 的月份会显示 100%。","再算乙店全好评：0.8 的 800 次方约为 10 的负 77.5 次方，实际上不可能发生。","看低值一端：甲店 8 条中最多 4 条好评（即显示不足六成）的概率约 5.6%，而乙店 800 条要掉到 60% 相当于偏离均值约 14 个标准差，几乎为零。","由此得到一般规律：样本越小，观测比例围绕真实值的散布越大。","顺带纠正 D：增大条数只是让波动变小，不等于结果一定恰好等于真实比例。"],"commonMistakes":[{"option":"B","errorType":"premise-misidentification","why":"决定极端比例出现概率的是条数占比带来的波动幅度，不是异常情况的绝对发生次数。"},{"option":"C","errorType":"equivocation","why":"期望水平相同只说明长期平均，不说明单次观测的分散程度相同。"},{"option":"D","errorType":"conclusion-overreach","why":"样本量提高只收窄波动，任何有限样本都可能出现偏离。"}],"takeaway":"小样本的漂亮数字先打折：条数越少，越可能只是运气。"}'::jsonb, array['样本量', '极端比例', '消费评价']::text[], '原创题，两个比例数值由编写者按二项分布独立算得（0.8 的 8 次方约 16.8%，8 条中不超 4 条的概率约 5.6%）。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-sta-003', 1, 'statistical-intuition', array['average-vs-distribution']::text[], 3, 75, 'single-choice', null, '某外卖店铺某天 10 笔订单的配送分钟数为：10、12、14、16、18、18、20、22、26、124。页面只显示“本店平均配送 28 分钟”。关于这个平均数，下列哪项最准确？', null, '[{"key":"A","text":"平均 28 分钟说明大部分订单都在 28 分钟上下浮动","errorType":"equivocation","reason":"把平均数当成典型订单的取值"},{"key":"B","text":"10 笔里有 9 笔不超过 26 分钟，平均数主要被那笔 124 分钟的订单抬高"},{"key":"C","text":"中位数 18 分钟与平均数 28 分钟不一致，说明这张表一定统计错了","errorType":"missing-reasoning-step","reason":"忽略偏态分布下两数本就可能不同就断言有错"},{"key":"D","text":"124 分钟那一单必定是录入错误，删掉它之后重新平均才是正确做法","errorType":"insufficient-evidence","reason":"没有任何证据就把极端观测判定为错误数据"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"这 10 个数之和为 280，平均 28 分钟；中位数是第 5、6 个数的平均即 18 分钟。一笔 124 分钟的订单占当日总时长约 44%，把一个不典型的极端值写进了平均数。","steps":["核对总量：10+12+14+16+18+18+20+22+26+124 = 280，平均 280÷10 = 28 分钟。","核对中位数：排序后第 5 与第 6 个数都是 18，中位数 18 分钟，与平均数相差 10 分钟。","看分布形态：9 笔不超过 26 分钟，只有 1 笔 124 分钟，该笔占总时长 124÷280 ≈ 44%。","检查 D 的诱惑：若把 124 剔除，其余 9 笔平均为 156÷9 ≈ 17.3 分钟，接近中位数，但剔除本身需要证据（例如是否重复记录），不能默认极端值就是错。"],"commonMistakes":[{"option":"A","errorType":"equivocation","why":"平均数受极端值拉动，此处没有一笔订单落在 28 分钟附近。"},{"option":"C","errorType":"missing-reasoning-step","why":"右偏分布中平均数高于中位数是正常现象，两数不等本身不构成错误证据。"},{"option":"D","errorType":"insufficient-evidence","why":"题目没有提供该单为异常记录的任何线索，直接判定为录入错误缺乏依据。"}],"takeaway":"只给平均数时，追问中位数和有没有极端值，往往比平均值更有代表性。"}'::jsonb, array['平均数', '中位数', '分布形态']::text[], '原创题，10 个数据由编写者构造为满足均值 28、中位数 18 的一组右偏数据，各项计算已在解析中列出。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-sta-004', 1, 'statistical-intuition', array['survivorship-bias', 'average-vs-distribution']::text[], 4, 110, 'multi-choice', null, '某理财平台展示页写着：“平台上存续的 12 只基金过去三年平均年化收益 9.2%。”另据公开资料，同期该平台共发行过 20 只同类基金，其中 8 只因业绩长期垫底被清盘合并，清盘基金的收益未出现在展示名单中。关于这条宣传，下列哪些说法是站得住的？（选出所有正确的）', null, '[{"key":"A","text":"9.2% 这个平均数只覆盖存续的 12 只，被清盘的 8 只在统计之前就已经被排除"},{"key":"B","text":"把 9.2% 当成“在这平台买这类基金三年的平均收益”，会高估真实结果"},{"key":"C","text":"凭题中这些数字就能算出全部 20 只基金真实的平均年化收益","errorType":"missing-reasoning-step","reason":"缺少被清盘 8 只基金的收益率，无法补齐总平均"},{"key":"D","text":"只要把展示名单从 12 只扩到 20 只，这个平均数就一定不再有偏","errorType":"conclusion-overreach","reason":"把扩大名单当成消除系统性筛选的充分条件"},{"key":"E","text":"让 20 只变成 12 只的规则是“业绩差就清盘”，这条筛选规则本身就是偏差来源"}]'::jsonb, null, '{"keys":["A","B","E"]}'::jsonb, '[]'::jsonb, '{"summary":"幸存者偏差的关键不在样本数少，而在于进入样本的规则与结果相关：业绩越差越容易被剔除，剩下的自然偏高。","steps":["先核对数量：发行 20 只，清盘 8 只，存续 20−8 = 12 只，展示名单只有 12 只。","看清筛选规则与结果的关系：清盘的依据正是业绩垫底，因此被剔除的样本系统性地偏低。","区分两件事：平均数本身算得没错，错在把它当作全体投资者的期望收益。","说明 C 缺什么：不知道 8 只清盘基金各自的三年收益，20 只的总平均无法求出。","说明 D 的问题：把名单补全只是补数据，若仍用“存续期间”这类口径来平均，筛选偏差依然存在；更稳妥的做法是按投资者实际买入时点逐笔计算，并同时展示清盘情况。"],"commonMistakes":[{"option":"C","errorType":"missing-reasoning-step","why":"总平均需要全部 20 只的收益数据，题中只给了 12 只的均值。"},{"option":"D","errorType":"conclusion-overreach","why":"扩名单是必要条件而非充分条件，口径与筛选规则仍需一并修正。"}],"takeaway":"看到“存续产品的平均成绩”，先问被删掉的那部分去哪了。"}'::jsonb, array['幸存者偏差', '平均数', '公司报表']::text[], '原创题，基金只数由编写者设定为 20、8、12 的自洽关系，用于训练识别按结果筛选样本的宣传话术。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-sta-005', 1, 'statistical-intuition', array['sample-size', 'confounder']::text[], 3, 60, 'true-false', null, '甲医院一年完成某类手术 1,200 台，术后并发症率 2%；乙医院同期只做 40 台，并发症率 5%。仅凭这两个数字，就能判定甲医院在这类手术上更安全。', null, null, null, '{"value":false}'::jsonb, '[]'::jsonb, '{"summary":"乙医院 40 台的 5% 只对应 2 例并发症，这种小样本的比例本身波动很大；两院收治的病情风险构成也可能不同，因此不能仅凭这两个数字定论。","steps":["把百分比还原成例数：甲医院 1,200×2% = 24 例，乙医院 40×5% = 2 例。","评估小样本的波动：如果乙医院的真实并发症率也是 2%，40 台中期望只有 0.8 例，而出现不少于 2 例的概率按二项分布估算约 19%，接近五分之一，并不罕见。","指出分母之外还有一层：两家医院接诊的重症比例、年龄构成、合并症情况可能不同，这些会同时推高并发症率与手术难度。","说明需要什么才可比：按病情严重程度分层比较，并给出区间而不是只看两个点估计。"],"commonMistakes":[{"errorType":"base-rate-neglect","why":"只看两个比率的大小，不看各自的分母规模与由此带来的波动。"},{"errorType":"hasty-generalization","why":"由 40 台这一小批手术的结果推广到该院整体水平。"},{"errorType":"correlation-as-causation","why":"把并发症率差异直接归因于医院技术水平，忽略了病情构成这个混淆变量。"}],"takeaway":"比较两个百分比之前，先把它们背后的例数和分母差异摆出来。"}'::jsonb, array['样本量', '比率与例数', '混淆变量']::text[], '原创题，例数与概率由编写者核算（1,200×2%=24 例、40×5%=2 例，真实率 2% 时 40 台不少于 2 例的概率约 19%）。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-sta-006', 1, 'statistical-intuition', array['survivorship-bias', 'average-vs-distribution', 'sample-size']::text[], 5, 160, 'short-answer', null, '一款 App 首月收到 2,000 条评价，平均分 3.4 星。第二个月商店改成只有注册满 7 天且有消费记录的用户才能评价，评价数降到 120 条，平均分升到 4.6 星。运营会上有人说：“改版让用户体验提升了 1.2 星。”请用两三句话指出这个说法的问题。', null, null, null, '{"checkpoints":[{"id":"c1","label":"指出两个平均数的人群口径不同","keywords":["口径","人群"],"weight":3,"required":true},{"id":"c2","label":"指出平均数掩盖了分布","keywords":["分布","平均数"],"weight":2,"required":false},{"id":"c3","label":"提出同口径分组对照","keywords":["对照","自我选择"],"weight":2,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"3.4 星与 4.6 星来自不同人群，不能直接相减成体验提升了 1.2 星。第一，评价者口径变了：改版后只有注册满七天且有消费记录的人能写评价，这批人本来就更容易满意，120 条与 2000 条统计的不是同一群用户，愿意评价本身也是一种自我选择。第二，平均数掩盖了分布：应当看各星级的人数，确认差评是消失还是仅仅被挡在门外。第三，要判断改版的影响，需要在改版前后用同一口径、同一人群分组对照，再看分布差异，才能把 1.2 星中属于体验改善的部分与属于谁在评价的部分分开。"}'::jsonb, '[]'::jsonb, '{"summary":"改版同时改变了谁能评价，等于换了统计人群；1.2 星的差距里混着筛选效应，不能整块算作体验提升。","steps":["先算量级变化：评价数从 2,000 条降到 120 条，只剩 120÷2,000 = 6% 的规模。","指出分母换了：新规则筛掉注册用户与无消费记录者，这两类人通常体验较差，因此 4.6 星的条件人群与 3.4 星不同。","指出平均数的局限：3.4 与 4.6 都是单一集中趋势，看不到一星占比是否被截断；分布形态才反映体验构成。","给出可比做法：把改版前后都限定为“注册满 7 天且有消费记录”的人群重新计算平均分，并分别报告各星级的占比。","补充一个可核对的数字：若 120 条平均分 4.6，则总星数约为 120×4.6 = 552，与 2,000×3.4 = 6,800 相比，星数总量下降主要来自评价人数减少。"],"commonMistakes":[{"errorType":"base-rate-neglect","why":"忽略能评价的人群在总体中只占一小部分，直接把两次的平均分对齐比较。"},{"errorType":"correlation-as-causation","why":"把“改版之后分数升高”写成“改版使体验升高”，跳过了筛选效应这一替代解释。"},{"errorType":"equivocation","why":"把“平均分变化”与“用户体验变化”当成同一件事，1.2 星这个数字的含义在两处并不相同。"}],"takeaway":"规则改动前后对比任何平均值，都要先确认统计的是同一群人。"}'::jsonb, array['幸存者偏差', '口径变化', '消费评价']::text[], '原创题，场景取自应用商店评价规则改版，120÷2,000=6% 与星数总量估算均由编写者核算。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-sta-007', 1, 'statistical-intuition', array['average-vs-distribution', 'survivorship-bias', 'sample-size']::text[], 3, 100, 'ordering', null, '某招聘页面写着“本岗位在职人员平均月薪 15,000 元”，数据来自平台上 300 条在职者自报薪资。你要判断这个数字能否代表一份普通工作的收入。请按最合理的先后顺序排列核查步骤。', null, null, '[{"key":"w1","text":"确认“平均月薪”的口径：是否含奖金与补贴、是税前还是税后、按多少人计算"},{"key":"w2","text":"查清这 300 条自报数据的来源：谁愿意报、谁没有报，在职者与离职者是否被排除"},{"key":"w3","text":"索取分布而不止平均数：看 25%、50%、75% 分位数以及薪资的最高与最低值"},{"key":"w4","text":"与独立来源对照：查同城市同岗位公开发布的薪资中位数区间"},{"key":"w5","text":"给出暂时结论：说明 15,000 元这个数最多能支持到哪一步，还有哪些不确定"}]'::jsonb, '{"keys":["w1","w2","w3","w4","w5"]}'::jsonb, '[]'::jsonb, '{"summary":"核查顺序要按依赖关系来：先固定定义，再弄清样本是谁，再看分布形态，然后与外部独立数据比较，最后才收敛结论。","steps":["口径不固定时，含不含奖金的两个平均数无法比较，所以第一步必须是定义核对。","自报薪资存在双重筛选：愿意填的人与仍在岗的人都不代表全体，这一步决定后面所有解释。","平均数会被少数高薪拉高，因此需要分位数与中位数才能判断 15,000 元是不是典型收入。","独立来源的作用是提供不受同一筛选机制影响的对照，缺了它只能就数据论数据。","最后一步把结论强度写清楚，并保留仍未解决的不确定项。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过样本来源直接进入计算，会让精确的分位数建立在有偏的 300 条自报数据上。"},{"errorType":"base-rate-neglect","why":"不查总体中在职者与离职者的构成，就难以判断样本代表性，容易把局部人群当整体。"}],"takeaway":"核查一个宣传用的平均数：先问口径，再问谁被统计进去，最后问分布长什么样。"}'::jsonb, array['平均数与分布', '幸存者偏差', '招聘数据']::text[], '原创题，场景取自招聘页面的薪资宣传，用于训练把统计口径核查排成有依赖顺序的步骤。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-sta-008', 1, 'statistical-intuition', array['base-rate', 'survivorship-bias', 'conditional-probability']::text[], 5, 180, 'open-response', null, '一家求职训练营宣传：“报名的 50 名学员中，45 人在三个月内拿到录用通知，成功率 90%；而同专业应届毕业生平均落实率只有 40%。”请评价这段宣传：90% 与 40% 这两个数字能比吗？你还想知道哪些信息？', null, null, null, '{"scale":[{"score":0,"label":"接受宣传","criteria":"认为 90% 与 40% 的差距已经证明训练营有效。"},{"score":1,"label":"仅表怀疑","criteria":"感觉宣传夸大，但说不出比较中的具体问题在哪。"},{"score":2,"label":"指出分母与定义不同","criteria":"能说明 50 名学员是自我选择的群体，两个 40% 与 90% 统计的不是同一件事。"},{"score":3,"label":"补出关键的口径缺口","criteria":"进一步追问三个月内未坚持完成、中途退出或未被计入统计的人有多少。"},{"score":4,"label":"给出可比的验证方案","criteria":"还能提出按报名时背景分层、以同类人群同期落实率为基线的可比方案，并写明自己的不确定处。"}],"guidance":"先分别说清 90% 与 40% 的分子与分母，再列出退出者去了哪里，最后设计一个能同口径比较的方案并标注剩余不确定。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"45÷50 = 90% 与全体毕业生 40% 的落实率是两个不同群体的条件概率；再加上报名筛选与中途退出，三处口径都不一致。","steps":["核对算出的部分：45÷50 = 0.9，即 90%，其中未拿到通知的是 5 人，50−45 = 5。","比较两个分母：90% 的分母是主动报名训练营的人，40% 的分母是同专业全体毕业生，前者经过求职意愿与经济条件的双重筛选。","检查时间条件：一个是“报名后三个月内”，一个是毕业季平均落实率，两个条件概率的时间窗口不同。","追查看不见的样本：是否有报名后退费、缺席或未完成的人被排除在 50 人之外，这是典型的幸存者偏差位置。","给出可比方案：把学员按学历背景、实习经历、目标城市分层，与同层毕业生在相同时间窗内的落实率比较，并同时报告总报名人数与最终计入统计的人数。"],"commonMistakes":[{"errorType":"base-rate-neglect","why":"用 90% 的亮眼比例压过 40% 的总体基线，却忽略两个比例的群体基础并不相同。"},{"errorType":"hasty-generalization","why":"由 50 人的样本推广到该方法对任何毕业生都有效。"},{"errorType":"conclusion-overreach","why":"从落实率差异直接跳到“训练营造成了这份提高”，省略了自选择与退出者的处理。"}],"takeaway":"两个百分比比较前，先把各自的分子、分母和时间窗口写在纸上。"}'::jsonb, array['基础概率', '条件概率', '教育产品宣传', '开放题']::text[], '原创题，场景取自求职训练营的宣传话术，45÷50=90% 与 50−45=5 由编写者核对，量表按回答层级设计供自评使用。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-tru-001', 1, 'truth-teller-puzzles', array['truth-table', 'validity-vs-truth']::text[], 3, 80, 'single-choice', '行政确认：拿钥匙的人就在当时在场的三人之中，且三人各说了一句。', '办公室备用钥匙不见了。在场三人的说法：老周：“不是我拿的。”小李：“是老陈拿的。”老陈：“小李在说谎。”已知三人中只有一个人说了真话。谁拿了钥匙？', null, '[{"key":"A","text":"是老周拿的，说真话的人是老陈"},{"key":"B","text":"是老陈拿的，说真话的人是小李","errorType":"missing-reasoning-step","reason":"漏掉小李与老陈之间必有一真一假"},{"key":"C","text":"是小李拿的，两人说真话一人说假话","errorType":"premise-misidentification","reason":"没有检查该组合下真话人数是否为 1"},{"key":"D","text":"条件不足，无法确定是谁拿的","errorType":"insufficient-evidence","reason":"把可以逐一排除的情形当成了无法排除"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"小李和老陈的话互相矛盾，必有一真一假；唯一的一句真话就在这两人之间，所以老周说假话，即钥匙是他拿的。","steps":["注意到小李说“是老陈拿的”，老陈说“小李在说谎”，两句话不能同真也不能同假。","既然三人中只有一句真话，而这一句已经在小李与老陈之中，老周那句必定为假。","老周说“不是我拿的”为假，因此拿钥匙的是老周。","回代检验：老周拿的场合，老周假、小李假（不是老陈）、老陈真，真话数正好为 1。","再检验另两种可能：老陈拿则老周与小李同真（2 句真话）；小李拿则老周与老陈同真（2 句真话），都与条件冲突。"],"commonMistakes":[{"option":"B","errorType":"missing-reasoning-step","why":"直接采信小李的话的内容，跳过了矛盾对与真话人数限制这两步。"},{"option":"C","errorType":"premise-misidentification","why":"该组合下会出现两句真话，与“只有一人说真话”的限制不符。"},{"option":"D","errorType":"insufficient-evidence","why":"三种可能里有两种被条件直接排除，结论是可确定的。"}],"takeaway":"先找互相矛盾的那两句，把真话名额锁定在它们内部，剩下的话真假立刻可判。"}'::jsonb, array['真假话', '矛盾对', '职场核实']::text[], '原创题，场景取自办公室物品失踪后的内部核实，用于训练矛盾句定位法。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-tru-002', 1, 'truth-teller-puzzles', array['truth-table', 'self-reference']::text[], 4, 100, 'single-choice', '采购会上两家供应商各说一句，每句话要么为真要么为假，没有第三种情况。', '供应商甲说：“我和乙说的都是真话。”供应商乙说：“甲在说假话。”据此可以推出什么？', null, '[{"key":"A","text":"甲说真话，乙说假话","errorType":"missing-reasoning-step","reason":"代入后乙的话会变成真，未做这一步检验"},{"key":"B","text":"甲说假话，乙说真话"},{"key":"C","text":"两人说的都是假话","errorType":"premise-misidentification","reason":"忽略了此时乙那句“甲在说假话”本身成了真话"},{"key":"D","text":"无法判断谁说真话谁说假话","errorType":"insufficient-evidence","reason":"四种赋值都能逐一检查，其实只剩一种成立"}]'::jsonb, null, '{"keys":["B"]}'::jsonb, '[]'::jsonb, '{"summary":"假设甲为真就要求乙也为真，可乙的内容恰好否认甲，矛盾；所以甲必假，于是乙的内容成立，乙为真，代回后一切自洽。","steps":["列出四种赋值：(真,真)、(真,假)、(假,真)、(假,假)。","(真,真)：甲的内容成立，但乙说“甲在说假话”此时为假，与乙为真冲突，排除。","(真,假)：甲的内容要求乙也说真话，与乙为假冲突，排除。","(假,假)：乙说“甲在说假话”此时恰好符合事实，应为真，与乙为假冲突，排除。","(假,真)：乙的内容与甲为假一致；甲那句“两人皆真”因甲自己为假而落空，与其为假一致，唯一成立。"],"commonMistakes":[{"option":"A","errorType":"missing-reasoning-step","why":"只检查了甲那句话，忘了同时检查乙那句话在该假设下的真假。"},{"option":"C","errorType":"premise-misidentification","why":"“甲在说假话”在甲确实说假话时本身就是真话，不能一并算成假。"},{"option":"D","errorType":"insufficient-evidence","why":"赋值空间只有四种且都能穷尽检验，不构成无法判断。"}],"takeaway":"遇到互相评价对方的话，把真假四种组合逐一代回去，比凭直觉快也更可靠。"}'::jsonb, array['真假话', '假设法', '商务沟通']::text[], '原创题，场景取自采购会上两家供应商的互相指认，用于训练赋值穷尽法。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-tru-003', 1, 'truth-teller-puzzles', array['self-reference', 'truth-table']::text[], 2, 40, 'true-false', null, '一张卡片正面写着“背面的话是真的”，背面写着“正面的话是假的”。请判断：这两句话可以同时为真。', null, null, null, '{"value":false}'::jsonb, '[]'::jsonb, '{"summary":"若正面为真则背面为真，而背面说正面为假，直接冲突；所以两者不能同真，该说法不成立。","steps":["设正面为真：正面断言背面是真的，于是背面也为真。","背面断言正面的话是假的，这与“正面为真”矛盾，假设失败。","再设正面为假：那么“背面是真的”这一断言不成立，背面应为假；可背面说“正面是假的”恰好符合事实，又该为真，仍然矛盾。","这是一个无法稳定赋值的自指结构，其中“同真”这种情形首先被排除。","因此“可以同时为真”的说法判为否。"],"commonMistakes":[{"errorType":"circular-reasoning","why":"用正面证明背面为真，再用背面证明正面为真，等于把待证的结论放进前提。"},{"errorType":"equivocation","why":"把“这句话为真”与“这句话所描述的内容成立”混成了同一件事。"}],"takeaway":"处理自指的说法，先只假设一种赋值并推到矛盾，不要同时接受两边。"}'::jsonb, array['自指', '真假话', '赋值检验']::text[], '原创题，场景取自益智卡片游戏，针对自指句的赋值冲突。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-tru-004', 1, 'truth-teller-puzzles', array['truth-table', 'exhaustive-cases']::text[], 5, 145, 'single-choice', '名单已定，只知道甲、乙、丙三人里恰好有两人入选，三人各说了一句。', '评优名单上有甲、乙、丙中的恰好两人。三句话：甲：“名单上有我。”乙：“名单上没有丙。”丙：“名单上没有甲，而且名单上有我。”已知三句话中恰好两句为真。谁在名单上？', null, '[{"key":"A","text":"名单上是甲和乙，丙说的是假话"},{"key":"B","text":"名单上是甲和丙","errorType":"missing-reasoning-step","reason":"没有把“恰好两句为真”拿去逐个组合检验"},{"key":"C","text":"名单上是乙和丙","errorType":"premise-misidentification","reason":"误以为丙的两半可以只算一句真话"},{"key":"D","text":"三种两两组合都满足条件，无法确定","errorType":"ignoring-counterexample","reason":"两种组合已被真话人数限制排除"}]'::jsonb, null, '{"keys":["A"]}'::jsonb, '[]'::jsonb, '{"summary":"三种入选组合都要代入“恰好两句为真”这一限制：只有“甲和乙”给出两句真话，另两种都只剩一句。","steps":["把三句话写成条件：甲＝名单含甲；乙＝名单不含丙；丙＝名单不含甲 且 名单含丙。","组合一（甲、乙入选）：甲真，乙真（丙不在名单），丙的前半句“没有甲”为假故整句为假，真话数 2，符合。","组合二（甲、丙入选）：甲真，乙假（丙在名单），丙因“没有甲”为假而整句假，真话数 1，不符合。","组合三（乙、丙入选）：甲假，乙假（丙在名单），丙“没有甲且有我”为真，真话数 1，不符合。","唯一存活的是组合一，所以名单上是甲和乙，说假话的是丙。"],"commonMistakes":[{"option":"B","errorType":"missing-reasoning-step","why":"该组合下只有甲一句真话，与题目要求的两句差一步就被放过了。"},{"option":"C","errorType":"premise-misidentification","why":"丙那句是“而且”连接的合取，一半为假整句就为假。"},{"option":"D","errorType":"ignoring-counterexample","why":"两种组合已被真话人数限制排除，不能算作同样可接受。"}],"takeaway":"没有明显矛盾句时，就按题目给的“恰好几句为真”把所有可能穷举一遍。"}'::jsonb, array['真假话', '穷尽情形', '职场评优']::text[], '原创题，场景取自公司年终评优名单的传闻，用于训练列表穷举法。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-tru-005', 1, 'truth-teller-puzzles', array['truth-table', 'validity-vs-truth']::text[], 4, 120, 'multi-choice', '技术负责人确认：补丁是三人中的一人偷偷发的，说假话的人正是发补丁的人，另外两人说的都是真话。', '线上出现一版没人认领的补丁。三句话：小冯：“不是我发的。”小杜：“不是我发的。”小高：“小冯说的是真话。”下面哪些判断必然为真？（选出所有必然为真的）', null, '[{"key":"A","text":"偷偷发补丁的是小杜"},{"key":"B","text":"小杜说的是一句假话"},{"key":"C","text":"小冯说的是真话"},{"key":"D","text":"小高说的是假话","errorType":"missing-reasoning-step","reason":"没检查小高这句话在每种假设下是否自洽"},{"key":"E","text":"条件不足，无法确定是谁发的补丁","errorType":"insufficient-evidence","reason":"三种假设逐个排除后其实只剩一个"}]'::jsonb, null, '{"keys":["A","B","C"]}'::jsonb, '[]'::jsonb, '{"summary":"约束是“发布者说假话、其余两人说真话”。假设发布者是小冯或小高都会让规则自相矛盾，只有小杜发布时三句话真假正好匹配。","steps":["假设小冯发的：他必须说假话，可他说“不是我发的”确实是假话，符合；那么小高也必须说真话，而小高说“小冯说的是真话”为假，矛盾。","假设小高发的：小冯与小杜都说真话，小冯“不是我发的”为真，于是小高那句“小冯说的是真话”也成了真话，与发布者必须说假话冲突。","假设小杜发的：小冯真、小杜假、小高肯定小冯故也为真，恰好只有发布者一人说假话，完全一致。","所以必然为真的是：发补丁的是小杜（A）、小杜说假话（B）、小冯说真话（C）。","D 与检验结果相反；E 低估了“发布者说假话”这条规则的排除力。"],"commonMistakes":[{"option":"D","errorType":"missing-reasoning-step","why":"把小高的话当成孤立断言，没接到“非发布者都说真话”的规则上。"},{"option":"E","errorType":"insufficient-evidence","why":"三种可能里两种直接产生矛盾，剩下的一种是唯一解。"}],"takeaway":"带有“身份决定真假”的规则时，把每种身份假设代入，看有没有违背规则的那一句。"}'::jsonb, array['真假话', '身份约束', '工作协作']::text[], '原创题，场景取自研发团队追查一次未登记的线上发布，用于训练身份与真假绑定的推理。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-tru-006', 1, 'truth-teller-puzzles', array['truth-table', 'exhaustive-cases']::text[], 3, 115, 'short-answer', null, '校招内推名额只剩一个，最终一定给了甲、乙、丙中的一人。三句话：甲：“我没拿到名额。”乙：“丙没拿到名额。”丙：“我拿到了名额。”已知三句话中恰好一句为真。请写出：哪两句话构成矛盾？名额最终给了谁？为什么？（两三句话）', null, null, null, '{"checkpoints":[{"id":"c1","label":"指出乙与丙互相矛盾","keywords":["矛盾","必有一真一假"],"weight":3,"required":true},{"id":"c2","label":"用真话名额锁定甲为假","keywords":["一句真话","落在"],"weight":2,"required":true},{"id":"c3","label":"给出最终归属","keywords":["给了甲","甲拿到"],"weight":3,"required":true},{"id":"c4","label":"回代检验其余组合","keywords":["检验","两句真话"],"weight":1,"required":false}],"correctRatio":0.8,"partialRatio":0.5,"modelAnswer":"乙说“丙没拿到”与丙说“我拿到了”构成矛盾，两句必有一真一假。既然三句话里恰好一句真话，这句真话就落在乙和丙之间，所以甲那句必定为假，“我没拿到”为假就推出名额给了甲。检验：名额给甲时甲假、乙真、丙假，正好一句真话；若给乙则甲乙同真，若给丙则甲丙同真，都出现两句真话。"}'::jsonb, '[]'::jsonb, '{"summary":"乙与丙是一对矛盾句，真话名额被它们占满，甲必假，从而名额属于甲；再回代三种归属即可确认唯一。","steps":["识别矛盾：乙断言丙没拿到，丙断言自己拿到，两者不能同真也不能同假。","用上限制：三句里恰好一句为真，这一真必在乙丙之中，因此甲为假。","由甲为假得事实：甲说“我没拿到”是假的，即名额给了甲。","回代检验：给甲时真话数为 1，符合；给乙时为 2，给丙时为 2，均不符合。","结论唯一：名额给了甲，说真话的是乙。"],"commonMistakes":[{"errorType":"premise-misidentification","why":"把甲的话当成真话起点，就会误推到乙或丙身上。"},{"errorType":"missing-reasoning-step","why":"看出矛盾却没接上“恰好一句为真”的限制，结论仍落在原地。"}],"takeaway":"先定位矛盾句，再用真话名额判定其余句子的真假，最后一定回代检验。"}'::jsonb, array['真假话', '矛盾对', '升学求职']::text[], '原创题，场景取自校招内推名额的传闻，用于训练把矛盾句与数量限制结合写出完整推理。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-tru-007', 1, 'truth-teller-puzzles', array['dependency-order', 'truth-table']::text[], 3, 95, 'ordering', null, '部门要查清共享文档是夜里被谁改动的，四个人各说了一句，已知恰好一人说了真话。按最合理的先后顺序排列下列步骤。', null, null, '[{"key":"s1","text":"把四句话逐条抄下来，写清每句断言的事实是什么"},{"key":"s2","text":"找出其中互相矛盾的两句话，确定它们必有一真一假"},{"key":"s3","text":"用“恰好一人说真话”的限制推出其余两句话都为假"},{"key":"s4","text":"由为假的句子反推事实，缩小到唯一的改动者"},{"key":"s5","text":"把结论代回四句话逐条验证，确认恰好只剩一句为真"}]'::jsonb, '{"keys":["s1","s2","s3","s4","s5"]}'::jsonb, '[]'::jsonb, '{"summary":"解真假话问题的稳定顺序是：先把陈述形式化，再定位矛盾句，然后用真话人数限制推剩余真假，最后回代验证。","steps":["不逐条抄下来，就会把说话人和内容混在一起，后面无法判断谁和谁矛盾。","矛盾句给出一真一假的必然配对，是信息量最大的一环，必须优先做。","真话人数限制只有接在矛盾对之后才能立刻定死其余句子的真假。","由已知为假的句子反推事实，是唯一能把真假转成事件归属的一步。","回代验证用来发现自己推理中的漏项，也用来确认答案唯一，所以放在最后。"],"commonMistakes":[{"errorType":"missing-reasoning-step","why":"跳过矛盾定位直接猜事实，往往在两种可能之间来回摇摆。"},{"errorType":"premise-misidentification","why":"把“恰好一人说真话”记成“恰好一人说假话”，全部真假关系就反了。"}],"takeaway":"先形式化、再找矛盾、后用数量限制，最后一定回代检验。"}'::jsonb, array['真假话', '步骤顺序', '工作核实']::text[], '原创题，场景取自团队追查共享文档的夜间改动记录，用于整理固定的解题顺序。', 'validated', true, 0.2, 'content-v1.0', 1),
  ('ex-tru-008', 1, 'truth-teller-puzzles', array['truth-table', 'conclusion-identification', 'implicit-premise']::text[], 5, 165, 'open-response', null, '同事群里争论：老李先说“我从来不加班”，第二天夜里他又在群里发“今天加班到十点”。小张据此断定：“他这两句里必有一句是假话，所以老李以后说的话都不能信。”请评价小张的推理：哪一步是站得住的，哪一步跳了？换成你，会怎么下结论？', null, null, null, '{"scale":[{"score":0,"label":"接受整体判断","criteria":"认为老李说话不算数，以后他的任何话都不必当真。"},{"score":1,"label":"只觉语气过重","criteria":"感觉最后一句说得太狠，但说不出问题出在哪一步。"},{"score":2,"label":"分清两步结论","criteria":"能指出“两句必有一假”是真的逻辑结论，而“以后都不能信”是另一步推断。"},{"score":3,"label":"补出隐含前提","criteria":"进一步写出后一步依赖的未说明前提，例如“一个人说过一次假话，之后说的每句话都为假”。"},{"score":4,"label":"给出可操作的结论","criteria":"还能按事情的可逆性与代价分层：关键信息另行核实，日常信息可参考，并留出他改口的可能。"}],"guidance":"先把两步结论拆开，分别问它们靠什么成立；再检查后一步需要的前提是否可靠，最后给出一个分层的处理方式。","selfAssessed":true}'::jsonb, '[]'::jsonb, '{"summary":"“从来不加班”与“今天加班到十点”不能同真，所以至少一句为假，这是有效的演绎；但由一次失信推出他以后所有话都不可信，跨了范围也跨了强度。","steps":["把两句对照：前者是全称时间断言，后者承认一次加班，两者不可同真，因此“至少一句为假”成立。","小张的第二步是从“这组话里有假”跳到“他之后的每句话都为假”，中间需要一条关于人格与概率的隐含前提。","这条隐含前提本身经不起检验：说过一次假话的人，其余陈述为真的比例并不会归零。","更稳的结论按代价分层：涉及排班、承诺等不可逆事项要另找凭据，日常闲聊仍可参考他的说法。","同时保留可修正空间：如果老李解释了口径（例如“从来”指本月），第一句也可能重新变得可信。"],"commonMistakes":[{"errorType":"conclusion-overreach","why":"由一次自相矛盾推出以后所有话都不可信，结论远超证据范围。"},{"errorType":"ad-hominem","why":"用对老李这个人的评价替代了对每句话证据的评估。"},{"errorType":"false-dilemma","why":"把处理办法压成“全信”或“全不信”两种，忽略了按代价分层的做法。"}],"takeaway":"从“某句话是假的”到“这个人不能信”之间，需要一条关于概率的额外前提，先把它写出来再判断。"}'::jsonb, array['真假话', '开放题', '同事沟通', '论证评估']::text[], '原创题，场景取自同事群里的日常争论，量表按从整体接受到分层处理的常见回答层级设计。', 'validated', true, 0.2, 'content-v1.0', 1)
