  grading_order_tolerance = excluded.grading_order_tolerance,
  seeded_from = excluded.seeded_from,
  content_schema_version = excluded.content_schema_version
;

-- Retire rows that a previous seed of the same tag inserted but the current
-- content no longer contains (the local equivalent is the stale-row pass in
